export const recipes: CountryRecipe[] = [{"country":"jp","id":"takoyaki","slug":"osaka-takoyaki","title":{"zh-TW":"大阪道頓堀章魚燒","en":"Osaka Dotonbori Takoyaki","ja":"大阪道頓堀 たこ焼き","ko":"오사카 도톤보리 타코야키","th":"ทาโกะยากิสูตรต้นตำรับโอซาก้า"},"subtitle":{"zh-TW":"外皮微酥、內餡流心燙口、柴魚片遇熱曼妙跳舞","en":"Crispy outside, creamy molten dashi core with dancing bonito flakes","ja":"外はカリッと中はとろっとろ、熱々出汁の旨味広がる本場大阪の味","ko":"겉은 바삭 속은 촉촉하게 녹아내리는 육수 품은 정통 타코야키","th":"กรอบนอกนุ่มใน เนื้อปลาหมึกชิ้นโตกับปลาแห้งเต้นระบำ"},"tagline":{"zh-TW":"大阪靈魂排隊國民美食，在家用烤盤或氣炸鍋也能完美重現！","en":"Iconic Kansai soul food, perfected for home pans and air fryers.","ja":"関西のソウルフード！ホットプレートやノンフライヤーでも再現可能。","ko":"오사카를 대표하는 국민 간식, 집에서도 바삭하게 완성!","th":"อาหารยอดนิยมอันดับหนึ่งของโอซาก้า ทำทานเองได้ง่ายๆ ที่บ้าน"},"heroImage":"/images/jp/takoyaki-hero.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":15,"defaultServings":2,"caloriesPerServing":320,"category":"konamono","dietaryTags":["classic","pescatarian"],"supportedCookware":["traditional","takoyakiPlate","airFryer"],"culture":{"originRegion":{"zh-TW":"大阪府西成區・道頓堀 (Osaka)","en":"Osaka, Kansai Region","ja":"大阪府大阪市西成区・道頓堀","ko":"오사카부 니시나리구 & 도톤보리","th":"ย่านโดทงโบริ โอซาก้า"},"famousYataiMarkets":[{"zh-TW":"大阪道頓堀章魚燒一文字街","en":"Dotonbori Takoyaki Street, Osaka","ja":"道頓堀たこ焼きストリート","ko":"도톤보리 타코야키 거리","th":"ถนนทาโกะยากิโดทงโบริ โอซาก้า"},{"zh-TW":"福岡天神・中洲屋台街","en":"Nakasu Yatai, Fukuoka","ja":"福岡中洲屋台","ko":"후쿠오카 나카스 야타이","th":"ร้านยาไตนาคาสุ ฟุกุโอกะ"}],"historyStory":{"zh-TW":"章魚燒起源於昭和 10 年（1935 年），由大阪「會津屋」創始人遠藤留吉從當時的牛肉「收音機燒（ラジオ焼き）」改良，改加入明石產新鮮章魚並調和高湯麵糊，從此風靡全日本並成為大阪人家庭必備電烤盤的象徵！","en":"Invented in 1935 by Tomekichi Endo in Osaka, adapting the earlier beef-filled \"Radio-yaki\" with succulent octopus. It became Osaka’s signature export worldwide.","ja":"昭和10年（1935年）、大阪「会津屋」の初代・遠藤留吉が従来のラヂオ焼を改良し、明石のタコを入れて開発したのが始まりとされています。","ko":"1935년 오사카 아이즈야의 창업자가 개발한 요리로, 문어의 쫄깃함과 육수 반죽의 조화로 큰 인기를 끌었습니다.","th":"คิดค้นขึ้นในปี 1935 ที่โอซาก้า พัฒนาจากขนมเดิมโดยใส่ปลาหมึกยักษ์ชิ้นโตจนกลายเป็นสัญลักษณ์ของโอซาก้า"},"japaneseKanji":"たこ焼き","japaneseKana":"たこやき","japaneseRomaji":"Takoyaki","audioPronunciationText":"たこ焼き","nativeName":"たこ焼き","nativePhonetics":"たこやき"},"ingredients":[{"id":"octopus","name":{"zh-TW":"熟章魚腳切塊 (Boiled Octopus)","en":"Boiled Octopus (cut into chunks)","ja":"茹でタコ（ぶつ切り）","ko":"자숙 문어 다리 (한입 크기 깍둑썰기)","th":"หนวดปลาหมึกยักษ์ต้มหั่นชิ้น"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":true,"japaneseKanji":"茹でタコ","japaneseKana":"ゆでたこ","japaneseRomaji":"Yude Tako","substitute":{"substituteName":{"zh-TW":"熟大鮮蝦丁或花枝塊","en":"Diced Prawns or Squid","ja":"エビ・イカ切り身","ko":"새우 또는 오징어 토막","th":"กุ้งลวกหรือปลาหมึกกล้วยหั่นเต๋า"},"ratio":"1:1","explanation":{"zh-TW":"若買不到熟章魚腳，鮮蝦與花枝丁同樣能提供絕佳的鮮脆嚼勁。","en":"Large shrimp pieces or squid rings provide fantastic springy texture.","ja":"タコが手に入らない場合、海老やイカでも美味しく仕上がります。","ko":"문어가 없으면 새우나 오징어로 대체해도 훌륭한 식감을 냅니다.","th":"หากไม่มีหมึกยักษ์ ใช้กุ้งสดหรือปลาหมึกกล้วยแทนได้"},"whereToBuy":{"zh-TW":"亞洲超市、好市多海鮮區或日本 Donki","en":"Asian supermarkets, seafood markets or Costco","ja":"スーパーの鮮魚コーナー、業務スーパー","ko":"한인마트, 일본 마트 수산 코너","th":"ซูเปอร์มาร์เก็ตแผนกอาหารทะเลสด"}}},{"id":"flour","name":{"zh-TW":"低筋麵粉 (Cake / Pastry Flour)","en":"Low Protein Flour (Cake Flour)","ja":"薄力粉","ko":"박력분 (밀가루)","th":"แป้งสาลีตราบัวแดง (แป้งเค้ก)"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz (approx 3/4 cup)","japaneseKanji":"薄力粉","japaneseKana":"はくりきこ","japaneseRomaji":"Hakurikiko"},{"id":"dashi-broth","name":{"zh-TW":"日式鰹魚高湯 (Dashi Stock chilled)","en":"Cold Japanese Dashi Broth","ja":"冷ました和風だし汁","ko":"식힌 가쓰오 다시마 육수","th":"น้ำซุปดาชิปลาแห้งเย็น"},"amount":340,"unitMetric":"ml","unitUS":"1.4 cups","isKeyFlavor":true,"japaneseKanji":"だし汁","japaneseKana":"だしじる","japaneseRomaji":"Dashi Jiru"},{"id":"egg","name":{"zh-TW":"全蛋 (Large Egg)","en":"Egg (beaten)","ja":"鶏卵","ko":"달걀","th":"ไข่ไก่สด"},"amount":1,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"卵","japaneseKana":"たまご","japaneseRomaji":"Tamago"},{"id":"tenkasu","name":{"zh-TW":"炸天婦羅花麵衣碎 (Tenkasu / Tempura Scraps)","en":"Tempura Flakes (Tenkasu)","ja":"天かす（揚げ玉）","ko":"텐카스 (튀김 부스러기)","th":"เกล็ดแป้งเทมปุระทอดกรอบ"},"amount":25,"unitMetric":"g","unitUS":"0.9 oz","isKeyFlavor":true,"japaneseKanji":"天かす","japaneseKana":"てんかす","japaneseRomaji":"Tenkasu"},{"id":"benishoga","name":{"zh-TW":"日式紅生薑碎 (Beni Shoga Red Pickled Ginger)","en":"Finely Chopped Red Pickled Ginger","ja":"紅しょうが（みじん切り）","ko":"베니쇼가 (다진 초생강)","th":"ขิงดองสีแดงสับละเอียด"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","japaneseKanji":"紅生姜","japaneseKana":"べにしょうが","japaneseRomaji":"Beni Shōga"},{"id":"scallions","name":{"zh-TW":"切碎綠蔥花 (Chopped Green Scallions)","en":"Finely chopped scallions","ja":"小ねぎ（小口切り）","ko":"송송 썬 쪽파","th":"ต้นหอมซอยละเอียด"},"amount":20,"unitMetric":"g","unitUS":"2 tbsp","japaneseKanji":"青ねぎ","japaneseKana":"あおねぎ","japaneseRomaji":"Ao Negi"},{"id":"takoyaki-sauce","name":{"zh-TW":"章魚燒專用醬 (Takoyaki Sauce)","en":"Japanese Takoyaki Sauce","ja":"たこ焼きソース","ko":"타코야키 전용 소스","th":"ซอสทาโกะยากิ"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","isKeyFlavor":true,"japaneseKanji":"たこ焼きソース","japaneseKana":"たこやきそーす","japaneseRomaji":"Takoyaki Sōsu"},{"id":"kewpie-mayo","name":{"zh-TW":"丘比日式美乃滋 (Kewpie Mayo)","en":"Kewpie Japanese Mayonnaise","ja":"キユーピーマヨネーズ","ko":"큐피 마요네즈","th":"มายองเนสคิวพี"},"amount":20,"unitMetric":"ml","unitUS":"1.5 tbsp","japaneseKanji":"マヨネーズ","japaneseKana":"まよねーず","japaneseRomaji":"Mayonēzu"},{"id":"katsuobushi","name":{"zh-TW":"柴魚片 (Bonito Flakes)","en":"Shaved Bonito Flakes (Katsuobushi)","ja":"鰹節（花かつお）","ko":"가쓰오부시 (가다랑어포)","th":"ปลาโอแห้งขูดฝอย"},"amount":5,"unitMetric":"g","unitUS":"0.2 oz","japaneseKanji":"鰹節","japaneseKana":"かつおぶし","japaneseRomaji":"Katsuobushi"},{"id":"aonori","name":{"zh-TW":"青海苔粉 (Aonori Dried Green Seaweed)","en":"Aonori Green Seaweed Powder","ja":"青のり粉","ko":"아오노리 (파래가루)","th":"สาหร่ายสีเขียวป่น"},"amount":2,"unitMetric":"g","unitUS":"1 tsp","japaneseKanji":"青のり","japaneseKana":"あおのり","japaneseRomaji":"Aonori"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調製高湯麵糊 (Whisk Batter)","en":"Whisk the Dashi Batter","ja":"出汁生地を作る","ko":"다시 육수 반죽 섞기","th":"ผสมแป้งกับน้ำซุปดาชิ"},"instruction":{"zh-TW":"將低筋麵粉過篩入調理碗中。加入打散的雞蛋、淡口醬油少許，並分三次緩緩倒入冰涼高湯，用打蛋器輕柔拌勻至無顆粒狀（麵糊質地偏稀是流心爆漿的秘訣！），靜置 15 分鐘消泡。","en":"Sift cake flour into a bowl. Whisk in beaten egg, then gradually stream in chilled dashi in 3 batches until completely smooth and runny. Let rest for 15 minutes.","ja":"ボウルに薄力粉をふるい入れ、溶き卵、冷ました出汁を3回に分けて注ぎながらダマがなくなるまでよく混ぜます。サラサラの生地が中トロの秘訣です。","ko":"볼에 박력분을 체 쳐 넣고 달걀과 식힌 다시 육수를 3번에 나누어 부어가며 멍울 없이 묽게 섞어 15분간 휴지합니다.","th":"ร่อนแป้งลงชาม ตอกไข่และค่อยๆ เทน้ำซุปดาชิเย็นลงไป คนให้เนียนไม่เป็นก้อน แป้งเหลวคือเคล็ดลับความนุ่มเยิ้ม"},"durationSeconds":180,"image":"/images/jp/takoyaki-step1.jpg","crucialTips":{"zh-TW":"正宗大阪章魚燒麵糊非常稀（粉水比約 1:3.4），千萬不要自行加麵粉！稀麵糊才能在高溫下形成脆薄外殼與流心高湯內餡。","en":"Authentic batter is very watery (~1:3.4 ratio). Do not add extra flour; a runny batter ensures the molten custard core.","ja":"生地はシャバシャバが正解です！粉を足してしまうとモサモサになるので分量を守りましょう。","ko":"반죽이 매우 묽어야 정상입니다! 밀가루를 더 넣으면 퍽퍽해지므로 정량을 지켜주세요.","th":"แป้งที่เหลวมากเป็นเรื่องปกติ ห้ามเติมแป้งเพิ่มเด็ดขาด เพื่อให้ได้สัมผัสนุ่มละลายด้านใน"}},{"stepNumber":2,"title":{"zh-TW":"預熱鐵盤與刷油 (Preheat & Oil)","en":"Preheat Pan & Oil Generously","ja":"鉄板を予熱し油を引く","ko":"팬 예열 및 넉넉한 기름칠","th":"วอร์มเตาและทาน้ำมันให้ทั่ว"},"instruction":{"zh-TW":"章魚燒烤盤預熱至 200°C。使用廚房紙巾或油刷，在每個圓形凹槽以及周圍平坦溝槽均勻抹上耐高溫沙拉油，直到微微冒煙。","en":"Preheat the takoyaki pan to 200°C (390°F). Generously coat each mold and flat rims with oil using a brush until shimmering.","ja":"たこ焼き器をしっかり200℃まで予熱。くぼみだけでなくプレートの縁まで油をたっぷり塗り広げます。","ko":"팬을 200도로 예열하고 구멍과 주변 틈새까지 식용유를 듬뿍 바릅니다.","th":"เปิดเตาให้ร้อน 200°C ใช้แปรงทาน้ำมันให้ทั่วหลุมและขอบกระทะ"},"durationSeconds":120,"image":"/images/jp/takoyaki-step2.jpg","dangerWarnings":{"zh-TW":"油量不足是新手黏鍋翻不轉的頭號原因！邊緣縫隙也要抹上油。","en":"Insufficient oil is the #1 reason batter sticks and fails to turn. Don’t skimp on oil.","ja":"油が足りないと生地がくっついて回転できなくなります。縁まで念入りに。","ko":"기름이 부족하면 반죽이 달라붙어 뒤집히지 않습니다. 충분히 둘러주세요.","th":"ทาน้ำมันน้อยเกินไปจะทำให้แป้งติดกระทะและหมุนไม่ได้"}},{"stepNumber":3,"title":{"zh-TW":"注漿入餡與灑料 (Pour & Add Fillings)","en":"Pour Batter & Add Fillings","ja":"生地を流し具材を入れる","ko":"반죽 붓고 속재료 넣기","th":"เทแป้งล้นหลุมและใส่ไส้"},"instruction":{"zh-TW":"將麵糊再次攪勻，倒滿所有模具凹槽，甚至讓麵糊溢出漫到整個烤盤表面。迅速在每個球心放入一塊章魚，隨後大方撒上天華天婦羅碎、蔥花與紅生薑碎。","en":"Stir batter well, then pour until overflowing past the molds. Immediately drop one chunk of octopus into each slot, then scatter tenkasu, chopped scallions, and red ginger all over.","ja":"沈殿した生地を混ぜてから、穴から溢れるまでたっぷり注ぎます。タコを1粒ずつ投入し、天かす、ネギ、紅生姜を全体に散らします。","ko":"가라앉은 반죽을 저은 후 틀 위로 넘치도록 붓습니다. 문어 조각을 하나씩 넣고 텐카스, 쪽파, 생강을 듬뿍 뿌립니다.","th":"คนแป้งแล้วเทให้ล้นหลุม ใส่ชิ้นปลาหมึกลงไปทุกหลุม โรยเกล็ดเทมปุระ ต้นหอมซอย และขิงดองให้ทั่ว"},"durationSeconds":90,"image":"/images/jp/takoyaki-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"氣炸鍋模式：200°C 烤 12 分鐘（使用球形矽膠模具或半圓模具）","instructionOverride":{"zh-TW":"若使用氣炸鍋，將麵糊倒入耐熱耐油的章魚燒矽膠模中，放入配料，以 200°C 氣炸 12 分鐘，中途翻面噴少許油以確保酥脆。","en":"For Air Fryer: Pour batter into heat-safe silicone takoyaki molds, add toppings, bake at 200°C for 12 mins, misting with oil once halfway.","ja":"ノンフライヤー使用時は耐熱シリコン型に生地を注ぎ、200℃で12分加熱。途中で一度返して油をひと吹きします。","ko":"에어프라이어 이용 시 실리콘 몰드에 붓고 200도에서 12분간 조리하며 중간에 뒤집어 오일을 살짝 뿌립니다.","th":"สำหรับหม้อทอดไร้น้ำมัน: เทใส่พิมพ์ซิลิโคน อบที่ 200°C นาน 12 นาที พลิกกลับด้านพ่นน้ำมันเล็กน้อย"}}]},{"stepNumber":4,"title":{"zh-TW":"劃線收邊與 90 度翻轉 (Cut & 90° Turn)","en":"Score Lines & 90-Degree Turn","ja":"格子に切り分け90度回転","ko":"격자로 선 긋고 90도 돌리기","th":"กรีดเส้นแบ่งและหมุน 90 องศา"},"instruction":{"zh-TW":"待底部稍微凝固（約 2 分鐘），用鐵籤或竹籤像切豆腐一樣，沿著模具邊緣劃出九宮格。將外圍溢出的配料與麵皮用籤子塞進球體下方，順勢將章魚燒挑起轉動 90 度，讓未熟的生麵糊流進凹槽底。","en":"After ~2 minutes when the bottom sets, use picks to score grids between molds. Tuck the spilled edges inside each ball, then swivel each 90° so raw batter flows down.","ja":"底が固まってきたら（約2分）、ピックで溝に沿って格子状に切り目を入れます。あふれた生地を穴に押し込みながら、手早く90度くるっと回転させます。","ko":"밑면이 살짝 익으면 꼬치로 구획을 나누어 넘친 반죽을 구멍 안으로 밀어 넣으며 90도 돌려줍니다.","th":"เมื่อก้นเริ่มสุก ใช้ไม้กรีดแบ่งเป็นช่องๆ เก็บขอบแป้งยัดลงหลุม แล้วสะกิดหมุน 90 องศาให้แป้งดิบไหลลงไป"},"durationSeconds":150,"image":"/images/jp/takoyaki-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"快速滾動滾圓與補油脆皮 (Roll Round & Crisp)","en":"Continuous Rolling & Crisping","ja":"コロコロ回して仕上げの追い油","ko":"계속 굴려 동그랗게 만들고 겉면 바삭하게","th":"หมุนกลมต่อเนื่องและหยอดน้ำมันเพิ่มความกรอบ"},"instruction":{"zh-TW":"持續用兩支竹籤快速翻動滾動每個球體，使其形成完美的正圓形。最後在盤面淋上幾滴沙拉油（職人稱為「追い油」），以大火半煎半炸約 2 分鐘，外皮瞬間轉為金黃酥脆！","en":"Continuously roll each ball until evenly spherical. Drizzle a little extra oil around the rims (\"oi-abura\" crisping technique) and fry on high heat for 2 mins for a crackly crust.","ja":"2本のピックでコロコロと絶え間なく回して綺麗な球体に。最後に油を少量回しかけ（追い油）、表面をカリッと揚げ焼きにします。","ko":"꼬치 2개로 둥글게 굴려주다가 마지막에 식용유를 약간 둘러 겉면을 튀기듯 바삭하게 구워냅니다.","th":"ใช้ไม้สองอันหมุนกลมไปเรื่อยๆ หยอดน้ำมันเพิ่มเล็กน้อยทอดจนผิวนอกเหลืองกรอบ"},"durationSeconds":180,"image":"/images/jp/takoyaki-step5.jpg","crucialTips":{"zh-TW":"最後起鍋前的「補油半煎炸」是外皮咔滋作響、放涼也不會塌陷的日本職人關鍵技巧！","en":"Drizzling a splash of oil at the very end flash-fries the outer crust so it stays crisp even when plated.","ja":"仕上げの「追い油」が銀だこ風のカリッとした食感を生む秘密です！","ko":"마지막에 두르는 소량의 기름이 겉은 바삭하고 속은 부드러운 타코야키의 비결입니다.","th":"การหยอดน้ำมันช่วงท้ายทำให้ผิวด้านนอกกรอบสะใจไม่ยุบตัว"}},{"stepNumber":6,"title":{"zh-TW":"刷醬擠醬與柴魚跳舞 (Sauce & Garnish)","en":"Brush Sauce & Garnish","ja":"ソース・マヨを塗りトッピング","ko":"소스, 마요네즈, 가쓰오부시 토핑","th":"ทาซอส บีบมายองเนส และโรยปลาแห้งเต้นระบำ"},"instruction":{"zh-TW":"將章魚燒盛入小船型木盒或盤中。豪邁刷上黑潤的章魚燒醬，以細孔擠醬瓶交錯擠出丘比美乃滋網格，最後灑上翠綠青海苔粉，頂部堆疊一把輕盈柴魚片，趁熱看柴魚在蒸汽中曼妙舞動，立即開動！","en":"Plate takoyaki onto a dish or wooden boat. Brush with takoyaki sauce, zigzag Kewpie mayo in fine lines, sprinkle aonori, and top with a mountain of dancing bonito flakes.","ja":"舟皿に盛り付け、特製ソースをたっぷりハケで塗り、マヨネーズを細く絞ります。青のりと鰹節を豪快にトッピングして召し上がれ！","ko":"접시에 담고 타코야키 소스를 듬뿍 바른 후 마요네즈를 지그재그로 뿌리고 파래가루와 가쓰오부시를 얹어냅니다.","th":"ตักใส่จาน ทาซอสทาโกะยากิ บีบมายองเนสเป็นตาราง โรยสาหร่ายและปลาโอแห้งขูด เสิร์ฟร้อนๆ ทันที"},"durationSeconds":60,"image":"/images/jp/takoyaki-step6.jpg"}],"troubleshooting":[{"id":"trouble-1","problem":{"zh-TW":"為什麼翻動時容易破皮黏在烤盤上？","en":"Why do the balls stick to the pan and tear apart?","ja":"ひっくり返す時に生地が破れてくっついてしまいます。","ko":"뒤집을 때 껍질이 찢어지고 팬에 달라붙어요.","th":"ทำไมเวลาพลิกกลับด้านแล้วแป้งขาดติดกระทะ?"},"cause":{"zh-TW":"鐵盤預熱不夠熱、或油抹得太少，或是太早急著去翻它（底部尚未凝結成皮）。","en":"Pan was not hot enough (under 190°C), lack of oil, or attempted to turn too early before the shell formed.","ja":"鉄板の温度不足、油の不足、または底が固まる前に焦って触りすぎたことが原因です。","ko":"팬 예열 부족, 기름칠 부족, 혹은 겉면이 익기 전에 너무 일찍 건드렸기 때문입니다.","th":"เตาร้อนไม่พอ ทาน้ำมันน้อยไป หรือใจร้อนพลิกเร็วเกินไปขณะที่แป้งยังไม่เซ็ตตัว"},"solution":{"zh-TW":"確實預熱至滴水會嗤嗤滾動，每個凹槽都均勻刷油，倒入麵糊後耐心等待滿 2 分鐘再動手劃線收邊。","en":"Wait until water drops sizzle and dance. Coat each mold fully with oil and give it a full 2 minutes before the first turn.","ja":"煙が出るまで予熱し、油をたっぷり引き、流し入れてから丸2分は触らず待ちましょう。","ko":"팬이 충분히 달궈진 후 기름을 넉넉히 바르고 반죽을 부은 뒤 2분간 기다렸다가 뒤집으세요.","th":"รอให้เตาร้อนจัด ทาน้ำมันให้ชุ่ม และรอครบ 2 นาทีเต็มก่อนเริ่มลงมือพลิก"}},{"id":"trouble-2","problem":{"zh-TW":"起鍋後一下子就消氣塌扁癟癟的？","en":"Why do the balls deflate and flatten out after plating?","ja":"焼き上がった後、お皿に取るとすぐにしぼんでしまいます。","ko":"접시에 꺼내놓으면 금방 납작하게 주저앉아요.","th":"ทำไมตักขึ้นมาแล้วทาโกะยากิยุบตัวแบนลงอย่างรวดเร็ว?"},"cause":{"zh-TW":"外皮烘烤時間不夠長、外殼不夠厚脆，球體內部水氣冷卻時支撐力不足。","en":"Outer shell was not fried long enough to form a rigid structure to withstand steam cooling.","ja":"焼き時間が短く、表面の皮が薄くて蒸気の収縮に耐えられないためです。","ko":"굽는 시간이 짧아 겉껍질이 충분히 두껍고 단단하게 형성되지 않았기 때문입니다.","th":"ทอดผิวรอบนอกยังไม่กรอบหนาพอ ทำให้รับแรงดันไอน้ำที่ลดลงไม่ได้"},"solution":{"zh-TW":"在成形後持續滾動至少 3 分鐘，起鍋前務必淋上一點油進行大火脆皮半煎炸，外殼金黃發硬才起鍋。","en":"Keep rolling for at least 3 minutes, and execute the final oil sizzle step until the shell sounds hollow and firm.","ja":"丸くなってからも転がし続け、最後の追い油でカリッとなるまでしっかり揚げ焼きにしましょう。","ko":"동그랗게 된 후에도 3분 이상 굴려주고 마지막에 기름을 둘러 겉을 바삭하게 튀기듯 익히세요.","th":"หมุนกลมต่อไปอีกอย่างน้อย 3 นาที และใช้น้ำมันหยอดทอดผิวให้กรอบทองก่อนตักขึ้น"}}],"proTips":[{"zh-TW":"【冰涼高湯法】：調配麵糊時使用冰高湯（甚至冷藏過），有助於抑制麵筋形成，保持內餡絲滑化口的 Creamy 質地！","en":"Use ice-cold dashi when mixing batter to inhibit gluten development, ensuring an ultra-creamy interior.","ja":"【冷たい出汁を使う】：冷水や冷たい出汁で溶くことでグルテンの発生を抑え、理想のとろとろ食感になります。","ko":"차가운 육수로 반죽을 만들면 글루텐 형성이 억제되어 속이 훨씬 부드럽게 녹아내립니다.","th":"ใช้น้ำซุปดาชิที่เย็นจัดช่วยยับยั้งกลูเตน ทำให้แป้งด้านในนุ่มเนียนละลายในปาก"},{"zh-TW":"【天婦羅碎不可省】：天華（天かす）在烤製時會融化釋放油脂並吸附高湯，是外皮酥脆與內部濃郁的香味大功臣！","en":"Never skip tenkasu: As tempura scraps melt inside the shell, they release rich umami and create micro-crispiness.","ja":"【天かすはケチらない】：天かすから溶け出す上質な油が出汁を吸い、コクとサクサク感を生みます。","ko":"텐카스는 필수입니다. 구워지면서 녹아 나오는 기름이 반죽의 풍미와 바삭함을 책임집니다.","th":"เกล็ดเทมปุระทอดกรอบห้ามงดเด็ดขาด เพราะจะปล่อยน้ำมันหอมและดูดซับน้ำซุปทำให้เนื้อสัมผัสยอดเยี่ยม"}]},{"country":"jp","id":"okonomiyaki","slug":"osaka-okonomiyaki","title":{"zh-TW":"大阪風經典御好燒","en":"Osaka Style Okonomiyaki","ja":"大阪風 豚玉お好み焼き","ko":"오사카식 클래식 오코노미야키","th":"โอโคโนมิยากิสไตล์โอซาก้า"},"subtitle":{"zh-TW":"蓬鬆厚實高麗菜餅、脆煎五花肉片與美乃滋拉花","en":"Fluffy shredded cabbage pancake layered with crisp pork belly & mayo lattice","ja":"キャベツたっぷり山芋ふんわり、カリッと焼いた豚バラの王道お好み焼き","ko":"양배추 가득, 산마로 부드럽게 부쳐낸 바삭한 삼겹살 오코노미야키","th":"พิซซ่าญี่ปุ่นกะหล่ำปลีเนื้อนุ่มฟู หมูสามชั้นกรอบ และซอสมายองเนส"},"tagline":{"zh-TW":"「隨你所好（お好み）」的鐵板盛宴，在家平底鍋輕鬆做出餐廳級鬆軟厚度！","en":"Cook what you love! Recreate restaurant-grade fluffy thickness on a home skillet.","ja":"家庭のフライパンでプロの味！山芋パワーで冷めてもふっくら極上の仕上がり。","ko":"원하는 재료를 마음껏! 프라이팬으로 만드는 두툼하고 촉촉한 정통 맛.","th":"ใส่เครื่องได้ตามใจชอบ ทำง่ายด้วยกระทะที่บ้าน หนา นุ่ม อร่อยระดับร้านดัง"},"heroImage":"/images/jp/okonomiyaki-hero.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":12,"defaultServings":2,"caloriesPerServing":480,"category":"konamono","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer","oven"],"culture":{"originRegion":{"zh-TW":"大阪府 (Osaka)","en":"Osaka, Kansai Region","ja":"大阪府","ko":"오사카부","th":"จังหวัดโอซาก้า"},"famousYataiMarkets":[{"zh-TW":"大阪道頓堀老舖御好燒街","en":"Dotonbori Okonomiyaki Stalls, Osaka","ja":"道頓堀お好み焼き老舗街","ko":"도톤보리 오코노미야키 골목","th":"ย่านโอโคโนมิยากิโดทงโบริ โอซาก้า"}],"historyStory":{"zh-TW":"戰後物資匱乏時代，大阪庶民利用美軍配給的麵粉，加上廉價又爽脆的高麗菜絲煎成厚餅，因顧客能自由挑選喜愛的肉類或海鮮配料，故得名「御好燒（Okonomi = 隨你喜好）」。","en":"Born post-WWII when Osakans mixed cheap abundant cabbage into flour batter. The name Okonomiyaki literally means \"grilled as you like it\".","ja":"戦後の食糧難の時代、手に入りやすかった小麦粉とキャベツを鉄板で焼いた「一銭洋食」が原型。好きな具材を入れて焼くことから名付けられました。","ko":"전후 밀가루와 양배추를 섞어 구워 먹던 음식에서 시작되어, 취향(오코노미)대로 구워 먹는 대표 명물이 되었습니다.","th":"มีต้นกำเนิดหลังสงครามโลก โดยนำกะหล่ำปลีราคาถูกมาผสมแป้งย่างบนกระทะเหล็ก เลือกใส่เครื่องได้ตามใจชอบ"},"japaneseKanji":"お好み焼き","japaneseKana":"おこのみやき","japaneseRomaji":"Okonomiyaki","audioPronunciationText":"お好み焼き","nativeName":"お好み焼き","nativePhonetics":"おこのみやき"},"ingredients":[{"id":"pork-belly","name":{"zh-TW":"五花肉薄切肉片 (Pork Belly Slices)","en":"Thinly sliced pork belly","ja":"豚バラ薄切り肉","ko":"대패 삼겹살 (얇은 삼겹살)","th":"หมูสามชั้นสไลซ์บาง"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":true,"japaneseKanji":"豚バラ肉","japaneseKana":"ぶたばらにく","japaneseRomaji":"Butabara Niku"},{"id":"cabbage","name":{"zh-TW":"高麗菜細絲 (Finely shredded cabbage)","en":"Finely shredded green cabbage","ja":"キャベツ（粗みじん切り）","ko":"잘게 썬 양배추","th":"กะหล่ำปลีซอยละเอียด"},"amount":200,"unitMetric":"g","unitUS":"7 oz (approx 3 cups)","japaneseKanji":"キャベツ","japaneseKana":"きゃべつ","japaneseRomaji":"Kyabetsu"},{"id":"nagaimo","name":{"zh-TW":"日本山藥泥 (Grated Japanese Nagaimo Yam)","en":"Grated Japanese Mountain Yam (Nagaimo)","ja":"山芋／長芋すりおろし","ko":"갈아낸 마 (산마)","th":"มันมือเสือญี่ปุ่นขูดละเอียด"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","isKeyFlavor":true,"japaneseKanji":"長芋","japaneseKana":"ながいも","japaneseRomaji":"Nagaimo","substitute":{"substituteName":{"zh-TW":"泡打粉 1/2 茶匙 + 豆腐泥 30g","en":"1/2 tsp Baking Powder + 30g Silken Tofu","ja":"ベーキングパウダー小さじ1/2 ＋ 絹豆腐30g","ko":"베이킹파우더 1/2작은술 + 연두부 30g","th":"ผงฟู 1/2 ช้อนชา + เต้าหู้ขาวบด 30 กรัม"},"ratio":"1:1","explanation":{"zh-TW":"山藥泥能鎖住水分讓餅身蓬鬆化口，豆腐與微量泡打粉可達成 90% 相似的鬆軟感。","en":"Yam traps steam for maximum fluffiness. Tofu and baking powder mimic this texture.","ja":"山芋はふんわり感の決め手。絹豆腐と少量のベーキングパウダーで代用可能です。","ko":"마가 없으면 연두부와 베이킹파우더로 비슷한 폭신한 식감을 낼 수 있습니다.","th":"มันมือเสือช่วยให้เนื้อฟูนุ่ม หากไม่มีใช้เต้าหู้บดกับผงฟูแทนได้"},"whereToBuy":{"zh-TW":"一般生鮮超市或亞洲超市蔬果區","en":"Asian produce markets or Whole Foods","ja":"スーパーの青果売り場","ko":"일반 마트 채소 코너","th":"ซูเปอร์มาร์เก็ตแผนกผักสด"}}},{"id":"flour","name":{"zh-TW":"低筋麵粉 (Cake Flour)","en":"Cake Flour","ja":"薄力粉","ko":"박력분","th":"แป้งเค้ก"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","japaneseKanji":"薄力粉","japaneseKana":"はくりきこ","japaneseRomaji":"Hakurikiko"},{"id":"dashi-stock","name":{"zh-TW":"鰹魚高湯 (Dashi Broth)","en":"Dashi Stock","ja":"和風だし汁","ko":"다시 육수","th":"น้ำซุปดาชิ"},"amount":100,"unitMetric":"ml","unitUS":"3.4 fl oz","japaneseKanji":"だし汁","japaneseKana":"だしじる","japaneseRomaji":"Dashi Jiru"},{"id":"eggs","name":{"zh-TW":"雞蛋 (Eggs)","en":"Large Eggs","ja":"鶏卵","ko":"달걀","th":"ไข่ไก่"},"amount":2,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"卵","japaneseKana":"たまご","japaneseRomaji":"Tamago"},{"id":"tenkasu","name":{"zh-TW":"天華炸天婦羅碎 (Tenkasu)","en":"Tempura Flakes","ja":"天かす","ko":"텐카스","th":"เกล็ดเทมปุระทอด"},"amount":20,"unitMetric":"g","unitUS":"0.7 oz","japaneseKanji":"天かす","japaneseKana":"てんかす","japaneseRomaji":"Tenkasu"},{"id":"okonomi-sauce","name":{"zh-TW":"御好燒專用醬 (Okonomiyaki Sauce)","en":"Okonomi Sauce","ja":"お好みソース","ko":"오코노미야키 소스","th":"ซอสโอโคโนมิยากิ"},"amount":40,"unitMetric":"ml","unitUS":"2.7 tbsp","isKeyFlavor":true,"japaneseKanji":"お好みソース","japaneseKana":"おこのみそーす","japaneseRomaji":"Okonomi Sōsu"},{"id":"kewpie-mayo","name":{"zh-TW":"日式丘比美乃滋 (Kewpie Mayo)","en":"Kewpie Mayonnaise","ja":"マヨネーズ","ko":"마요네즈","th":"มายองเนส"},"amount":25,"unitMetric":"ml","unitUS":"1.7 tbsp","japaneseKanji":"マヨネーズ","japaneseKana":"まよねーず","japaneseRomaji":"Mayonēzu"},{"id":"katsuobushi","name":{"zh-TW":"柴魚片 (Bonito Flakes)","en":"Katsuobushi Bonito Flakes","ja":"鰹節削り節","ko":"가쓰오부시","th":"ปลาโอแห้งขูด"},"amount":5,"unitMetric":"g","unitUS":"0.2 oz","japaneseKanji":"鰹節","japaneseKana":"かつおぶし","japaneseRomaji":"Katsuobushi"},{"id":"aonori","name":{"zh-TW":"青海苔粉 (Aonori)","en":"Aonori Green Seaweed","ja":"青のり粉","ko":"아오노리","th":"สาหร่ายผงเขียว"},"amount":2,"unitMetric":"g","unitUS":"1 tsp","japaneseKanji":"青のり","japaneseKana":"あおのり","japaneseRomaji":"Aonori"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調和高湯山藥基底 (Mix Batter Base)","en":"Prepare Yam Dashi Batter","ja":"出汁と山芋の生地を混ぜる","ko":"다시 육수와 산마 반죽 만들기","th":"ผสมน้ำซุปดาชิกับมันมือเสือขูด"},"instruction":{"zh-TW":"在碗中將麵粉、高湯、磨碎的山藥泥充分攪拌勻化成滑順粉漿，靜置 10 分鐘。","en":"In a bowl, combine flour, dashi broth, and freshly grated nagaimo yam into a smooth batter. Rest for 10 minutes.","ja":"ボウルに薄力粉、出汁、すりおろした山芋を合わせ、泡立て器でダマがなくなるまで滑らかに混ぜます。","ko":"볼에 밀가루, 다시 육수, 간 산마를 넣고 멍울 없이 곱게 섞은 뒤 10분간 둡니다.","th":"ผสมแป้ง น้ำซุปดาชิ และมันมือเสือขูดให้เนียนเข้ากัน พักไว้ 10 นาที"},"durationSeconds":120,"image":"/images/jp/okonomiyaki-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"輕柔拌入高麗菜與空氣 (Fold with Air)","en":"Fold in Cabbage & Trap Air","ja":"キャベツと卵を空気を含むように混ぜる","ko":"양배추와 달걀을 공기 머금듯 살살 섞기","th":"ตะล่อมกะหล่ำปลีและไข่ให้มีโพรงอากาศ"},"instruction":{"zh-TW":"在基底粉漿中加入切細的高麗菜絲、雞蛋、天華天婦羅碎。用湯匙「由下往上」大幅度翻拌約 15-20 下即可（切忌死力打圈攪拌，保留葉片間的空氣，是厚餅煎出來鬆軟不沉重的靈魂！）。","en":"Add shredded cabbage, eggs, and tenkasu. Gently fold from bottom to top 15-20 times to trap air pockets. Do not overmix!","ja":"キャベツ、卵、天かすを加えます。スプーンで底から空気を抱き込むように大きくサックリと15回程度混ぜます（混ぜすぎ厳禁）。","ko":"양배추, 달걀, 텐카스를 넣고 숟가락으로 밑에서 위로 공기를 넣듯 15~20번만 가볍게 섞습니다.","th":"ใส่กะหล่ำปลี ไข่ และเกล็ดเทมปุระ ตะล่อมเบาๆ 15-20 ครั้งเพื่อให้อากาศแทรก ไม่คนแรงจนแน่น"},"durationSeconds":60,"image":"/images/jp/okonomiyaki-step2.jpg","crucialTips":{"zh-TW":"職人秘訣：絕對不要把麵糊拌成糊爛一團！像拌沙拉一樣輕盈，高麗菜才不會大量出水破壞蓬鬆度。","en":"Never over-whisk cabbage into a dense sludge. Treat it like folding a salad to prevent moisture leakage.","ja":"練り混ぜてしまうとキャベツから水分が出てベチャベチャになります。サックリが基本！","ko":"치대듯 섞으면 양배추에서 물이 나와 떡처럼 됩니다. 샐러드 버무리듯 가볍게 섞으세요.","th":"อย่าคนจนเละ กะหล่ำปลีจะคายน้ำและทำให้แป้งเหนียวแน่นไม่ฟู"}},{"stepNumber":3,"title":{"zh-TW":"下鍋整形與鋪肉片 (Form Patty & Layer Pork)","en":"Griddle Patty & Layer Pork Belly","ja":"フライパンに丸く広げ豚バラを乗せる","ko":"팬에 도톰하게 올리고 삼겹살 얹기","th":"เทลงกระทะจัดทรงกลมหนาและวางหมูสามชั้น"},"instruction":{"zh-TW":"平底鍋熱油（中火約 180°C）。將整盆麵糊一口氣倒入鍋中，用鏟子輕輕推攏整修成厚度約 2-2.5 公分的圓形厚餅。頂部並排鋪上五花肉薄片，蓋上鍋蓋燜煎 4 分鐘。","en":"Heat skillet with oil on medium. Pour all batter in, gently nudging into a 2-2.5 cm thick disk. Layer pork belly slices across the top. Cover with lid and steam-fry for 4 mins.","ja":"フライパンを中火で熱し油を引く。生地を丸く流し、厚さ約2cmに形を整えます。上に豚バラ肉を隙間なく並べ、フタをして蒸し焼き4分。","ko":"팬에 기름을 두르고 반죽을 부어 두께 2cm 원형으로 도톰하게 모양을 잡습니다. 위에 삼겹살을 얹고 뚜껑을 덮어 4분간 굽습니다.","th":"ตั้งกระทะไฟกลาง ทาน้ำมัน เทแป้งลงไปจัดรูปทรงหนาประมาณ 2 ซม. วางหมูสามชั้นเรียงด้านบน ปิดฝาอบ 4 นาที"},"durationSeconds":240,"image":"/images/jp/okonomiyaki-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"華麗翻面與燜烤熟透 (Flip & Steam-Cook)","en":"Flip & Crisp the Pork","ja":"一気にひっくり返しフタをして焼く","ko":"단숨에 뒤집고 뚜껑 덮어 속까지 익히기","th":"พลิกกลับด้านในครั้งเดียวและปิดฝาอบต่อ"},"instruction":{"zh-TW":"開蓋，用雙鏟果斷翻面（讓五花肉朝下貼著鍋面）！此時五花肉會釋放豐沛豬油，將底面煎得噴香金黃酥脆。蓋上鍋蓋繼續中小火燜煎 5 分鐘。","en":"Remove lid, use two spatulas to flip decisively so pork touches the hot pan directly! Pork fat will render and crisp the base. Cover and cook for 5 mins.","ja":"フタを取り、2枚のフライ返しで思い切って一気に裏返します！豚の脂で香ばしくカリカリに焼き上げます。再びフタをして5分蒸し焼き。","ko":"뒤집개 두 개로 단숨에 뒤집어 삼겹살 면이 바닥에 닿게 합니다. 돼지기름으로 바삭해지도록 뚜껑 덮고 5분간 익힙니다.","th":"เปิดฝา ใช้ตะหลิวสองอันพลิกกลับด้านอย่างรวดเร็ว ให้หมูสามชั้นนาบกระทะ ปิดฝาอบต่ออีก 5 นาที"},"durationSeconds":300,"image":"/images/jp/okonomiyaki-step4.jpg","dangerWarnings":{"zh-TW":"嚴禁用鏟子去重重按壓餅身！按壓會擠出高湯蒸氣，讓餅身變死硬扁塌！","en":"NEVER press down with spatulas! Pressing squeezes out steam and deflates your fluffy texture into rubber.","ja":"絶対にヘラで上から押さえつけないでください！中の空気が抜けて固くなります。","ko":"절대로 뒤집개로 꾹꾹 누르지 마세요! 수분과 공기가 빠져나가 퍽퍽해집니다.","th":"ห้ามใช้ตะหลิวกดทับลงบนแผ่นแป้งเด็ดขาด จะทำให้ไอน้ำระเหยหมดและแป้งเหนียวแข็ง"}},{"stepNumber":5,"title":{"zh-TW":"回正翻面與雙醬拉花 (Flip Back & Glaze)","en":"Flip Back, Sauce & Mayo Art","ja":"表に戻しソースとマヨネーズで化粧","ko":"다시 뒤집어 소스와 마요네즈 토핑","th":"พลิกกลับด้านเดิม ทาซอสและบีบมายองเนสสวยงาม"},"instruction":{"zh-TW":"再次翻面讓酥脆的五花肉面朝上。豪邁刷滿濃厚御好燒醬，以擠醬瓶交叉擠上細密的美乃滋線條，撒滿青海苔粉，最後堆疊滿滿跳舞柴魚片，大功告成！","en":"Flip one last time so the crispy pork faces up. Slather generously with Okonomi sauce, zigzag Kewpie mayo in fine stripes, dust with aonori and crown with dancing bonito flakes.","ja":"もう一度裏返して豚肉面を上に。お好みソースをたっぷり塗り、マヨネーズを線描きします。青のりと花かつおを踊らせて完成！","ko":"삼겹살이 위로 오도록 한 번 더 뒤집고, 오코노미 소스를 듬뿍 바른 후 마요네즈, 파래가루, 가쓰오부시를 얹습니다.","th":"พลิกด้านหมูกลับขึ้นมา ทาซอสโอโคโนมิยากิ บีบมายองเนส โรยสาหร่ายผงและปลาแห้งขูด พร้อมเสิร์ฟ"},"durationSeconds":120,"image":"/images/jp/okonomiyaki-step5.jpg"}],"troubleshooting":[{"id":"trouble-oko-1","problem":{"zh-TW":"翻面時容易四分五裂碎開？","en":"Why does the pancake break apart when flipping?","ja":"ひっくり返す時に崩れて割れてしまいます。","ko":"뒤집을 때 모양이 부서져요.","th":"ทำไมเวลาพลิกกลับด้านแล้วแตกกระจายไม่เป็นแผ่น?"},"cause":{"zh-TW":"底面尚未煎出微焦硬皮，或者使用的鏟子太小支力道不均。","en":"Underneath crust hasn’t solidified yet, or spatulas are too small.","ja":"底面の焼き固まりが不十分、またはヘラが小さすぎることが原因。","ko":"밑면이 충분히 노릇하게 굳지 않았거나 뒤집개가 너무 작기 때문입니다.","th":"ก้นกระทะยังไม่เกรียมเซ็ตตัวแข็งพอ หรือตะหลิวเล็กเกินไป"},"solution":{"zh-TW":"新手可用大平盤倒扣法：將盤子倒扣在鍋內，一口氣翻轉倒出，再滑回平底鍋中，零失誤率！","en":"Plate method: Invert a large plate over the skillet, flip the pan onto the plate, then slide it back in.","ja":"お皿をフライパンに被せてひっくり返し、そのままスライドさせて戻すと絶対に失敗しません！","ko":"큰 접시를 팬 위에 덮고 뒤집은 뒤 다시 프라이팬으로 밀어 넣으면 100% 성공합니다.","th":"ใช้จานแบนใบใหญ่คว่ำบนกระทะแล้วพลิกคว่ำลงจาน จากนั้นเลื่อนกลับลงกระทะอย่างง่ายดาย"}}],"proTips":[{"zh-TW":"【加蓋燜煎是關鍵】：厚切御好燒不能一直開蓋乾煎，加蓋能利用內部高麗菜蒸發的水氣把厚餅中心蒸至滑嫩多汁！","en":"Covering with a lid turns your pan into a mini convection oven, steaming the thick core while browning the crust.","ja":"【フタをして蒸し焼き】：フタをすることでキャベツの水分で中心までふっくらジューシーに火が通ります。","ko":"뚜껑을 덮어 증기로 찌듯 익혀야 겉은 바삭하고 속은 촉촉한 두께 2cm 오코노미야키가 완성됩니다.","th":"การปิดฝาจะช่วยอบความร้อนให้สุกทั่วถึงทั้งแผ่นโดยที่ผิวนอกยังกรอบนุ่ม"}]},{"country":"jp","id":"yakitori-negima","slug":"yakitori-negima","title":{"zh-TW":"炭火醬燒雞肉蔥串","en":"Charcoal Grilled Yakitori Negima","ja":"炭火焼き鳥 ねぎま（秘伝タレ／塩）","ko":"숯불 야키토리 파닭꼬치 (네기마)","th":"ยากิโทริ ไก่เสียบไม้ต้นหอมย่างซอสทาเระ"},"subtitle":{"zh-TW":"鮮嫩雞腿肉交錯焦甜大蔥、秘傳鹹甜醬汁多次浸刷","en":"Juicy chicken thighs alternated with caramelized Tokyo scallions dipped in tare glaze","ja":"ジューシーな鶏もも肉と甘み溢れる白ねぎ、香ばしい秘伝醤油タレが絡む極上串","ko":"육즙 가득한 닭다리살과 달콤한 대파의 조화, 단짠 비법 타레 소스","th":"เนื้อสะโพกไก่นุ่มชุ่มฉ่ำ สลับกับต้นหอมญี่ปุ่นย่างเกรียมหอมหวาน จุ่มซอสทาเระเข้มข้น"},"tagline":{"zh-TW":"日本居酒屋靈魂看板料理！在家用平底鍋、烤箱或氣炸鍋重現道地炭香！","en":"The quintessential Japanese Izakaya skewer, adaptable to home stovetop and air fryers.","ja":"居酒屋の大定番！家庭の魚焼きグリルやフライパンでも本格的な焼き上がりに。","ko":"이자카야의 영원한 베스트셀러! 집에서도 불맛 가득하게 완성.","th":"เมนูอันดับหนึ่งประจำร้านอิซากายะ ย่างบนกระทะหรือหม้อทอดไร้น้ำมันได้ความหอมเหมือนเตาถ่าน"},"heroImage":"/images/jp/yakitori-hero.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":280,"category":"yakimono","dietaryTags":["classic","halal"],"supportedCookware":["traditional","airFryer","oven"],"culture":{"originRegion":{"zh-TW":"東京都新宿區・思出橫丁 (Tokyo)","en":"Tokyo, Kanto Region","ja":"東京都・浅草および新宿思い出横丁","ko":"도쿄도 신주쿠","th":"โตเกียว ภูมิภาคคันโต"},"famousYataiMarkets":[{"zh-TW":"東京新宿思出橫丁","en":"Omoide Yokocho, Shinjuku","ja":"新宿思い出横丁","ko":"신주쿠 오모이데 요코초","th":"โอโมอิเดะ โยโกโช ชินจูกุ"},{"zh-TW":"福岡中洲屋台","en":"Nakasu Yatai, Fukuoka","ja":"福岡中洲屋台","ko":"후쿠오카 나카스 야타이","th":"ร้านยาไตนาคาสุ ฟุกุโอกะ"}],"historyStory":{"zh-TW":"烤雞肉串自江戶時代即有記載，戰後在東京思出橫丁等黑市巷弄發揚光大，利用竹籤穿刺一口大小雞肉，在備長炭火上高溫急速炙烤鎖住肉汁，成為上班族下班洗去疲憊的心靈綠洲。","en":"Evolving since the Edo period and flourishing post-WWII in Tokyo alleys. Skewered chicken seared over binchotan charcoal creates an irresistible smoky crust.","ja":"江戸時代から庶民に親しまれ、戦後の横丁で一気に大衆文化として定着。炭火の強火で一気に旨味を閉じ込めるのが職人の技です。","ko":"에도 시대부터 이어져 온 서민 요리로, 직장인들의 고단함을 달래주는 퇴근길 대표 안주입니다.","th":"มีมาตั้งแต่ยุคเอโดะ ย่างบนเตาถ่านไฟแรงเพื่อล็อกความชุ่มฉ่ำของเนื้อไก่ด้านใน"},"japaneseKanji":"焼き鳥 ねぎま","japaneseKana":"やきとり ねぎま","japaneseRomaji":"Yakitori Negima","audioPronunciationText":"焼き鳥 ねぎま","nativeName":"焼き鳥 ねぎま","nativePhonetics":"やきとり ねぎま"},"ingredients":[{"id":"chicken-thigh","name":{"zh-TW":"帶皮去骨雞腿肉 (Boneless Chicken Thigh with skin)","en":"Boneless skin-on chicken thighs","ja":"鶏もも肉（皮付き）","ko":"껍질 있는 닭다리살","th":"สะโพกไก่ติดหนังเลาะกระดูก"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":true,"japaneseKanji":"鶏もも肉","japaneseKana":"とりももにく","japaneseRomaji":"Tori Momo Niku"},{"id":"tokyo-negi","name":{"zh-TW":"日本大蔥白或京蔥 (Tokyo Scallions / Leek)","en":"Japanese Long Scallion (Negi)","ja":"白ねぎ（長ねぎ）","ko":"대파 (흰 대 부분)","th":"ต้นหอมญี่ปุ่นท่อนขาว"},"amount":2,"unitMetric":"stalk","unitUS":"stalk","isKeyFlavor":true,"japaneseKanji":"白ねぎ","japaneseKana":"しろねぎ","japaneseRomaji":"Shiro Negi"},{"id":"shoyu","name":{"zh-TW":"濃口醬油 (Dark Soy Sauce)","en":"Japanese Soy Sauce (Koikuchi)","ja":"濃口醤油","ko":"진간장","th":"โชยุญี่ปุ่นสูตรเข้มข้น"},"amount":45,"unitMetric":"ml","unitUS":"3 tbsp","japaneseKanji":"濃口醤油","japaneseKana":"こいくちしょうゆ","japaneseRomaji":"Koikuchi Shōyu"},{"id":"mirin","name":{"zh-TW":"味醂 (Hon Mirin)","en":"Hon-Mirin","ja":"本みりん","ko":"미림","th":"มิริน"},"amount":45,"unitMetric":"ml","unitUS":"3 tbsp","japaneseKanji":"本みりん","japaneseKana":"ほんみりん","japaneseRomaji":"Hon-Mirin"},{"id":"sake","name":{"zh-TW":"料理清酒 (Cooking Sake)","en":"Cooking Sake","ja":"清酒（料理酒）","ko":"청주","th":"สาเกปรุงอาหาร"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","japaneseKanji":"料理酒","japaneseKana":"りょうりしゅ","japaneseRomaji":"Ryōrishu"},{"id":"sugar","name":{"zh-TW":"三溫糖或黃糖 (Brown Sugar)","en":"Sugar","ja":"三温糖または上白糖","ko":"황설탕","th":"น้ำตาลทรายแดง"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","japaneseKanji":"砂糖","japaneseKana":"さとう","japaneseRomaji":"Satō"},{"id":"shichimi","name":{"zh-TW":"七味唐辛子 (Shichimi Togarashi)","en":"Japanese Seven Spice","ja":"七味唐辛子","ko":"시치미 토가라시","th":"พริกไทยเจ็ดรสชิจิมิ"},"amount":2,"unitMetric":"g","unitUS":"1/2 tsp","japaneseKanji":"七味唐辛子","japaneseKana":"しちみとうがらし","japaneseRomaji":"Shichimi Tōgarashi"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"熬製秘傳醬汁 (Simmer Tare Glaze)","en":"Simmer the Tare Glaze","ja":"秘伝のタレを煮詰める","ko":"비법 타레 소스 졸이기","th":"เคี่ยวซอสทาเระ"},"instruction":{"zh-TW":"將醬油、味醂、清酒、砂糖倒入小鍋中，小火煮滾約 4-5 分鐘，略微濃縮呈現光澤糖蜜狀，關火備用（烤製時用來反覆刷烤）。","en":"In a small saucepot, bring soy sauce, mirin, sake, and sugar to a gentle boil. Simmer for 4-5 mins until glossy and slightly syrupy.","ja":"小鍋に醤油、みりん、酒、砂糖を入れて火にかけ、弱火で4〜5分ほど軽くとろみがつくまで煮詰めます。","ko":"냄비에 간장, 미림, 청주, 설탕을 넣고 약불에서 4~5분간 윤기가 돌 때까지 조려줍니다.","th":"ใส่โชยุ มิริน สาเก และน้ำตาลลงหม้อ เคี่ยวไฟอ่อน 4-5 นาทีจนเริ่มงวดและขึ้นเงา"},"durationSeconds":300,"image":"/images/jp/yakitori-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"分切與穿串 (Cut & Skewer)","en":"Cut Chicken & Skewer with Negi","ja":"鶏肉とねぎをカットし串打ちする","ko":"닭고기와 파를 썰어 꼬치에 꿰기","th":"หั่นไก่และต้นหอมแล้วเสียบไม้"},"instruction":{"zh-TW":"竹籤事先泡水 15 分鐘防燒焦。雞腿肉切成約 3 公分立方塊，大蔥切 3 公分蔥段。以「肉塊-蔥段-肉塊-蔥段-肉塊」的順序緊密穿串，每串穿 3 塊肉、2 段蔥。","en":"Soak skewers in water for 15 mins. Cut chicken into 3 cm cubes, slice negi into 3 cm batons. Alternate chicken and scallion (3 chicken, 2 negi per skewer).","ja":"竹串を水に15分浸しておく。鶏もも肉は一口大、ねぎは3cm長さに切り、「肉・ねぎ・肉・ねぎ・肉」の順にぎゅっと隙間なく刺します。","ko":"대나무 꼬치를 물에 15분간 담가둡니다. 닭고기와 대파를 3cm로 썰어 고기-파-고기-파-고기 순으로 촘촘히 꿰어줍니다.","th":"แช่ไม้เสียบในน้ำ 15 นาที หั่นไก่และต้นหอมยาว 3 ซม. เสียบสลับกัน ไก่-ต้นหอม-ไก่-ต้นหอม-ไก่"},"durationSeconds":360,"image":"/images/jp/yakitori-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"初次乾煎至微金黃 (First Sear)","en":"Initial High-Heat Sear","ja":"まずは素焼きで香ばしく両面を焼く","ko":"양념 없이 초벌구이로 겉면 익히기","th":"ย่างด้านนอกให้เหลืองหอมรอบแรก"},"instruction":{"zh-TW":"平底鍋薄薄刷油，中大火將肉串排入（先不刷醬汁！先刷醬容易焦黑）。煎烤約 2-3 分鐘至雞肉轉白帶金黃焦斑，翻面再煎 2 分鐘。","en":"Heat a lightly oiled skillet on medium-high. Sear skewers unglazed first for 2-3 mins until golden, then flip for 2 mins. (Unglazed first prevents burning!)","ja":"フライパンに薄く油をひき、タレは塗らずに素焼きします。中火で2〜3分、こんがり焼き色がついたら裏返します。","ko":"팬에 꼬치를 올리고 양념 바르지 않은 상태로 2~3분간 노릇하게 굽고 뒤집습니다.","th":"ทาน้ำมันบางๆ นำไก่ลงย่างโดยยังไม่ทาซอส เพื่อป้องกันไม่ให้ซอสไหม้ ย่างด้านละ 2-3 นาที"},"durationSeconds":300,"image":"/images/jp/yakitori-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"氣炸鍋模式：200°C (390°F) 烤 10 分鐘，第 6 分鐘刷醬翻面","instructionOverride":{"zh-TW":"氣炸鍋 200°C 預熱，底層鋪烘焙紙，肉串平鋪先氣炸 6 分鐘，取出兩面刷滿醬汁，再氣炸 4 分鐘至焦香撲鼻。","en":"Air Fryer at 200°C for 6 mins plain. Pull out, generously brush both sides with tare glaze, air fry 4 more mins.","ja":"ノンフライヤー200℃でまず6分素焼き。取り出してタレを両面にたっぷり塗り、さらに4分香ばしく焼き上げます。","ko":"에어프라이어 200도에서 6분간 먼저 굽고, 꺼내서 타레 소스를 앞뒤로 바른 뒤 4분간 더 굽습니다.","th":"หม้อทอดไร้น้ำมัน 200°C ย่าง 6 นาที นำออกมาทาซอสทั้งสองด้าน แล้วอบต่ออีก 4 นาที"}}]},{"stepNumber":4,"title":{"zh-TW":"反覆刷醬焦糖化 (Double Glaze & Caramelize)","en":"Double Tare Glazing & Caramelization","ja":"タレを2回重ねづけして照りを出す","ko":"타레 소스를 두 번 발라 캐러멜라이징","th":"ทาซอสซ้ำและย่างต่อให้ขึ้นเงาคาราเมล"},"instruction":{"zh-TW":"轉中小火。用油刷將熱醬汁厚厚刷在肉串兩面，煎 30 秒至醬汁冒泡收乾；再次刷上一層醬汁，迅速翻面炙烤 30 秒，形成晶亮紅潤的醬油焦糖光澤！","en":"Turn heat to medium-low. Brush tare generously over both sides, sizzle for 30s until bubbling. Apply a 2nd coat, flash-sear for 30s for a glossy lacquer finish.","ja":"火を弱め、ハケでタレをたっぷり塗って30秒。さらにタレを重ね塗りし、香ばしい照りが出るまで素早く炙ります。","ko":"약불로 줄이고 타레 소스를 듬뿍 발라 30초, 다시 한 번 덧발라 윤기 나는 갈색이 될 때까지 구워줍니다.","th":"ลดไฟลง ทาซอสทาเระให้ทั่วทั้งสองด้าน ย่าง 30 วินาที แล้วทาซ้ำอีกรอบให้ซอสซึมเข้าเนื้อเกิดความเงางาม"},"durationSeconds":90,"image":"/images/jp/yakitori-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"裝盤撒粉開動 (Plate & Seven Spice)","en":"Plate with Shichimi Togarashi","ja":"盛り付けて七味唐辛子を添える","ko":"접시에 담고 시치미 곁들이기","th":"จัดจานและโรยพริกชิจิมิ"},"instruction":{"zh-TW":"將肉串起鍋擺盤，淋上鍋底殘存的香濃醬汁。附上日式七味唐辛子或山椒粉，搭配冰涼生啤酒，大口咬下品味炭火與肉汁的交融！","en":"Transfer to a serving board. Drizzle remaining tare over top. Dust with fragrant shichimi togarashi or sansho pepper. Serve with cold beer!","ja":"お皿に盛り、残ったタレを回しかけます。七味唐辛子や山椒を振って、アツアツをお召し上がりください！","ko":"접시에 담고 남은 소스를 살짝 끼얹은 뒤 시치미나 산초가루를 곁들여 맥주와 함께 즐깁니다.","th":"ตักใส่จาน ราดซอสที่เหลือเล็กน้อย โรยพริกชิจิมิหรือผงซันโช ทานคู่กับเครื่องดื่มเย็นฉ่ำ"},"durationSeconds":30,"image":"/images/jp/yakitori-step5.jpg"}],"troubleshooting":[{"id":"trouble-yaki-1","problem":{"zh-TW":"為什麼雞肉外層焦黑了，裡面卻還帶血水沒熟？","en":"Why is the surface blackened while the core is still raw?","ja":"外側が焦げて中が生焼けになってしまいます。","ko":"겉은 탔는데 속은 덜 익었어요.","th":"ทำไมเนื้อไก่ข้างนอกไหม้แต่ข้างในยังไม่สุก?"},"cause":{"zh-TW":"一開始就刷了帶糖的醬汁，或者是火開太大、雞肉切得太大塊。","en":"Applied sugary tare too early, heat was excessively high, or chicken chunks cut too thick.","ja":"最初からタレを塗って焼いたか、火が強すぎたことが原因です。","ko":"처음부터 양념을 바르고 구웠거나 불이 너무 세고 고기가 너무 컸기 때문입니다.","th":"ทาซอสตั้งแต่แรก หรือใช้ไฟแรงเกินไปและหั่นชิ้นไก่หนาเกินไป"},"solution":{"zh-TW":"務必遵守「先乾煎到 8 分熟，最後起鍋前 1 分鐘才刷醬」的黃金定律！","en":"Always follow the rule: Sear unglazed until 80% cooked, glaze tare only during the final 60 seconds.","ja":"「最初は素焼き、最後にタレを絡める」を守れば絶対に焦げません。","ko":"반드시 80% 정도 구워진 뒤 마지막 1분 전에 양념을 발라주세요.","th":"ย่างเนื้อเปล่าให้สุก 80% ก่อน แล้วจึงทาซอสในช่วง 1 นาทีสุดท้าย"}}],"proTips":[{"zh-TW":"【帶皮雞腿更香脆】：穿串時刻意將雞皮朝向外側，雞皮的高溫焦化能保護雞腿肉汁不乾柴，一口咬下外脆肉嫩！","en":"Position the chicken skin facing outward; skin fats render to baste the skewer and seal in moisture.","ja":"【皮目を外側に揃える】：皮を外側にして串打ちすることで、余分な脂が落ちてパリッと香ばしくなります。","ko":"닭껍질이 겉으로 오게 꿰면 구워지며 바삭해지고 고기의 육즙을 꽉 잡아줍니다.","th":"หันด้านหนังไก่ออกด้านนอก หนังจะกรอบและช่วยกักเก็บน้ำหวานในเนื้อไก่ไม่ให้แห้ง"}]},{"country":"jp","id":"karaage","slug":"japanese-karaage-chicken","title":{"zh-TW":"日式居酒屋唐揚炸雞","en":"Japanese Izakaya Karaage","ja":"極上ジューシー 鶏の唐揚げ","ko":"이자카야 스타일 일본식 닭튀김 (가라아게)","th":"ไก่ทอดคาราอาเกะ สไตล์อิซากายะ"},"subtitle":{"zh-TW":"雙重油炸極致酥脆、生薑醬油醃汁入味、咬下爆汁噴香","en":"Double-fried for glass-like shatter crust, ginger-soy marinade bursting with juice","ja":"二度揚げでサクッとジューシー！生姜とニンニク香る黄金比タレ仕込み","ko":"두 번 튀겨 극강의 바삭함! 생강과 마늘 향이 은은한 육즙 폭발 닭튀김","th":"ทอดสองรอบเพื่อความกรอบขั้นสุด หมักขิงและโชยุเข้าเนื้อ ชุ่มฉ่ำเต็มคำ"},"tagline":{"zh-TW":"日本定食與居酒屋點檯率 No.1，掌握片栗粉（太白粉）與雙炸溫控秘訣！","en":"Japan’s #1 Izakaya staple. Master the potato starch crust & double-fry technique.","ja":"大人も子供も大好きな国民的おかず！片栗粉の軽やかな衣と二度揚げが決め手。","ko":"이자카야 주문 1위! 감자 전분과 두 번 튀기기로 만드는 인생 가라아게.","th":"เมนูยอดนิยมตลอดกาล เคล็ดลับแป้งมันฝรั่งทอดสองรอบ กรอบนานไม่อมน้ำมัน"},"heroImage":"/images/jp/karaage-hero.jpg","difficulty":"easy","prepTimeMinutes":25,"cookTimeMinutes":12,"defaultServings":3,"caloriesPerServing":360,"category":"agemono","dietaryTags":["classic","halal"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"大分縣中津市・宇佐市 (Oita)","en":"Nakatsu, Oita Prefecture (The Karaage Holy Land)","ja":"大分県中津市（からあげの聖地）","ko":"오이타현 나카츠시 (가라아게의 성지)","th":"เมืองนาคัตสึ จังหวัดโออิตะ"},"famousYataiMarkets":[{"zh-TW":"九州大分中津炸雞聖地巡禮","en":"Nakatsu Karaage Street, Oita","ja":"中津からあげ巡礼街","ko":"나카츠 가라아게 성지순례","th":"ถนนไก่ทอดนาคัตสึ โออิตะ"},{"zh-TW":"東京新宿思出橫丁居酒屋","en":"Shinjuku Izakaya Alley, Tokyo","ja":"新宿西口居酒屋街","ko":"신주쿠 골목 이자카야","th":"ร้านอิซากายะ ชินจูกุ"}],"historyStory":{"zh-TW":"唐揚雞起源於江戶時代，昭和初期由大分縣中津與宇佐一帶推廣為大眾美食，利用生薑、蒜泥、濃口醬油與清酒深層浸泡雞肉，並裹上輕盈的日本馬鈴薯澱粉（片栗粉），成就外皮輕薄如紙脆、內部肉汁四濺的極品滋味。","en":"Perfected in Oita prefecture. The secret lies in potato starch (Katakuriko) which creates a delicate, shatteringly crisp shell while keeping the inside deeply marinated.","ja":"昭和初期、大分県中津で養鶏が盛んだったことから発展。片栗粉を使った薄衣と、ニンニク生姜の醤油漬け込みが日本のソウルフードに。","ko":"오이타현에서 발전한 일본식 닭튀김으로, 감자 전분으로 얇고 바삭한 튀김옷을 입혀 육즙을 가두는 것이 특징입니다.","th":"พัฒนาขึ้นในจังหวัดโออิตะ หมักด้วยโชยุ ขิงบด และกระเทียม ชุบแป้งมันฝรั่งทอดจนกรอบเบา"},"japaneseKanji":"鶏の唐揚げ","japaneseKana":"とりのからあげ","japaneseRomaji":"Tori no Karaage","audioPronunciationText":"唐揚げ","nativeName":"鶏の唐揚げ","nativePhonetics":"とりのからあげ"},"ingredients":[{"id":"chicken-thigh","name":{"zh-TW":"去骨帶皮雞腿肉 (Chicken Thighs)","en":"Boneless skin-on chicken thighs","ja":"鶏もも肉","ko":"닭다리살 (정육)","th":"สะโพกไก่เลาะกระดูกติดหนัง"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"japaneseKanji":"鶏もも肉","japaneseKana":"とりももにく","japaneseRomaji":"Tori Momo Niku"},{"id":"shoyu","name":{"zh-TW":"濃口醬油 (Koikuchi Soy Sauce)","en":"Japanese Soy Sauce","ja":"濃口醤油","ko":"진간장","th":"โชยุญี่ปุ่น"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","japaneseKanji":"醤油","japaneseKana":"しょうゆ","japaneseRomaji":"Shōyu"},{"id":"sake","name":{"zh-TW":"料理清酒 (Cooking Sake)","en":"Cooking Sake","ja":"清酒","ko":"청주","th":"สาเก"},"amount":15,"unitMetric":"ml","unitUS":"1 tbsp","japaneseKanji":"料理酒","japaneseKana":"りょうりしゅ","japaneseRomaji":"Ryōrishu"},{"id":"ginger-garlic","name":{"zh-TW":"現磨生薑泥與蒜泥 (Grated Ginger & Garlic)","en":"Freshly grated ginger and garlic","ja":"すりおろし生姜・にんにく","ko":"간 생강과 다진 마늘","th":"ขิงขูดและกระเทียมขูดสด"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","isKeyFlavor":true,"japaneseKanji":"生姜・にんにく","japaneseKana":"しょうが・にんにく","japaneseRomaji":"Shōga / Ninniku"},{"id":"sesame-oil","name":{"zh-TW":"純黑麻油 (Pure Sesame Oil)","en":"Toasted Sesame Oil","ja":"純正ごま油","ko":"참기름","th":"น้ำมันงาบริสุทธิ์"},"amount":5,"unitMetric":"ml","unitUS":"1 tsp","japaneseKanji":"ごま油","japaneseKana":"ごまあぶら","japaneseRomaji":"Goma Abura"},{"id":"katakuriko","name":{"zh-TW":"日本片栗粉 / 馬鈴薯澱粉 (Potato Starch)","en":"Japanese Potato Starch (Katakuriko)","ja":"片栗粉（馬鈴薯澱粉）","ko":"감자 전분 (카타쿠리코)","th":"แป้งมันฝรั่งญี่ปุ่น (คาตาคุริโกะ)"},"amount":60,"unitMetric":"g","unitUS":"1/2 cup","isKeyFlavor":true,"japaneseKanji":"片栗粉","japaneseKana":"かたくりこ","japaneseRomaji":"Katakuriko","substitute":{"substituteName":{"zh-TW":"玉米澱粉 (Cornstarch)","en":"Cornstarch","ja":"コーンスターチ","ko":"옥수수 전분","th":"แป้งข้าวโพด"},"ratio":"1:1","explanation":{"zh-TW":"玉米澱粉也能炸出酥脆效果，但日本片栗粉顆粒感更好、吸油量更低。","en":"Cornstarch works nicely, though potato starch creates a lighter, crunchier shell.","ja":"コーンスターチでも代用できますが、片栗粉のほうがサクサクに仕上がります。","ko":"옥수수 전분으로 대체 가능하나 감자 전분이 더 바삭하고 기름을 덜 먹습니다.","th":"ใช้แป้งข้าวโพดแทนได้ แต่แป้งมันฝรั่งจะให้ความกรอบโปร่งและไม่อมน้ำมันมากกว่า"},"whereToBuy":{"zh-TW":"一般超市烘焙區或亞超","en":"Baking aisle or Asian grocery","ja":"スーパーの粉類コーナー","ko":"마트 전분 코너","th":"ซูเปอร์มาร์เก็ตแผนกแป้งทำอาหาร"}}},{"id":"lemon","name":{"zh-TW":"黃檸檬角 (Fresh Lemon Wedges)","en":"Lemon wedges for serving","ja":"レモン（くし形切り）","ko":"레몬 조각","th":"เลมอนหั่นเสี้ยว"},"amount":1,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"レモン","japaneseKana":"れもん","japaneseRomaji":"Remon"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"分切與抓醃入味 (Cut & Marinate)","en":"Cut & Marinate Chicken","ja":"鶏肉を切り下味を揉み込む","ko":"닭고기 손질 및 양념에 재우기","th":"หั่นชิ้นและคลุกเคล้าหมักให้เข้าเนื้อ"},"instruction":{"zh-TW":"雞腿肉切成約 4 公分的大一口塊（切太小容易炸乾炸柴）。放入保鮮袋或碗中，加入醬油、清酒、生薑泥、蒜泥、黑麻油與一小撮糖。用手用力抓揉按摩 2 分鐘，冷藏醃製 20-30 分鐘讓肉質吸飽汁水。","en":"Cut chicken into generous 4 cm cubes. In a bowl, massage with soy sauce, sake, ginger, garlic, sesame oil, and pinch of sugar for 2 mins. Marinate for 20-30 mins.","ja":"鶏肉は大きめの一口大（約4cm）に切る。ボウルに調味料を合わせ、手で揉み込んで20〜30分しっかり味を染み込ませます。","ko":"닭고기를 큼직한 한입 크기(4cm)로 썰어 양념을 넣고 손으로 조물조물 마사지한 뒤 20~30분간 재웁니다.","th":"หั่นไก่ชิ้นใหญ่พอดีคำ 4 ซม. ใส่เครื่องปรุงทั้งหมดแล้วนวดคลุกเคล้า 2 นาที หมักไว้ 20-30 นาที"},"durationSeconds":1200,"image":"/images/jp/karaage-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"輕盈裹粉防返潮 (Dredge in Starch)","en":"Light Dredge in Potato Starch","ja":"余分なタレを切り片栗粉をまぶす","ko":"양념 털어내고 감자 전분 가볍게 묻히기","th":"ซับน้ำหมักส่วนเกินแล้วคลุกแป้งมันฝรั่ง"},"instruction":{"zh-TW":"將雞肉取出，用廚房紙巾輕輕吸去表面過多滴落的醬汁（避免粉衣太濕）。將肉塊均勻滾上一層片栗粉，雙手輕拍抖掉多餘乾粉，靜置 3 分鐘讓粉略為回潮。","en":"Dab off excess marinade with paper towel. Dredge each piece generously in potato starch, shaking off excess so only a thin translucent veil remains. Rest for 3 mins.","ja":"余分な水分を軽く切り、片栗粉をまんべんなくまぶして余分な粉をはたき落とします。3分ほど置いて粉を落ち着かせます。","ko":"여분의 양념 국물을 살짝 털어내고 감자 전분을 골고루 묻힌 뒤 여분의 가루를 털어냅니다. 3분간 휴지합니다.","th":"ซับน้ำหมักส่วนเกิน คลุกแป้งมันฝรั่งให้ทั่ว เคาะแป้งส่วนเกินออก พักไว้ 3 นาที"},"durationSeconds":180,"image":"/images/jp/karaage-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"氣炸鍋模式：190°C (375°F) 氣炸 12 分鐘，中途翻面噴少許油","instructionOverride":{"zh-TW":"將裹粉雞塊表面均勻噴上一層薄油，放入氣炸鍋籃中不重疊，以 190°C 氣炸 8 分鐘，翻面再氣炸 4 分鐘至金黃香脆。","en":"Mist coated chicken with cooking oil spray. Arrange in single layer, air fry at 190°C for 8 mins, flip, spray again, fry 4 more mins.","ja":"表面に油をスプレーし、重ならないように並べて190℃で8分加熱。裏返してさらに4分加熱します。","ko":"닭고기 겉면에 오일을 살짝 분사하고 190도에서 8분간 조리 후 뒤집어 4분간 더 바삭하게 익힙니다.","th":"ฉีดน้ำมันบางๆ วางเรียงไม่ซ้อนกัน อบที่ 190°C นาน 8 นาที กลับด้านอบต่ออีก 4 นาที"}}]},{"stepNumber":3,"title":{"zh-TW":"第一炸：中溫低火熟化 (1st Fry: Low & Slow)","en":"First Fry at 160°C (320°F)","ja":"一度目：160℃の低温でじっくり火を通す","ko":"1차 튀김: 160도 중저온에서 속까지 익히기","th":"ทอดรอบแรก: ไฟกลาง 160°C ให้สุกถึงด้านใน"},"instruction":{"zh-TW":"油鍋升溫至 160°C（插入木筷邊緣冒出微小細泡）。將雞肉分批下鍋（切忌一次放太多降低油溫），炸約 3-4 分鐘至表皮呈淡米黃色、筷子戳進去無血水，撈起瀝油，靜置在架上休息 3 分鐘（利用餘熱把中心熟透）。","en":"Heat oil to 160°C (320°F). Fry in small batches for 3-4 mins until light blonde. Drain onto a wire rack and let rest for 3 mins (residual heat finishes the interior gently).","ja":"油を160℃に熱し、鶏肉を投入して3〜4分揚げます。薄い揚げ色がついたらバットに取り出し、余熱で3分休ませます。","ko":"160도 기름에 넣고 3~4분간 튀겨 연한 노란색이 되면 건져내어 3분간 레스팅합니다 (잔열로 속 익히기).","th":"ตั้งน้ำมัน 160°C ใส่ไก่ลงทอด 3-4 นาทีจนสุกสีเหลืองอ่อน ตักขึ้นพักบนตะแกรง 3 นาที"},"durationSeconds":240,"image":"/images/jp/karaage-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"第二炸：高溫搶酥逼油 (2nd Fry: High Heat Crunch)","en":"Second Flash Fry at 185°C (365°F)","ja":"二度目：185℃の高温でカラッと二度揚げ","ko":"2차 튀김: 185도 고온에서 바삭하게 겉면 튀기기","th":"ทอดรอบสอง: ไฟแรง 185°C ไล่น้ำมันและกรอบสะใจ"},"instruction":{"zh-TW":"將油溫拉高至 185-190°C（木筷插入冒強烈大泡）。將瀝乾休息後的雞肉再次推入熱油中，用漏勺在油中來回翻動與高高夾出接觸空氣（空氣脆皮法），大火高溫炸 45-60 秒，直到外皮化為誘人的金棕深金黃色，立刻起鍋瀝油！","en":"Crank heat to 185°C (365°F). Re-drop rested chicken and flash-fry for 45-60s, tossing occasionally into the air for maximum crackly crust. Pull immediately onto paper towels.","ja":"油温を185℃まで上げ、肉を戻して45〜60秒間一気に揚げます。時々空気に触れさせるとさらにサクサクに！きつね色になったら完成。","ko":"기름 온도를 185도로 올려 45~60초간 빠르게 2차로 튀겨냅니다. 공기와 접촉시키며 튀기면 극강의 바삭함이 완성됩니다.","th":"เร่งไฟให้น้ำมันร้อน 185°C นำไก่ลงทอดรอบสอง 45-60 วินาที ยกขึ้นสัมผัสอากาศเป็นระยะเพื่อให้กรอบจัด"},"durationSeconds":60,"image":"/images/jp/karaage-step4.jpg","crucialTips":{"zh-TW":"「二次油炸 + 夾出接觸空氣」是居酒屋唐揚雞外皮咔滋作響、放涼 1 小時依然酥脆不軟爛的不二法門！","en":"The resting gap allows interior steam to escape; the second high-heat plunge instantly crisps the exterior without drying out meat.","ja":"二度揚げの間の「3分間の休息」で肉汁が落ち着き、二度目の高温で水分を飛ばして超カリカリになります！","ko":"중간 레스팅과 2차 고온 튀김이 식어도 눅눅해지지 않는 이자카야의 핵심 비법입니다.","th":"การพัก 3 นาทีระหว่างทอดสองรอบช่วยให้ความชื้นระบายออก ทอดรอบสองจึงกรอบสนั่นไม่เหี่ยว"}},{"stepNumber":5,"title":{"zh-TW":"擠檸檬趁熱享用 (Serve with Lemon)","en":"Plate with Fresh Lemon","ja":"レモンを添えて熱々をいただく","ko":"레몬을 곁들여 바로 서빙","th":"เสิร์ฟพร้อมเลมอนสด"},"instruction":{"zh-TW":"將金黃唐揚炸雞堆成小山擺盤，附上切塊新鮮黃檸檬與美乃滋。擠上幾滴酸香檸檬汁，中和油脂提鮮，大口咬下感受滾燙噴汁的快感！","en":"Mound onto a platter with lemon wedges and Kewpie mayo. Squeeze fresh lemon overtop to cut through the richness and enjoy piping hot!","ja":"お皿に高く盛り付け、くし形レモンとマヨネーズを添えます。アツアツの肉汁が弾ける瞬間をお楽しみください！","ko":"접시에 먹음직스럽게 쌓고 레몬 조각과 마요네즈를 곁들입니다. 상큼한 레몬즙을 뿌려 즐겨보세요!","th":"ตักขึ้นจัดจานเป็นทรงภูเขา เสิร์ฟคู่เลมอนสดและมายองเนส บีบเลมอนตัดเลี่ยน ทานร้อนๆ ทันที"},"durationSeconds":30,"image":"/images/jp/karaage-step5.jpg"}],"troubleshooting":[{"id":"trouble-karaage-1","problem":{"zh-TW":"為什麼炸出來外皮濕軟油膩，完全不脆？","en":"Why is the fried chicken greasy and soggy instead of crunchy?","ja":"衣がベチャッとして油っぽく、カリッとしません。","ko":"튀김옷이 눅눅하고 기름을 너무 많이 먹었어요.","th":"ทำไมไก่ทอดออกมานิ่มแฉะและอมน้ำมัน ไม่กรอบเลย?"},"cause":{"zh-TW":"油溫太低（低於 150°C）、一次丟入太多雞肉導致油溫暴跌，或是裹粉前沒有擦乾醬汁。","en":"Oil temperature was too low, overcrowded the pot, or excess marinade turned the starch into wet slurry before frying.","ja":"油の温度が低すぎたか、一度に肉を入れすぎて温度が下がってしまったことが原因です。","ko":"기름 온도가 낮거나 너무 많은 양을 한 번에 넣어 기름 온도가 급격히 떨어졌기 때문입니다.","th":"น้ำมันไม่ร้อนพอ ใส่ไก่ลงไปแน่นเกินไป หรือชุบแป้งตอนที่เนื้อไก่ยังเปียกโชก"},"solution":{"zh-TW":"分批油炸（每次不超過鍋面 1/2），裹粉前輕拭表面水份，並嚴格執行二次 185°C 高溫搶酥！","en":"Fry in smaller batches, pat chicken lightly dry before dredging, and always perform the 185°C second flash fry.","ja":"鍋の半分以下の量で揚げ、しっかり二度揚げで高温フィニッシュを徹底しましょう。","ko":"절반씩 나누어 튀기고 마지막 2차 고온 튀김을 반드시 거쳐 기름을 빼주세요.","th":"แบ่งทอดทีละน้อย ซับน้ำก่อนคลุกแป้ง และทอดซ้ำรอบสองด้วยไฟแรงเสมอ"}}],"proTips":[{"zh-TW":"【日本片栗粉 vs 麵粉】：傳統唐揚只用純片栗粉（馬鈴薯澱粉），炸出來具有獨特的透明薄脆「白霜鱗片」外觀，酥度持久且完全不厚重！","en":"Using 100% Katakuriko (potato starch) creates that iconic Izakaya white-frost shattered glass crust, far superior to flour.","ja":"【片栗粉100%がおすすめ】：小麦粉を使わず片栗粉だけにすることで、竜田揚げのような白い粉吹き衣と軽やかなクリスピー感が生まれます。","ko":"밀가루 대신 100% 감자 전분만 사용하면 눈꽃처럼 하얗고 가벼운 바삭함을 얻을 수 있습니다.","th":"ใช้แป้งมันฝรั่งแท้ 100% จะได้ผิวสัมผัสกรอบบางเบาเหมือนเกล็ดหิมะ ดีกว่าการใช้แป้งสาลี"}]},{"country":"jp","id":"oden-traditional","slug":"traditional-japanese-oden","title":{"zh-TW":"正宗關東煮黃金高湯","en":"Traditional Japanese Oden Hot Pot","ja":"極上出汁染み染み 本格おでん","ko":"정통 일본식 황금 육수 오뎅탕","th":"โอเด้งหม้อไฟน้ำซุปดาชิสีทอง"},"subtitle":{"zh-TW":"吸飽昆布柴魚高湯的透光白蘿蔔、油豆腐與彈牙竹輪","en":"Translucent daikon, fried tofu and fishcakes simmered in golden kombu-bonito broth","ja":"昆布と鰹の黄金出汁が芯まで染みた大根と玉子、屋台の冬の定番","ko":"가쓰오부시와 다시마 육수가 깊게 밴 투명한 무와 어묵의 깊은 풍미","th":"หัวไชเท้าฉ่ำน้ำซุปดาชิปลาแห้ง เต้าหู้ทอด และลูกชิ้นปลาชิกุวะ"},"tagline":{"zh-TW":"冬夜屋台最溫暖的慰藉！掌握「煮而不沸」慢火浸透入味絕技。","en":"The ultimate winter comfort food. Master the gentle simmer and overnight steeping.","ja":"屋台の赤ちょうちんの下で湯気を上げる心温まる逸品。煮立てず静かに味を染み込ませます。","ko":"추운 겨울 포장마차의 따스한 위로! 끓이지 않고 은근하게 우리는 장인의 비법.","th":"เมนูคลายหนาวอันดับหนึ่ง ต้มด้วยไฟอ่อนเพื่อให้น้ำซุปซึมลึกถึงเนื้อใน"},"heroImage":"/images/jp/oden-hero.jpg","difficulty":"easy","prepTimeMinutes":30,"cookTimeMinutes":60,"defaultServings":4,"caloriesPerServing":240,"category":"nimono","dietaryTags":["classic","pescatarian"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"東京都・關東與關西 (Kanto/Kansai)","en":"Kanto & Kansai Regions","ja":"東京都・浅草および関西一円","ko":"도쿄 및 간사이 지방","th":"ภูมิภาคคันโตและคันไซ"},"famousYataiMarkets":[{"zh-TW":"福岡博多中洲屋台","en":"Nakasu Yatai, Fukuoka","ja":"福岡中洲屋台","ko":"후쿠오카 나카스 야타이","th":"ร้านยาไตนาคาสุ ฟุกุโอกะ"},{"zh-TW":"東京淺草雷門老街","en":"Asakusa Oden Houses, Tokyo","ja":"浅草おでん老舗街","ko":"아사쿠사 오뎅 골목","th":"ย่านโอเด้งอาซากุสะ โตเกียว"}],"historyStory":{"zh-TW":"關東煮起源於室町時代的烤豆腐串（田樂豆腐），到了江戶晚期，醬油釀造業興起，店家改將食材放入深鍋中以柴魚昆布高湯慢火久煮。日本關東偏好濃口醬油，關西則追求澄澈金黃的薄口淡高湯，是日本超商與街頭屋台最溫暖的冬日象徵。","en":"Originated from skewered grilled tofu (Dengaku) in the Muromachi period, evolving into a hotpot simmered in rich dashi. Japan’s supreme comfort broth.","ja":"室町時代の「田楽」が原型で、江戸時代後期に出汁で煮込むスタイルへ進化。黄金色の出汁を具材にじっくり吸わせるのが醍醐味です。","ko":"무로마치 시대의 두부 꼬치구이에서 유래하여 에도 시대에 육수에 끓여 먹는 형태로 발전한 서민 요리입니다.","th":"พัฒนาจากเต้าหู้เสียบไม้ย่างในอดีต จนกลายเป็นต้มในหม้อซุปดาชิกลมกล่อม"},"japaneseKanji":"おでん","japaneseKana":"おでん","japaneseRomaji":"Oden","audioPronunciationText":"おでん","nativeName":"おでん","nativePhonetics":"おでん"},"ingredients":[{"id":"daikon","name":{"zh-TW":"日本白蘿蔔 (Japanese Daikon Radish)","en":"Thickly sliced Japanese Daikon","ja":"大根（厚切り）","ko":"무 (두툼하게 썬 것)","th":"หัวไชเท้าหั่นท่อนหนา"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"japaneseKanji":"大根","japaneseKana":"だいこん","japaneseRomaji":"Daikon"},{"id":"eggs","name":{"zh-TW":"水煮蛋 (Hard-Boiled Eggs peeled)","en":"Hard-boiled eggs, peeled","ja":"ゆで卵","ko":"삶은 달걀","th":"ไข่ต้มปอกเปลือก"},"amount":4,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"ゆで卵","japaneseKana":"ゆでたまご","japaneseRomaji":"Yude Tamago"},{"id":"chikuwa","name":{"zh-TW":"烤竹輪 (Japanese Chikuwa Fish Cakes)","en":"Japanese Chikuwa (grilled fish cake tubes)","ja":"焼きちくわ","ko":"구운 치쿠와 어묵","th":"ชิกุวะ (ลูกชิ้นปลาหลอดเผา)"},"amount":3,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"ちくわ","japaneseKana":"ちくわ","japaneseRomaji":"Chikuwa"},{"id":"konnyaku","name":{"zh-TW":"魔芋蒟蒻塊 (Konjac Cake)","en":"Konjac (Konnyaku) Block, scored","ja":"こんにゃく","ko":"곤약","th":"บุกก้อน (คอนเนียคุ)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","japaneseKanji":"こんにゃく","japaneseKana":"こんにゃく","japaneseRomaji":"Konnyaku"},{"id":"atsuage","name":{"zh-TW":"厚揚油豆腐塊 (Atsuage Fried Tofu)","en":"Thick Fried Tofu (Atsuage)","ja":"厚揚げ（生揚げ）","ko":"두툼한 튀김 두부 (아츠아게)","th":"เต้าหู้ทอดชิ้นหนา"},"amount":180,"unitMetric":"g","unitUS":"6.3 oz","japaneseKanji":"厚揚げ","japaneseKana":"あつあげ","japaneseRomaji":"Atsuage"},{"id":"dashi-stock","name":{"zh-TW":"極上昆布柴魚黃金高湯 (Golden Dashi Stock)","en":"Kombu & Bonito Golden Dashi","ja":"昆布と鰹節の一番出汁","ko":"다시마와 가쓰오부시 황금 육수","th":"น้ำซุปดาชิปลาแห้งและสาหร่ายคอมบุ"},"amount":1000,"unitMetric":"ml","unitUS":"4.2 cups","isKeyFlavor":true,"japaneseKanji":"一番出汁","japaneseKana":"いちばんだし","japaneseRomaji":"Ichiban Dashi"},{"id":"usukuchi-shoyu","name":{"zh-TW":"薄口醬油 (Light Soy Sauce)","en":"Light-Colored Japanese Soy Sauce (Usukuchi)","ja":"薄口醤油","ko":"우스구치(연한) 간장","th":"โชยุสีอ่อนแบบอุสุกุจิ"},"amount":40,"unitMetric":"ml","unitUS":"2.7 tbsp","isKeyFlavor":true,"japaneseKanji":"薄口醤油","japaneseKana":"うすくちしょうゆ","japaneseRomaji":"Usukuchi Shōyu"},{"id":"mirin","name":{"zh-TW":"味醂 (Hon Mirin)","en":"Hon-Mirin","ja":"本みりん","ko":"미림","th":"มิริน"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","japaneseKanji":"本みりん","japaneseKana":"ほんみりん","japaneseRomaji":"Hon-Mirin"},{"id":"sake","name":{"zh-TW":"料理清酒 (Cooking Sake)","en":"Cooking Sake","ja":"清酒","ko":"청주","th":"สาเก"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","japaneseKanji":"料理酒","japaneseKana":"りょうりしゅ","japaneseRomaji":"Ryōrishu"},{"id":"karashi","name":{"zh-TW":"日式黃芥末醬 (Karashi Japanese Mustard)","en":"Japanese Spicy Yellow Mustard (Karashi)","ja":"練り辛子（からし）","ko":"일본식 연겨자","th":"มัสตาร์ดญี่ปุ่นรสเผ็ด (คาราชิ)"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","isKeyFlavor":true,"japaneseKanji":"練り辛子","japaneseKana":"ねりがらし","japaneseRomaji":"Karashi"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"蘿蔔修邊與劃十字 (Prep Daikon)","en":"Chamfer & Cross-Cut Daikon","ja":"大根の面取りと隠し包丁","ko":"무 모서리 깎고 십자 칼집 넣기","th":"เกลาขอบหัวไชเท้าและบั้งกากบาท"},"instruction":{"zh-TW":"白蘿蔔切成約 3 公分厚圓輪狀，厚厚削去外皮（約 2-3mm 削至纖維層內）。用小刀將上下邊緣削圓（面取り，防止久煮破皮），在單面切入深度約 1/3 的十字刀口（隱し包丁，幫助高湯快速透入核心）。","en":"Cut daikon into 3 cm thick rounds. Peel skin thickly. Chamfer the sharp edges to prevent crumbling. Score a cross \"X\" halfway into one side to speed broth absorption.","ja":"大根は厚さ3cmに切り、皮を厚めにむく。角を薄くそぎ落とす「面取り」をし、片面に深さ1cmほどの「隠し包丁」を十字に入れます。","ko":"무를 3cm 두께로 썰고 껍질을 두껍게 벗긴 뒤 모서리를 둥글게 깎아냅니다. 한쪽 면에 십자로 칼집을 넣습니다.","th":"หั่นหัวไชเท้าหนา 3 ซม. ปอกเปลือกหนา เกลาขอบมนป้องกันการแตก และบั้งกากบาทเพื่อให้ซึมน้ำซุป"},"durationSeconds":300,"image":"/images/jp/oden-step1.jpg","crucialTips":{"zh-TW":"「面取り（削角修邊）」是日本料亭的必備基本功，能讓蘿蔔煮上一整天依然形體圓潤完整！","en":"Beveling the edges (Mentori) prevents edges from knocking together and dissolving into broth.","ja":"【面取りの魔法】：面取りをすることで、煮込んでも角が崩れず出汁が濁りません。","ko":"모서리를 깎아주면 오래 끓여도 부서지지 않고 국물이 깔끔하게 유지됩니다.","th":"การเกลาขอบมนจะช่วยให้หัวไชเท้าไม่เละและน้ำซุปยังคงใสบริสุทธิ์"}},{"stepNumber":2,"title":{"zh-TW":"蘿蔔預煮去苦澀 (Pre-Boil Daikon)","en":"Pre-Boil Daikon in Rice Water","ja":"米のとぎ汁で大根を下茹で","ko":"쌀뜨물에 무 초벌 삶기","th":"ต้มหัวไชเท้าในน้ำซาวข้าว"},"instruction":{"zh-TW":"鍋中放入洗米水（或清水加一小把白米），放入切好的蘿蔔塊，大火煮滾轉小火燜煮 15-20 分鐘，直到竹籤能輕鬆穿透蘿蔔中心，撈出以冷水沖淨瀝乾。","en":"Submerge daikon in rice water (or water with 1 tbsp rice). Simmer for 15-20 mins until a skewer easily pierces the core. Rinse with cold water.","ja":"米のとぎ汁（または生米少々）で大根を20分ほど下茹で。竹串がスッと通るまで煮たら、水に取ってぬめりを洗います。","ko":"쌀뜨물에 무를 넣고 15~20분간 꼬치가 쑥 들어갈 때까지 삶은 뒤 찬물에 헹궈 전분기를 뺍니다.","th":"ต้มในน้ำซาวข้าว 15-20 นาทีจนไม้เสียบแทงทะลุได้ง่าย ล้างน้ำเย็นให้สะอาด"},"durationSeconds":1200,"image":"/images/jp/oden-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"油豆腐與魔芋去油除臭 (Parboil Tofu & Konjac)","en":"Scald Tofu & Konjac","ja":"厚揚げの油抜きとこんにゃくのアク抜き","ko":"튀김두부 기름 빼기와 곤약 데치기","th":"ลวกน้ำร้อนเอาน้ำมันและกลิ่นบุกออก"},"instruction":{"zh-TW":"魔芋切斜三角塊，表面劃出菱形花紋，沸水汆燙 2 分鐘去除鹼味；厚揚油豆腐以滾水淋洗或汆燙 1 分鐘去除表面多餘油脂（油抜き），煮出來的湯頭才金黃清爽不混濁。","en":"Cut konjac into triangles, crosshatch surface, boil 2 mins to remove odor. Scald fried tofu in boiling water for 1 min to wash off stale oil (aburanuki).","ja":"こんにゃくは格子状に切れ目を入れ下茹でしてアク抜き。厚揚げは熱湯を回しかけて余分な油を抜きます（油抜き）。","ko":"곤약은 칼집을 내어 데치고, 두부튀김은 뜨거운 물을 끼얹어 산화된 기름을 뺍니다.","th":"ลวกบุกในน้ำเดือด 2 นาที ลวกเต้าหู้ทอด 1 นาทีเพื่อเอาน้ำมันเก่าออก น้ำซุปจะได้ใสไม่เลี่ยน"},"durationSeconds":300,"image":"/images/jp/oden-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"調配高湯與慢火浸燉 (Gentle Simmer Broth)","en":"Combine Dashi & Gentle Simmer","ja":"出汁を合わせ沸騰させずに弱火で煮る","ko":"육수를 붓고 끓어넘치지 않게 은근히 조리기","th":"ใส่น้ำซุปและเคี่ยวด้วยไฟอ่อนไม่ให้เดือดพล่าน"},"instruction":{"zh-TW":"大燉鍋中注入昆布柴魚高湯，加入薄口醬油、味醂、清酒與 1/2 茶匙海鹽。先排入需要長時間燉煮的白蘿蔔、水煮蛋、蒟蒻，以極小火慢燉 40 分鐘（湯面僅冒微弱小氣泡，切勿大滾翻騰！）。","en":"In a large pot, combine dashi, light soy sauce, mirin, sake, and a pinch of salt. Add daikon, eggs, and konjac. Simmer on the lowest heat for 40 mins (gentle shiver, never rolling boil).","ja":"土鍋に出汁、薄口醤油、みりん、酒を合わせます。大根、卵、こんにゃくを入れ、煮立たせない極弱火で40分静かにコトコト煮ます。","ko":"냄비에 다시 육수, 우스구치 간장, 미림, 청주를 붓고 무, 달걀, 곤약을 넣어 약불에서 40분간 끓이지 않고 은근하게 졸입니다.","th":"ใส่น้ำซุปดาชิ โชยุสีอ่อน มิริน และสาเก ใส่หัวไชเท้า ไข่ต้ม และบุก เคี่ยวไฟอ่อนสุด 40 นาที ห้ามเดือดพล่าน"},"durationSeconds":2400,"image":"/images/jp/oden-step4.jpg","dangerWarnings":{"zh-TW":"大滾會破壞高湯的清澈度並讓柴魚香氣揮發，甚至導致魚漿製品泡發破裂！務必保持「煮而不沸」的微顫狀態。","en":"Violent boiling clouds the broth and destroys delicate aromatics. Keep the liquid at a gentle tremor.","ja":"グラグラ沸騰させると出汁が濁り、練り物がふやけて破裂します！火加減は常に微沸騰をキープ。","ko":"팔팔 끓이면 국물이 탁해지고 어묵이 퉁퉁 불어 맛이 없어집니다. 잔잔한 온도를 유지하세요.","th":"การต้มเดือดพล่านจะทำให้น้ำซุปขุ่นและลูกชิ้นปลาเละแตก ให้ใช้ไฟอ่อนเสมอ"}},{"stepNumber":5,"title":{"zh-TW":"加入魚漿竹輪與厚揚油豆腐 (Add Fishcakes)","en":"Add Chikuwa & Fried Tofu","ja":"練り物・厚揚げを加えさらに20分","ko":"어묵과 튀김두부 넣고 20분 더 졸이기","th":"ใส่ลูกชิ้นปลาและเต้าหู้ทอดต้มต่อ 20 นาที"},"instruction":{"zh-TW":"最後 20 分鐘排入切段的竹輪與厚揚油豆腐。讓魚漿的鮮甜自然融入湯頭，食材吸飽金黃高湯轉為膨潤入味。","en":"Add chikuwa and fried tofu for the final 20 minutes. Their seafood juices enrich the broth as they soak up the soup.","ja":"最後にちくわと厚揚げを加え、弱火でさらに20分煮て味をなじませます。","ko":"마지막에 치쿠와와 아츠아게를 넣고 약불에서 20분간 더 졸여 맛을 어우러지게 합니다.","th":"ใส่ชิกุวะและเต้าหู้ทอดลงไป ต้มไฟอ่อนต่ออีก 20 นาทีให้น้ำซุปซึมเข้าเนื้อ"},"durationSeconds":1200,"image":"/images/jp/oden-step5.jpg"},{"stepNumber":6,"title":{"zh-TW":"關火冷卻靜置入味 (Rest & Serve with Mustard)","en":"Cool Down to Steep & Serve","ja":"一度冷まして味を染み込ませてから再加熱","ko":"불 끄고 식혀 맛을 깊게 배게 한 뒤 겨자 곁들이기","th":"ปิดไฟพักให้ดูดซับน้ำซุป อุ่นร้อนและเสิร์ฟพร้อมคาราชิ"},"instruction":{"zh-TW":"煮好後關火，放涼靜置至少 1-2 小時（或隔夜，味道會提升一個檔次！因為食材是在降溫時吸收最多湯汁）。食用前重新加熱，盤緣沾上一抹辛辣濃香的日式黃芥末（からし），伴著清澈熱高湯一起享用！","en":"Turn off heat and let sit for 1-2 hours (flavors penetrate deepest while cooling). Reheat before serving. Dab spicy yellow Karashi mustard on the rim and sip the steaming golden elixir!","ja":"火を止め、一度冷まします（冷める時に味がグッと芯まで入ります）。食べる直前に温め直し、お皿の縁に練り辛子を添えて完成！","ko":"불을 끄고 1~2시간 식혀줍니다(식으면서 국물이 가장 깊게 뱁니다). 다시 데워 접시에 담고 알싸한 연겨자를 곁들입니다.","th":"ปิดไฟ พักไว้ 1-2 ชั่วโมงให้น้ำซุปซึมเข้าเนื้อ อุ่นร้อนก่อนเสิร์ฟพร้อมมัสตาร์ดญี่ปุ่นรสเผ็ด"},"durationSeconds":60,"image":"/images/jp/oden-step6.jpg"}],"troubleshooting":[{"id":"trouble-oden-1","problem":{"zh-TW":"為什麼白蘿蔔中心白白的，吃起來還是硬而帶生味？","en":"Why is the daikon center still hard and pale without flavor?","ja":"大根の中心に味が染みておらず、固さが残っています。","ko":"무 속까지 맛이 배지 않고 서걱거려요.","th":"ทำไมเนื้อหัวไชเท้าข้างในยังขาวแข็งและไม่ซึมรสชาติ?"},"cause":{"zh-TW":"省略了預先煮熟（下茹で）的步驟，或者煮好後沒有經歷「靜置降溫」的吸汁過程。","en":"Skipped the pre-boiling step, or ate immediately without resting.","ja":"下茹でを省略したか、作ってすぐ食べてしまい「冷ます工程」を経ていないためです。","ko":"초벌 삶기를 건너뛰었거나 만든 직후에 바로 먹어 식히는 과정을 거치지 않았기 때문입니다.","th":"ข้ามขั้นตอนต้มในน้ำซาวข้าว หรือทานทันทีโดยไม่ปล่อยให้เย็นเพื่อให้ดูดซับน้ำซุป"},"solution":{"zh-TW":"務必以洗米水預煮到筷子輕鬆穿透，並且在煮好後關火浸泡至少 1 小時再復熱食用。","en":"Always parboil daikon first until tender, and rest off heat for at least 1 hour before serving.","ja":"米のとぎ汁で箸が通るまで下茹でし、煮た後に一度完全に冷ましましょう。","ko":"반드시 쌀뜨물에 푹 삶은 뒤 조리하고, 불을 끄고 최소 1시간 식힌 후 다시 데워 드세요.","th":"ต้มหัวไชเท้าจนนิ่มก่อนนำมาแกง และปิดไฟแช่ทิ้งไว้อย่างน้อย 1 ชั่วโมงก่อนอุ่นทาน"}}],"proTips":[{"zh-TW":"【使用薄口醬油（Usukuchi）】：關東煮的靈魂是清澈金黃的色澤。請使用淡色薄口醬油，鹹度足夠且不會把湯底染得漆黑，完美展現高湯純粹的高級感！","en":"Use light soy sauce (Usukuchi) to maintain a shimmering golden broth without turning it muddy black.","ja":"【薄口醤油で黄金色をキープ】：濃口ではなく薄口醤油を使うことで、お出汁の美しさをそのまま活かせます。","ko":"진간장 대신 우스구치(국간장/연한 간장)를 써야 국물이 까맣게 변하지 않고 맑은 황금빛을 유지합니다.","th":"ใช้โชยุสีอ่อนเพื่อรักษาน้ำซุปสีทองประกายสวยงาม ไม่ดำคล้ำ"}]},{"country":"jp","id":"taiyaki","slug":"japanese-taiyaki","title":{"zh-TW":"經典酥脆十勝紅豆鯛魚燒","en":"Crispy Japanese Red Bean Taiyaki","ja":"天然モノのサクサク鯛焼き（十勝産粒あん）","ko":"바삭바삭 정통 팥 붕어빵 (타이야키)","th":"ไทยากิ ขนมปลาไส้ถั่วแดงฮอกไกโดกรอบนอกนุ่มใน"},"subtitle":{"zh-TW":"外皮薄脆酥香、從頭到尾鰭爆漿飽滿的十勝紅豆餡","en":"Crispy wafer-thin waffle exterior bursting with sweet Hokkaido azuki from head to tail","ja":"頭から尻尾までアンコがぎっしり！外は香ばしくサクサク、中はふっくらの縁起物","ko":"머리부터 꼬리까지 통단팥이 꽉 찬 바삭하고 고소한 일본 전통 타이야키","th":"แป้งบางกรอบ ไส้ถั่วแดงกวนหวานฉ่ำอัดแน่นตั้งแต่หัวจรดหาง"},"tagline":{"zh-TW":"日本祭典屋台吉祥甜點，在家用鯛魚燒機或三明治機輕鬆出爐！","en":"The iconic Japanese festival fish waffle, easily made with home waffle makers.","ja":"お祭りの屋台でも大人気！家庭のたい焼き器やワッフルメーカーで焼き立てを。","ko":"일본 축제 최고의 인기 길거리 간식! 와플 팬이나 붕어빵 팬으로 갓 구워내기.","th":"ขนมมงคลยอดนิยมในงานเทศกาลญี่ปุ่น ทำเองได้ง่ายๆ ด้วยเครื่องทำวาฟเฟิล"},"heroImage":"/images/jp/taiyaki-hero.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":8,"defaultServings":4,"caloriesPerServing":210,"category":"sweets","dietaryTags":["classic","vegetarian"],"supportedCookware":["traditional","takoyakiPlate","airFryer","oven"],"culture":{"originRegion":{"zh-TW":"東京都麻布十番 (Tokyo)","en":"Azabu-Juban, Tokyo","ja":"東京都港区麻布十番","ko":"도쿄 아자부주반","th":"อาซาบุจูบัง โตเกียว"},"famousYataiMarkets":[{"zh-TW":"東京麻布十番浪花家總本店","en":"Naniwaya Sohonten, Tokyo","ja":"麻布十番 浪花家総本店","ko":"아자부주반 나니와야 총본점","th":"ร้านดั้งเดิมนานิวะยะ อาซาบุจูบัง"},{"zh-TW":"淺草寺仲見世祭典屋台","en":"Asakusa Festival Stalls, Tokyo","ja":"浅草寺縁日屋台","ko":"아사쿠사 축제 야타이","th":"แผงลอยเทศกาลวัดอาซากุสะ"}],"historyStory":{"zh-TW":"鯛魚燒誕生於明治 42 年（1909 年），由麻布十番「浪花家總本店」創始人神戶清次郎發明。當時平民吃不起象徵喜慶的昂貴高檔真鯛魚，便將今川燒麵糊灌入吉祥的鯛魚模具中烘烤，深受江戶庶民喜愛，傳唱全日本！","en":"Invented in 1909 at Naniwaya Sohonten in Tokyo. Red sea bream (Tai) was an expensive luxury reserved for celebrations; casting sweet red bean waffles in its shape brought good fortune to the masses.","ja":"明治42年（1909年）、麻布十番「浪花家総本店」の初代が考案。「めでたい」高級魚の鯛を型にしたことで庶民の間で爆発的な人気となりました。","ko":"1909년 고급 어종인 도미를 맛보기 힘든 서민들을 위해 도미 모양으로 구워 팔기 시작한 것이 시초입니다.","th":"คิดค้นขึ้นในปี 1909 โดยใช้รูปปลาไท (ปลากะพงแดงมงคล) เพื่อให้คนทั่วไปได้ลิ้มรสความสุขในราคาประหยัด"},"japaneseKanji":"たい焼き","japaneseKana":"たいやき","japaneseRomaji":"Taiyaki","audioPronunciationText":"たい焼き","nativeName":"たい焼き","nativePhonetics":"たいやき"},"ingredients":[{"id":"anko","name":{"zh-TW":"日本十勝蜜紅豆餡 (Sweet Azuki Red Bean Paste)","en":"Japanese Sweet Red Bean Paste (Tsubuan)","ja":"粒あん（十勝産あずき）","ko":"통단팥 앙금","th":"ถั่วแดงกวนญี่ปุ่น"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"japaneseKanji":"粒あん","japaneseKana":"つぶあん","japaneseRomaji":"Tsubuan"},{"id":"flour","name":{"zh-TW":"低筋麵粉 (Cake Flour)","en":"Cake Flour","ja":"薄力粉","ko":"박력분","th":"แป้งเค้ก"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","japaneseKanji":"薄力粉","japaneseKana":"はくりきこ","japaneseRomaji":"Hakurikiko"},{"id":"baking-powder","name":{"zh-TW":"無鋁泡打粉與小蘇打 (Baking Powder & Soda)","en":"Baking Powder (1 tsp) & Baking Soda (1/4 tsp)","ja":"ベーキングパウダー＆重曹","ko":"베이킹파우더 & 베이킹소다","th":"ผงฟูและเบกกิ้งโซดา"},"amount":5,"unitMetric":"g","unitUS":"1 tsp","japaneseKanji":"膨張剤","japaneseKana":"べーきんぐぱうだー","japaneseRomaji":"Bēkingu Paudā"},{"id":"egg","name":{"zh-TW":"全蛋 (Large Egg)","en":"Large Egg","ja":"卵","ko":"달걀","th":"ไข่ไก่"},"amount":1,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"卵","japaneseKana":"たまご","japaneseRomaji":"Tamago"},{"id":"milk","name":{"zh-TW":"鮮乳或水 (Fresh Milk or Water)","en":"Milk or Cold Water","ja":"牛乳または水","ko":"우유 또는 물","th":"นมสดหรือน้ำเปล่า"},"amount":140,"unitMetric":"ml","unitUS":"0.6 cup","japaneseKanji":"牛乳","japaneseKana":"ぎゅうにゅう","japaneseRomaji":"Gyūnyū"},{"id":"honey","name":{"zh-TW":"天然純蜂蜜 (Natural Honey)","en":"Honey (creates golden hue & sheen)","ja":"蜂蜜","ko":"꿀","th":"น้ำผึ้งแท้"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","isKeyFlavor":true,"japaneseKanji":"蜂蜜","japaneseKana":"はちみつ","japaneseRomaji":"Hachimitsu"},{"id":"sugar","name":{"zh-TW":"細砂糖 (Caster Sugar)","en":"Sugar","ja":"上白糖","ko":"설탕","th":"น้ำตาลทราย"},"amount":25,"unitMetric":"g","unitUS":"2 tbsp","japaneseKanji":"砂糖","japaneseKana":"さとう","japaneseRomaji":"Satō"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調製香甜鯛魚麵糊 (Whisk Batter)","en":"Whisk Honey Waffle Batter","ja":"卵、蜂蜜、牛乳を混ぜ粉類を合わせる","ko":"달걀, 꿀, 우유와 가루류 섞기","th":"ตีไข่ น้ำผึ้ง นม และแป้งให้เข้ากัน"},"instruction":{"zh-TW":"碗中打散雞蛋、加入細砂糖、蜂蜜與鮮奶攪打勻化。篩入低筋麵粉、泡打粉與小蘇打，用打蛋器輕柔攪拌至滑順無粉粒，靜置冷藏鬆弛 20 分鐘。","en":"Whisk egg, sugar, honey, and milk together. Sift in flour, baking powder, and baking soda. Whisk gently until smooth. Rest in the fridge for 20 mins.","ja":"ボウルに卵、砂糖、蜂蜜、牛乳を入れてよく混ぜ、粉類をふるい入れます。ダマがなくなるまでサッと混ぜ、冷蔵庫で20分休ませます。","ko":"볼에 달걀, 설탕, 꿀, 우유를 풀고 가루류를 체 쳐 넣어 부드럽게 섞은 뒤 냉장고에서 20분간 휴지합니다.","th":"ตีไข่ น้ำตาล น้ำผึ้ง และนม ร่อนแป้งและผงฟูลงไป คนจนเนียน แช่เย็นพักไว้ 20 นาที"},"durationSeconds":180,"image":"/images/jp/taiyaki-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"預熱模具與薄抹油脂 (Preheat & Grease Mold)","en":"Preheat Taiyaki Pan","ja":"焼き型を温めて油を薄く塗る","ko":"틀 예열하고 얇게 기름칠하기","th":"วอร์มเตาและทาน้ำมันบางๆ"},"instruction":{"zh-TW":"鯛魚燒烤模（直火模或電烤機）以中小火雙面均勻預熱，在魚身與魚尾紋理細部薄薄刷上一層植物油或融化奶油。","en":"Preheat taiyaki maker or stovetop mold on medium-low. Lightly brush all fish contours and tails with melted butter or oil.","ja":"たい焼き器の両面を弱火で予熱し、溝の隅々までサラダ油を薄く塗ります。","ko":"틀을 약불로 예열하고 지느러미와 꼬리 구석구석까지 식용유를 얇게 바릅니다.","th":"วอร์มเตาไฟอ่อน ทาน้ำมันบางๆ ตามรอยเกล็ดและหางปลาให้ทั่ว"},"durationSeconds":90,"image":"/images/jp/taiyaki-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"注漿入餡與覆蓋密封 (Pour Batter & Seal)","en":"Pour, Fill with Azuki & Seal","ja":"生地を流しあんこを乗せて覆う","ko":"반죽 붓고 단팥 넣은 뒤 반죽 덮기","th":"เทแป้งครึ่งหนึ่ง ใส่ไส้ถั่วแดง แล้วเทแป้งปิดทับ"},"instruction":{"zh-TW":"倒入麵糊至魚模約 6 分滿（魚尾也要倒一點）。在魚身中央放入厚厚一條長條狀紅豆餡（約 45g，刻意延展至尾巴），再淋上一層薄薄麵糊蓋住紅豆餡。","en":"Pour batter to fill 60% of the mold including the tail. Lay a thick log of red bean paste (~45g) down the center, then drizzle extra batter over the top to seal.","ja":"型の6分目まで生地を流し、あんこを細長く成形して乗せます（尻尾まで届くように）。上から生地を薄く流してアンコを隠します。","ko":"틀의 60%까지 반죽을 붓고 팥앙금을 길게 얹은 뒤(꼬리까지), 위에 반죽을 살짝 덧부어 팥을 덮어줍니다.","th":"เทแป้งลงไป 60% ของพิมพ์ วางไส้ถั่วแดงเป็นแนวยาวจรดหาง แล้วหยอดแป้งปิดทับบางๆ"},"durationSeconds":90,"image":"/images/jp/taiyaki-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"扣合翻面慢火烘烤 (Flip & Bake Crispy)","en":"Flip & Crisp Both Sides","ja":"型を閉じて素早く裏返し両面を焼く","ko":"틀을 닫고 뒤집어가며 노릇하게 굽기","th":"ประกบเตา พลิกกลับด้านย่างจนเหลืองกรอบ"},"instruction":{"zh-TW":"蓋上模具鎖緊，立刻將烤模翻轉 180 度（讓生麵糊流動填滿另一面魚紋細節）。小火每隔 1 分鐘翻面一次，總共烘烤約 4-5 分鐘，直到蒸氣變少、表面呈現誘人深金黃色！","en":"Clamp the mold shut and immediately flip 180° so batter flows into the top scales. Flip every minute over low heat for 4-5 mins until deep golden.","ja":"フタを閉めてすぐに裏返し（反対側の模様に生地を行き渡らせる）、弱火で1分ごとに返しながら合計4〜5分香ばしく焼き上げます。","ko":"틀을 닫고 즉시 180도 뒤집은 뒤 약불에서 1분마다 뒤집어가며 총 4~5분간 노릇하게 굽습니다.","th":"ปิดฝาล็อกแล้วพลิกเตาทันที 180 องศา ย่างไฟอ่อนพลิกไปมาทุก 1 นาที รวม 4-5 นาทีจนสีเหลืองทอง"},"durationSeconds":300,"image":"/images/jp/taiyaki-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"立架透氣保持薄脆 (Cool on Rack)","en":"Cool on Rack for Maximum Crunch","ja":"網に立てて粗熱を取りサクサクを保つ","ko":"식힘망에 세워 식혀 바삭함 유지하기","th":"วางผึ่งบนตะแกรงเพื่อรักษาความกรอบ"},"instruction":{"zh-TW":"開模將烤得金黃香酥的鯛魚燒取出，豎立在散熱鐵架上散熱 1 分鐘，排出底部水氣。外殼酥脆咔滋、內餡滾燙軟糯的天然鯛魚燒完成！","en":"Transfer to a wire rack standing upright for 1 min to vent moisture. Enjoy the shatteringly crisp exterior and hot molten sweet center!","ja":"焼き上がったら金網の上に立てて置き、1分蒸気を逃がします。皮がパリッと、中はアツアツの極上たい焼きの完成！","ko":"꺼내어 식힘망에 세워 1분간 김을 빼면 바닥이 눅눅해지지 않고 파삭파삭함이 유지됩니다.","th":"ตักขึ้นวางตั้งบนตะแกรง 1 นาทีให้ไอน้ำระบายออก ผิวด้านนอกจะกรอบกริ๊บ ไส้ในหวานฉ่ำฟินสุดๆ"},"durationSeconds":60,"image":"/images/jp/taiyaki-step5.jpg"}],"troubleshooting":[{"id":"trouble-tai-1","problem":{"zh-TW":"為什麼鯛魚眼睛或魚尾花紋缺角不完整？","en":"Why are the tail or eye details missing on the crust?","ja":"尻尾や目の細かい模様に生地が行き渡らず欠けてしまいます。","ko":"지느러미나 눈 모양이 제대로 찍히지 않고 비어 있어요.","th":"ทำไมลายหางปลาหรือเกล็ดปลาแหว่งไม่เต็มพิมพ์?"},"cause":{"zh-TW":"扣上模具後翻轉太慢，或者倒入的麵糊量太少。","en":"Flipped too late after closing, or poured insufficient batter to fill crevices.","ja":"フタを閉めた後のひっくり返しが遅く、生地が流れる前に固まってしまったため。","ko":"틀을 닫은 뒤 너무 늦게 뒤집어서 반죽이 미처 흘러가지 못했기 때문입니다.","th":"ปิดฝาแล้วพลิกช้าเกินไป ทำให้แป้งสุกตัวก่อนจะไหลไปตามซอกพิมพ์"},"solution":{"zh-TW":"倒完麵糊合起模具後，「1 秒內立刻翻轉 180 度」，利用重力讓流動的麵糊完美填滿魚紋！","en":"Invert the pan within 1 second of closing so liquid batter cascades into the top scales.","ja":"フタを閉じたら迷わず「1秒以内」に素早く180度反転させましょう！","ko":"틀을 닫자마자 1초 만에 단숨에 뒤집어주면 모든 문양이 완벽하게 찍힙니다.","th":"ปิดฝาแล้วให้พลิกกลับด้านใน 1 วินาทีทันที แป้งจะไหลเต็มทุกลายอย่างสวยงาม"}}],"proTips":[{"zh-TW":"【加微量小蘇打的妙用】：食譜中加入 1/4 茶匙小蘇打（重曹），能在烘烤時與蜂蜜產生美拉德反應，烤出金黃誘人的焦香脆皮！","en":"A pinch of baking soda reacts with honey to produce a deep mahogany color and crisp waffle aroma.","ja":"【重曹で香ばしさと色ツヤ】：少量の重曹を入れることで、昔懐かしい屋台の香ばしい焼き色と香りが生まれます。","ko":"베이킹소다를 아주 약간 넣으면 꿀과 반응하여 먹음직스러운 갈색 구움색과 특유의 구수한 향을 냅니다.","th":"การใส่เบกกิ้งโซดาเพียงเล็กน้อย จะทำปฏิกิริยากับน้ำผึ้งให้สีน้ำตาลทองกรอบและกลิ่นหอมชวนทาน"}]},{"country":"jp","id":"yakisoba-street","slug":"japanese-street-yakisoba","title":{"zh-TW":"日式夏祭屋台炒麵","en":"Japanese Festival Street Yakisoba","ja":"縁日屋台の極上 焼きそば","ko":"일본 축제 포장마차 야키소바","th":"ยากิโซบะ ผัดซอสสูตรงานเทศกาลญี่ปุ่น"},"subtitle":{"zh-TW":"大鐵板鑊氣噴香、濃郁伍斯特蔬果醬汁、紅生薑酸爽開胃","en":"Sizzling noodles wok-tossed with pork belly, cabbage, Worcestershire sauce & pickled ginger","ja":"鉄板の香ばしいソースの焦げた香り！豚バラとシャキシャキキャベツの王道屋台味","ko":"뜨거운 철판에서 볶아낸 불맛 가득한 면발과 아삭한 양배추, 단짠 소스의 조화","th":"เส้นเหนียวนุ่มผัดบนกระทะร้อน คลุกเคล้าซอสผลไม้รสเข้มข้น หมูสามชั้น และขิงดองสีแดง"},"tagline":{"zh-TW":"日本祭典大排長龍的鐵板霸主！掌握高溫乾炒與醬汁焦化的美味極意。","en":"The undisputed champion of Japanese festival stalls, easily replicated in a hot skillet.","ja":"夏祭りの主役！麺をしっかり焼き付けてからほぐすのがプロの技。","ko":"마츠리의 꽃! 면을 먼저 바삭하게 구운 뒤 볶아내는 전문가의 비법.","th":"เมนูยอดฮิตในงานวัดญี่ปุ่น เคล็ดลับคั่วเส้นให้หอมกระทะก่อนคลุกซอส"},"heroImage":"/images/jp/yakisoba-hero.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":450,"category":"konamono","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"淺草・夏日祭典屋台 (Tokyo Asakusa)","en":"Tokyo & Festival Markets across Japan","ja":"全国の縁日・夏祭り屋台","ko":"일본 전역의 여름 축제 야타이","th":"งานเทศกาลฤดูร้อนทั่วประเทศญี่ปุ่น"},"famousYataiMarkets":[{"zh-TW":"東京淺草寺三社祭屋台","en":"Asakusa Sanja Matsuri Stalls, Tokyo","ja":"浅草三社祭 屋台街","ko":"아사쿠사 산자 마츠리 야타이","th":"งานเทศกาลซันจา อาซากุสะ"}],"historyStory":{"zh-TW":"日式炒麵起源於昭和初期，從中式炒麵結合日本引進的伍斯特辣醬油（Worcestershire sauce）改良而成。戰後因捲心菜便宜耐放，在街頭鐵板大火翻炒，酸甜濃郁的香氣飄散數百公尺，成為祭典最具代表性的風景！","en":"Evolving in the early Showa period by seasoning Chinese stir-fried noodles with Japanese Worcestershire fruit sauce. An iconic fixture at every summer festival.","ja":"昭和初期に中華そばにウスターソースを合わせたのが始まり。ソースが焼ける魅惑的な匂いは、日本の祭りの原風景です。","ko":"쇼와 초기에 중화면에 우스터소스를 접목하여 탄생한 대중 요리로 축제 포장마차의 상징이 되었습니다.","th":"เกิดขึ้นในยุคโชวะ โดยนำเส้นบะหมี่มาผัดกับซอสวูสเตอร์สไตล์ญี่ปุ่น กลิ่นหอมฟุ้งไปทั่วงานเทศกาล"},"japaneseKanji":"焼きそば","japaneseKana":"やきそば","japaneseRomaji":"Yakisoba","audioPronunciationText":"焼きそば","nativeName":"焼きそば","nativePhonetics":"やきそば"},"ingredients":[{"id":"yakisoba-noodles","name":{"zh-TW":"日式蒸煮炒麵麵條 (Steamed Chuka Yakisoba Noodles)","en":"Pre-steamed Yakisoba Noodles","ja":"焼きそば用蒸し中華麺","ko":"야키소바용 찐 중화면","th":"เส้นยากิโซบะกึ่งสำเร็จรูป"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":true,"japaneseKanji":"蒸し中華麺","japaneseKana":"むしちゅうかめん","japaneseRomaji":"Mushi Chūkamen"},{"id":"pork-belly","name":{"zh-TW":"五花肉薄片 (Pork Belly Slices cut bite-sized)","en":"Pork belly slices, cut into 3cm pieces","ja":"豚バラ薄切り肉","ko":"돼지 삼겹살 한입 크기","th":"หมูสามชั้นสไลซ์หั่นพอดีคำ"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","japaneseKanji":"豚バラ肉","japaneseKana":"ぶたばらにく","japaneseRomaji":"Butabara Niku"},{"id":"cabbage","name":{"zh-TW":"高麗菜切塊 (Roughly chopped cabbage)","en":"Green cabbage, chopped into squares","ja":"キャベツ（一口大のざく切り）","ko":"양배추 깍둑썰기","th":"กะหล่ำปลีหั่นชิ้นสี่เหลี่ยม"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","japaneseKanji":"キャベツ","japaneseKana":"きゃべつ","japaneseRomaji":"Kyabetsu"},{"id":"bean-sprouts","name":{"zh-TW":"綠豆芽 (Bean Sprouts)","en":"Fresh bean sprouts","ja":"もやし","ko":"숙주나물","th":"ถั่วงอกสด"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","japaneseKanji":"もやし","japaneseKana":"もやし","japaneseRomaji":"Moyashi"},{"id":"yakisoba-sauce","name":{"zh-TW":"日式炒麵醬汁 (Yakisoba Sauce)","en":"Yakisoba Sauce (or Worcestershire + Oyster Sauce)","ja":"焼きそばソース","ko":"야키소바 전용 소스","th":"ซอสยากิโซบะเข้มข้น"},"amount":50,"unitMetric":"ml","unitUS":"3.5 tbsp","isKeyFlavor":true,"japaneseKanji":"焼きそばソース","japaneseKana":"やきそばそーす","japaneseRomaji":"Yakisoba Sōsu"},{"id":"benishoga","name":{"zh-TW":"紅生薑 (Beni Shoga)","en":"Red pickled ginger (Beni Shoga)","ja":"紅生姜","ko":"초생강 (베니쇼가)","th":"ขิงดองเส้นสีแดง"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","japaneseKanji":"紅生姜","japaneseKana":"べにしょうが","japaneseRomaji":"Beni Shōga"},{"id":"aonori-katsuobushi","name":{"zh-TW":"青海苔粉與柴魚片 (Aonori & Bonito Flakes)","en":"Aonori green seaweed & bonito flakes","ja":"青のり・花かつお","ko":"파래가루와 가쓰오부시","th":"ผงสาหร่ายสีเขียวและปลาแห้งขูด"},"amount":5,"unitMetric":"g","unitUS":"1 tsp","japaneseKanji":"青のり・鰹節","japaneseKana":"あおのり・かつおぶし","japaneseRomaji":"Aonori / Katsuobushi"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"麵條微波微溫與煎出脆痕 (Sear the Noodles)","en":"Crisp the Noodles First","ja":"麺をレンジで温め、ほぐさず両面を焼く","ko":"면을 먼저 굽듯 볶아 불맛 입히기","th":"นำเส้นลงย่างให้เกรียมหอมก่อนผัด"},"instruction":{"zh-TW":"蒸煮炒麵麵條事先微波 30 秒使油脂鬆化。大鐵鍋倒少許油，將整團麵條平鋪鍋底，先不要急著炒散！中大火乾煎 2 分鐘，翻面再煎 1 分鐘，煎出金黃微焦脆痕，盛起備用（屋台炒麵乾爽彈牙的秘訣！）。","en":"Microwave noodles for 30s to loosen. Heat skillet with oil; lay noodles flat without breaking them. Sear for 2 mins until golden and crusty, flip for 1 min, then transfer to a plate.","ja":"麺をレンジで30秒加熱。油を引いたフライパンに広げ、触らずに2分焼き、裏返して1分。表面にカリッとした焼き色をつけて一度取り出します。","ko":"면을 전자레인지에 30초 돌려 부드럽게 한 뒤, 팬에 넓게 펴서 건드리지 않고 앞뒤로 2분씩 노릇하게 구워 따로 덜어둡니다.","th":"อุ่นเส้น 30 วินาที วางบนกระทะให้เกรียมด้านละ 1-2 นาทีโดยไม่คน เพื่อสร้างความกรอบหอมกระทะ"},"durationSeconds":240,"image":"/images/jp/yakisoba-step1.jpg","crucialTips":{"zh-TW":"千萬不要加水把麵條煮爛！事先把麵條表面「煎香煎脆」，後續裹上醬汁才不會軟爛糊成一團。","en":"Never add water to steam noodles into mush! Searing them first locks in elasticity so they drink up sauce without getting soggy.","ja":"【水を入れて蒸さない】：水を入れず、油で焼き付けることで屋台のような香ばしさと弾力が生まれます。","ko":"물을 부어 찌면 눅눅해집니다! 기름에 바삭하게 구워내야 소스를 넣어도 쫄깃합니다.","th":"อย่าเติมน้ำลงไปต้ม ให้ใช้วิธีคั่วบนกระทะเพื่อให้เส้นเหนียวนุ่มดูดซอสได้ดี"}},{"stepNumber":2,"title":{"zh-TW":"煸香五花肉與脆炒蔬菜 (Stir-Fry Meat & Veggies)","en":"Sear Pork & Vegetables","ja":"豚肉をカリッと炒め、野菜を加える","ko":"돼지고기와 채소 센 불에 볶기","th":"ผัดหมูสามชั้นและผักด้วยไฟแรง"},"instruction":{"zh-TW":"原鍋不用洗，大火下五花肉片煸炒至豬油釋出、表面微金黃。加入高麗菜塊與綠豆芽，大火快速翻炒 1 分鐘至蔬菜斷生但依然脆甜。","en":"In the same pan, fry pork belly until crisp and fat renders. Toss in cabbage and bean sprouts, flash-frying on high for 1 min until tender-crisp.","ja":"同じフライパンで豚肉を炒め、脂が出たらキャベツともやしを投入。強火で一気に炒め合わせます。","ko":"같은 팬에 삼겹살을 볶아 기름을 낸 뒤 양배추와 숙주를 넣고 센 불에서 아삭하게 1분간 볶습니다.","th":"ผัดหมูสามชั้นจนน้ำมันออก ใส่กะหล่ำปลีและถั่วงอก ผัดไฟแรง 1 นาทีให้ผักยังคงความกรอบ"},"durationSeconds":120,"image":"/images/jp/yakisoba-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"合鍋翻炒與鍋邊淋醬 (Combine & Sizzle Sauce)","en":"Combine & Sizzle Sauce on Pan Edges","ja":"麺を戻し、鍋肌からソースを回し入れ絡める","ko":"면을 합치고 가장자리에 소스 둘러 볶기","th":"ใส่เส้นกลับลงไป ราดซอสรอบขอบกระทะคลุกเคล้า"},"instruction":{"zh-TW":"將煎香的麵條倒回鍋中與肉菜混合。將日式炒麵醬汁沿著滾燙的「鍋邊淋入」（利用高溫鐵壁讓醬汁瞬間焦糖化噴發鑊氣！），以雙鏟高速翻拌均勻，讓每根麵條都裹上油亮深棕醬色。","en":"Return noodles to the pan. Drizzle yakisoba sauce around the screaming hot edges of the pan so it sizzles and caramelizes instantly. Toss vigorously with two spatulas.","ja":"麺を戻し、ソースを鍋肌からジャッと回し入れます。焦がしソースの香りを麺全体に手早く絡め合わせます。","ko":"구워둔 면을 넣고 소스를 팬 가장자리에 둘러 지글지글 불맛을 입히며 빠르게 섞어줍니다.","th":"ใส่เส้นลงไป ราดซอสลงบนขอบกระทะร้อนๆ เพื่อสร้างกลิ่นหอมไหม้กระทะ แล้วคลุกเคล้าอย่างรวดเร็ว"},"durationSeconds":90,"image":"/images/jp/yakisoba-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"盛盤點綴紅生薑 (Plate with Toppings)","en":"Plate with Aonori & Beni Shoga","ja":"器に盛り青のり・紅生姜を添える","ko":"접시에 담고 파래가루, 가쓰오부시, 초생강 얹기","th":"ตักใส่จาน โรยสาหร่าย ปลาแห้ง และขิงดอง"},"instruction":{"zh-TW":"裝盤堆成小山，灑上翠綠青海苔粉與柴魚片，旁邊夾上一大坨鮮紅脆爽的日式紅生薑（紅生薑的微酸解膩是炒麵的絕配！），趁熱大快朵頤！","en":"Mound onto a plate, dust with aonori, crown with dancing bonito flakes, and nestle a bright heap of pickled beni shoga ginger alongside. Enjoy festival vibes at home!","ja":"お皿に盛り、青のりと鰹節を振り、紅生姜をたっぷり添えて熱々のうちにいただきます！","ko":"접시에 높게 담고 파래가루와 가쓰오부시를 얹은 뒤 개운한 초생강을 곁들여 완성합니다.","th":"ตักใส่จาน โรยผงสาหร่ายและปลาโอแห้งขูด แนบด้วยขิงดองสีแดงสด ทานร้อนๆ ได้บรรยากาศงานเทศกาล"},"durationSeconds":30,"image":"/images/jp/yakisoba-step4.jpg"}],"troubleshooting":[{"id":"trouble-yaki-noodle","problem":{"zh-TW":"為什麼炒出來整盤濕黏軟爛，像在吃燴麵？","en":"Why is the yakisoba soggy and wet instead of springy?","ja":"麺が柔らかくベチャベチャになってしまいます。","ko":"면이 눅눅하고 질척거려요.","th":"ทำไมผัดออกมาแล้วแฉะเละ ไม่แห้งเหนียวนุ่ม?"},"cause":{"zh-TW":"加了水去燜麵，或是蔬菜翻炒時間太長出水過多。","en":"Added water to steam, or cooked vegetables too long causing them to release water.","ja":"水を加えてほぐしたか、野菜を炒めすぎて水分が出てしまったため。","ko":"면을 풀기 위해 물을 부었거나 채소를 너무 오래 볶아 물이 흥건해졌기 때문입니다.","th":"เติมน้ำลงไป หรือผัดผักนานเกินไปจนคายน้ำ"},"solution":{"zh-TW":"微波麵條去除冷藏硬度即可，全程保持大火，菜斷生立刻下麵淋醬翻炒出鍋。","en":"Microwave cold noodles to soften instead of water, use roaring high heat throughout.","ja":"レンジで温めてから乾煎りし、強火で一気に仕上げましょう。","ko":"물 대신 전자레인지로 면을 데우고, 센 불에서 빠르게 볶아내세요.","th":"ใช้ไมโครเวฟช่วยคลายเส้นแทนการใช้น้ำ และผัดด้วยไฟแรงสม่ำเสมอ"}}],"proTips":[{"zh-TW":"【鍋邊淋醬鑊氣倍增】：醬汁千萬不要直接倒在麵條正中央，沿著燒紅的鐵鍋邊緣淋下，醬油與果醋瞬間焦化沸騰，才能激發街頭屋台那股無可抗拒的焦糖香氣！","en":"Pour sauce around the sizzling perimeter of the pan, not directly onto cold noodles. Flash caramelization creates authentic street food wok hei.","ja":"【ソースは鍋肌から】：フライパンのフチから回し入れ、一瞬で焦がすことで縁日屋台のプロの香ばしさを再現できます。","ko":"소스를 면 위에 붓지 말고 달궈진 팬 가장자리에 둘러 태우듯 끓여야 정통 포장마차의 불맛이 살아납니다.","th":"ราดซอสลงบนขอบกระทะร้อนๆ เพื่อให้ซอสไหม้หอมคาราเมลก่อนคลุกเส้น"}]},{"country":"jp","id":"kushikatsu","slug":"osaka-shinsekai-kushikatsu","title":{"zh-TW":"大阪新世界極上串炸","en":"Osaka Shinsekai Kushikatsu","ja":"大阪新世界 元祖串カツ（秘伝二度づけ禁止ソース）","ko":"오사카 신세카이 명물 쿠시카츠 (꼬치튀김)","th":"คุชิคัตสึ ของทอดเสียบไม้สไตล์โอซาก้า"},"subtitle":{"zh-TW":"超細麵包粉金黃酥脆薄衣、嚴禁沾二次醬的濃郁黑醋醬汁","en":"Ultra-fine panko crust, assorted skewers with the iconic \"no double dipping\" dip sauce","ja":"きめ細かな極細パン粉でサクッと軽い！ソースの二度づけ禁止でいただく下町名物","ko":"초미세 빵가루로 얇고 바삭하게 튀겨낸 신세카이 명물, 소스는 두 번 찍기 금지!","th":"เกล็ดขนมปังละเอียดพิเศษกรอบเบา จุ่มซอสเข้มข้น ห้ามจิ้มซอสซ้ำเด็ดขาด"},"tagline":{"zh-TW":"通天閣下最具人情味的平民美食！高溫快速炸出爽脆不油膩的黃金炸物。","en":"Crispy skewered delights from beneath the Tsutenkaku tower, air fryer and stove friendly.","ja":"通天閣の下で愛され続ける庶民の味。ノンフライヤーでもヘルシーに再現。","ko":"츠텐카쿠 타워 아래의 명물! 기름지지 않고 파삭하게 즐기는 일본식 꼬치튀김.","th":"อาหารยอดฮิตใต้หอคอยซึเทนคาคุ กรอบเบาไม่อมน้ำมัน ทำด้วยหม้อทอดไร้น้ำมันได้"},"heroImage":"/images/jp/kushikatsu-hero.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":380,"category":"agemono","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"大阪府浪速區・新世界 (Shinsekai, Osaka)","en":"Shinsekai, Osaka","ja":"大阪市浪速区新世界（通天閣界隈）","ko":"오사카 신세카이 (츠텐카쿠 주변)","th":"ย่านชินเซไก โอซาก้า"},"famousYataiMarkets":[{"zh-TW":"大阪新世界通天閣串炸一文字街","en":"Shinsekai Kushikatsu Street, Osaka","ja":"新世界串カツ街（だるま総本店など）","ko":"신세카이 쿠시카츠 거리","th":"ถนนคุชิคัตสึชินเซไก โอซาก้า"}],"historyStory":{"zh-TW":"大正末期至昭和初期，新世界聚集許多從事繁重體力勞動的碼頭與建築工人。為了讓工人們花小錢就能吃飽，店家將牛肉、鵪鶉蛋、洋蔥切塊串在竹籤上，裹上厚麵衣沾超細麵包粉酥炸，沾上共用鐵盒醬汁，搭配新鮮解膩的免費生高麗菜，誕生了風靡全球的大阪串炸文化！","en":"Born in the 1920s to feed hungry working-class laborers cheaply. Beef, lotus root, and quail eggs are skewered, coated in fine panko, and dipped into communal sauce tanks.","ja":"大正から昭和初期、新世界の労働者のために安くて満腹になるよう考案されたのが始まり。サクサクの細かい衣とキャベツが特徴。","ko":"1920년대 오사카의 노동자들을 위해 저렴하고 든든하게 먹을 수 있도록 고안된 서민 꼬치튀김입니다.","th":"เริ่มต้นในช่วงปี 1920 สำหรับผู้ใช้แรงงาน นำเนื้อสัตว์และผักมาเสียบไม้ชุบแป้งทอดกรอบ"},"japaneseKanji":"串カツ","japaneseKana":"くしかつ","japaneseRomaji":"Kushikatsu","audioPronunciationText":"串カツ","nativeName":"串カツ","nativePhonetics":"くしかつ"},"ingredients":[{"id":"beef-cubes","name":{"zh-TW":"牛里肌或豬梅花肉塊 (Beef or Pork cubes)","en":"Beef sirloin or pork loin cubes (2cm)","ja":"牛もも肉または豚ヒレ肉（一口大）","ko":"소고기 또는 돼지 안심 깍둑썰기","th":"เนื้อวัวหรือเนื้อหมูหั่นเต๋า 2 ซม."},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"japaneseKanji":"牛角切り肉","japaneseKana":"ぎゅうかくぎりにく","japaneseRomaji":"Gyū Kakugiri Niku"},{"id":"quail-eggs","name":{"zh-TW":"水煮鵪鶉蛋 (Boiled Quail Eggs peeled)","en":"Boiled quail eggs, peeled","ja":"うずらの卵水煮","ko":"메추리알 삶은 것","th":"ไข่นกกระทาต้มสุกปอกเปลือก"},"amount":6,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"うずらの卵","japaneseKana":"うずらのたまご","japaneseRomaji":"Uzura no Tamago"},{"id":"lotus-root","name":{"zh-TW":"蓮藕片 (Lotus Root slices)","en":"Lotus root slices (Renkon)","ja":"れんこん（輪切り）","ko":"연근 슬라이스","th":"รากบัวหั่นแว่น"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","japaneseKanji":"蓮根","japaneseKana":"れんこん","japaneseRomaji":"Renkon"},{"id":"panko-fine","name":{"zh-TW":"超細日式麵包粉 (Fine Japanese Panko)","en":"Ultra-fine Japanese Panko breadcrumbs","ja":"極細目パン粉","ko":"초미세 빵가루","th":"เกล็ดขนมปังญี่ปุ่นชนิดละเอียดพิเศษ"},"amount":80,"unitMetric":"g","unitUS":"1 cup","isKeyFlavor":true,"japaneseKanji":"細目パン粉","japaneseKana":"こまめぱんこ","japaneseRomaji":"Komame Panko"},{"id":"batter-flour","name":{"zh-TW":"低筋麵粉與全蛋粉漿 (Flour Egg Batter / Neriko)","en":"Batter (flour, egg, ice water whisked)","ja":"練り粉（小麦粉、卵、冷水）","ko":"밀가루 반죽물 (밀가루, 달걀, 찬물)","th":"แป้งชุบทอด (แป้งเค้ก ไข่ไก่ น้ำเย็นจัด)"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","japaneseKanji":"練り粉","japaneseKana":"ねりこ","japaneseRomaji":"Neriko"},{"id":"worcestershire-sauce","name":{"zh-TW":"串炸秘傳沾醬 (Kushikatsu Dipping Sauce)","en":"Worcestershire sauce mixed with dashi & mirin","ja":"特製串カツソース（ウスター、出汁、みりん）","ko":"우스터소스 기반 특제 딥소스","th":"ซอสจิ้มคุชิคัตสึ (วูสเตอร์ผสมดาชิและมิริน)"},"amount":80,"unitMetric":"ml","unitUS":"1/3 cup","isKeyFlavor":true,"japaneseKanji":"串カツソース","japaneseKana":"くしかつそーす","japaneseRomaji":"Kushikatsu Sōsu"},{"id":"raw-cabbage","name":{"zh-TW":"手撕冰鎮生高麗菜葉 (Fresh Cabbage leaves)","en":"Crisp raw cabbage wedges for scooping sauce","ja":"生キャベツ（一口大にちぎったもの）","ko":"아삭한 생양배추 조각","th":"กะหล่ำปลีสดแช่เย็นฉีกชิ้น"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","japaneseKanji":"キャベツ","japaneseKana":"きゃべつ","japaneseRomaji":"Kyabetsu"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"食材穿串 (Skewer Ingredients)","en":"Skewer All Ingredients","ja":"食材を竹串に刺す","ko":"재료들을 꼬치에 꿰기","th":"นำวัตถุดิบเสียบไม้"},"instruction":{"zh-TW":"竹籤刺入牛肉塊（每串 2-3 塊）、鵪鶉蛋（每串 2 顆）、蓮藕片與香菇。食材表面撒上極少許鹽巴與黑胡椒提味。","en":"Thread beef, quail eggs, lotus root, and mushrooms onto skewers. Lightly season with salt and pepper.","ja":"牛肉、うずら卵、れんこん、椎茸をそれぞれ竹串に刺します。軽く塩コショウを振ります。","ko":"소고기, 메추리알, 연근, 버섯을 꼬치에 꿰고 소금, 후추로 밑간합니다.","th":"เสียบเนื้อวัว ไข่นกกระทา รากบัว และเห็ดหอม โรยเกลือและพริกไทยเล็กน้อย"},"durationSeconds":300,"image":"/images/jp/kushikatsu-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"裹薄漿與極細麵包粉 (Batter & Fine Panko)","en":"Dip in Batter & Coat in Fine Panko","ja":"練り粉をくぐらせ極細パン粉を薄くまぶす","ko":"반죽물 입히고 미세 빵가루 얇게 묻히기","th":"ชุบแป้งเปียกและคลุกเกล็ดขนมปังชนิดละเอียด"},"instruction":{"zh-TW":"串好的食材先浸入調勻的稀薄粉漿（Neriko），瀝去多餘漿液；隨後埋入「極細麵包粉」中輕輕按壓裹滿，輕拍抖掉多餘碎屑（超細麵包粉是大阪串炸薄脆不扎嘴、不吸油的絕對關鍵！）。","en":"Dip skewered items into batter, drain excess, then roll in ultra-fine panko. Pat gently to form a paper-thin, even coating.","ja":"薄い練り粉にくぐらせ、極細パン粉の中に埋めて薄く均一に付けます。余分な粉はしっかり落とすのがプロの技。","ko":"묽은 반죽물에 적신 뒤 미세 빵가루를 얇게 묻히고 털어냅니다. 두껍지 않아야 바삭합니다.","th":"ชุบแป้งบางๆ แล้วคลุกเกล็ดขนมปังละเอียดให้ทั่ว เคาะเศษส่วนเกินออก"},"durationSeconds":240,"image":"/images/jp/kushikatsu-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"氣炸鍋模式：200°C (390°F) 氣炸 8 分鐘","instructionOverride":{"zh-TW":"表面均勻噴上一層薄油，放入氣炸鍋以 200°C 氣炸 8 分鐘，中途翻面，外皮同樣金黃酥脆！","en":"Mist generously with oil spray, air fry at 200°C for 8 mins, turning halfway for a crackly golden finish.","ja":"油をスプレーし、ノンフライヤー200℃で8分加熱。途中で返してカリッと仕上げます。","ko":"오일을 충분히 분사하고 200도에서 8분간 에어프라이어로 바삭하게 구워냅니다.","th":"ฉีดน้ำมันสเปรย์ อบในหม้อทอดไร้น้ำมัน 200°C นาน 8 นาที กลับด้านให้เหลืองทองทั่วถึง"}}]},{"stepNumber":3,"title":{"zh-TW":"高溫快炸至金黃 (Flash Fry at 180°C)","en":"Flash Fry at 180°C (355°F)","ja":"180℃の油でサッとキツネ色に揚げる","ko":"180도 기름에서 바삭하게 튀기기","th":"ทอดน้ำมันร้อน 180°C จนสีเหลืองทอง"},"instruction":{"zh-TW":"油鍋加熱至 180°C。手持竹籤將串物下鍋，高溫油炸約 90 秒至 2 分鐘，炸至外皮轉為淡金黃色、氣泡由大變小，立刻拉起瀝油，直立插在架上滴乾油份。","en":"Heat oil to 180°C. Submerge skewers for 90s to 2 mins until golden and crisp. Rest vertically on a wire rack to drain.","ja":"180℃に熱した油に串を入れ、1分半〜2分サッと揚げます。カラッときつね色になったら網に立てて油を切ります。","ko":"180도 기름에 넣고 1분 30초~2분간 바삭하게 튀겨내어 망에 세워 기름을 뺍니다.","th":"ทอดในน้ำมัน 180°C นาน 1.5 - 2 นาทีจนสีเหลืองทอง ตักขึ้นวางตั้งบนตะแกรงสะเด็ดน้ำมัน"},"durationSeconds":150,"image":"/images/jp/kushikatsu-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"浸沾醬汁與生高麗菜享用 (Dip Once & Enjoy)","en":"Dip ONCE and Savor with Cabbage","ja":"ソースに一度だけドボン！キャベツと一緒にいただく","ko":"소스에 딱 한 번 담가 양배추와 함께 먹기","th":"จุ่มซอสเพียงครั้งเดียว ทานคู่กะหล่ำปลีสด"},"instruction":{"zh-TW":"將剛炸出鍋、滋滋作響的炸串「整支浸入」深盒特製醬汁中（記住大阪鐵律：咬過一口嚴禁再伸進去沾二次！若醬汁不夠，用附贈的生高麗菜舀醬澆在上面），搭配生高麗菜葉爽脆解膩，趁熱享用！","en":"Plunge the entire hot skewer into the sauce box ONCE before biting. Never double dip! Scoop extra sauce with raw cabbage leaves.","ja":"アツアツの串カツをタレ缶に「一度だけ」ドボンと浸してかぶりつきます！ソースが足りない時はキャベツですくってかけましょう。","ko":"갓 튀긴 꼬치를 소스에 단 한 번 푹 담갔다 꺼내 드세요! 소스가 부족하면 생양배추로 떠서 얹어 드세요.","th":"จุ่มไม้ลงในถาดซอสทั้งไม้อย่างรวดเร็วเพียงครั้งเดียว ห้ามจิ้มซ้ำเด็ดขาด ใช้กะหล่ำปลีตักซอสเพิ่มได้"},"durationSeconds":30,"image":"/images/jp/kushikatsu-step4.jpg"}],"troubleshooting":[{"id":"trouble-kushi-1","problem":{"zh-TW":"麵衣太厚太硬，吃起來像美式熱狗？","en":"Why is the batter too thick and doughy instead of light and crisp?","ja":"衣が厚くて重く、サクッと軽くなりません。","ko":"튀김옷이 너무 두껍고 퍽퍽해요.","th":"ทำไมแป้งทอดหนาเตอะไม่กรอบโปร่ง?"},"cause":{"zh-TW":"粉漿調得太稠、或者使用了顆粒粗大的西式麵包粉。","en":"Batter was too thick or used coarse Western breadcrumbs instead of fine Japanese panko.","ja":"練り粉が濃すぎたか、粒の粗いパン粉を使ったため。","ko":"반죽물이 너무 걸쭉했거나 입자가 굵은 빵가루를 썼기 때문입니다.","th":"แป้งชุบข้นเกินไป หรือใช้เกล็ดขนมปังหยาบ"},"solution":{"zh-TW":"粉漿要調成如生乳般稀薄流動，麵包粉務必用手搓細或料理機打成極細粉。","en":"Whisk batter thin like whole milk, and crush panko finely before coating.","ja":"練り粉はサラサラに薄め、パン粉は手で細かくすりつぶして使いましょう。","ko":"반죽물을 우유처럼 묽게 만들고 빵가루를 잘게 부수어 사용하세요.","th":"ผสมแป้งเปียกให้เหลวเหมือนนมสด และบดเกล็ดขนมปังให้ละเอียดก่อนชุบ"}}],"proTips":[{"zh-TW":"【特製串炸醬調配公式】：伍斯特辣醬油 4 大匙 + 柴魚高湯 2 大匙 + 味醂 1 大匙 + 砂糖 1 茶匙煮滾放涼，比市售醬汁更清爽甘甜，完全不死鹹！","en":"Homemade Kushikatsu Sauce: 4 tbsp Worcestershire + 2 tbsp dashi broth + 1 tbsp mirin + 1 tsp sugar simmered and chilled.","ja":"【秘伝ソースの黄金比】：ウスターソース4：出汁2：みりん1：砂糖小さじ1を一煮立ち。あっさりフルーティーに仕上がります。","ko":"우스터소스 4큰술, 다시 육수 2큰술, 미림 1큰술, 설탕 1작은술을 살짝 끓여 식히면 짜지 않은 정통 소스가 됩니다.","th":"สูตรซอสคุชิคัตสึ: ซอสวูสเตอร์ 4 ชต. + น้ำซุปดาชิ 2 ชต. + มิริน 1 ชต. + น้ำตาล 1 ชช. ต้มให้เดือดแล้วพักให้เย็น"}]},{"country":"jp","id":"mitarashi-dango","slug":"kyoto-mitarashi-dango","title":{"zh-TW":"京都風炙烤醬油糰子","en":"Kyoto Grilled Mitarashi Dango","ja":"京都発祥 焼きたて香ばしみたらし団子","ko":"교토식 갓 구운 미타라시 당고 (간장 조림 경단)","th":"มิตาราชิ ดังโงะ ย่างซอสโชยุหวานสไตล์เกียวโต"},"subtitle":{"zh-TW":"白玉米糰炙烤微焦斑痕、琥珀甜鹹葛粉醬汁晶瑩淋覆","en":"Chewy grilled mochi rice dumplings glazed in glossy, sweet-savory amber soy sauce","ja":"香ばしい焦げ目ともちもち食感！特製とろみ醤油タレがたっぷり絡む伝統和菓子","ko":"은은한 불맛과 쫄깃한 식감, 달콤 짭조름한 윤기 나는 간장 글레이즈","th":"ลูกชิ้นแป้งโมจิย่างเกรียมหอม ราดซอสโชยุเหนียวข้นสีอำพันหวานเค็มกลมกล่อม"},"tagline":{"zh-TW":"京都下鴨神社發祥的千年和風甘味，軟糯彈牙、放涼依舊柔軟！","en":"Ancient Kyoto wagashi with 1,000 years of history, effortlessly made in 20 minutes.","ja":"下鴨神社の御手洗祭りが起源。冷めても柔らかい黄金比率の白玉粉ブレンド。","ko":"천년 역사의 교토 전통 화과자! 식어도 굳지 않고 부드러운 황금 비율.","th":"ขนมหวานโบราณพันปีจากศาลเจ้าชิโมกาโมะ เกียวโต นุ่มหนึบเคี้ยวเพลิน"},"heroImage":"/images/jp/mitarashi-dango-hero.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":10,"defaultServings":3,"caloriesPerServing":180,"category":"sweets","dietaryTags":["classic","vegetarian","vegan"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"京都府京都市左京區・下鴨神社 (Kyoto)","en":"Shimogamo Shrine, Kyoto","ja":"京都市左京区下鴨神社（加茂みたらし茶屋）","ko":"교토 시모가모 신사","th":"ศาลเจ้าชิโมกาโมะ เกียวโต"},"famousYataiMarkets":[{"zh-TW":"京都下鴨神社御手洗茶屋","en":"Kamo Mitarashi Tea House, Kyoto","ja":"加茂みたらし茶屋","ko":"카모 미타라시 찻집","th":"คาโมะ มิตาราชิ เกียวโต"},{"zh-TW":"東京淺草寺仲見世通","en":"Asakusa Nakamise, Tokyo","ja":"浅草仲見世茶屋","ko":"아사쿠사 나카미세","th":"ถนนนากามิเสะ อาซากุสะ"}],"historyStory":{"zh-TW":"相傳鎌倉時代後醍醐天皇造訪京都下鴨神社御手洗池時，池中先冒出 1 個大水泡，隨後連冒 4 個小水泡，因此傳統京都糰子每串穿 5 顆（頂部 1 顆代表頭部，下方 4 顆代表人體四肢）。將糰子在炭火上炙出微焦，裹上濃郁葛粉甘鹹醬汁，祈求無病息災！","en":"Originating at Shimogamo Shrine when Emperor Godaigo observed bubbles in the sacred pond (1 bubble, then 4), inspiring the 5-dumpling skewer representing the human body. Glazed with sweet soy sauce as an offering of health.","ja":"後醍醐天皇が下鴨神社の御手洗池で水を掬った際、最初に1つの泡、続いて4つの泡が出た故事に由来。串に5つの団子を刺すのが本場京都の伝統です。","ko":"시모가모 신사의 연못에서 솟아난 물방울 모양을 본떠 만든 것에서 유래하여 건강과 평안을 비는 음식입니다.","th":"มีต้นกำเนิดจากศาลเจ้าชิโมกาโมะ เลียนแบบฟองน้ำศักดิ์สิทธิ์ เสียบไม้ละ 5 ลูก ย่างเกรียมแล้วราดซอสหวานเค็ม"},"japaneseKanji":"みたらし団子","japaneseKana":"みたらしだんご","japaneseRomaji":"Mitarashi Dango","audioPronunciationText":"みたらし団子","nativeName":"みたらし団子","nativePhonetics":"みたらしだんご"},"ingredients":[{"id":"shiratamako","name":{"zh-TW":"白玉粉 (Shiratamako Sweet Rice Flour)","en":"Shiratamako (Glutinous Rice Flour)","ja":"白玉粉","ko":"시라타마코 (찹쌀가루)","th":"แป้งชิราทามะ (แป้งข้าวเหนียวญี่ปุ่น)"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":true,"japaneseKanji":"白玉粉","japaneseKana":"しらたまこ","japaneseRomaji":"Shiratamako"},{"id":"joshinko","name":{"zh-TW":"上新粉 / 在來米粉 (Joshinko Non-Glutinous Rice Flour)","en":"Joshinko (Regular Rice Flour)","ja":"上新粉（米粉）","ko":"조신코 (멥쌀가루)","th":"แป้งโจชินโกะ (แป้งข้าวเจ้าญี่ปุ่น)"},"amount":50,"unitMetric":"g","unitUS":"1.8 oz","japaneseKanji":"上新粉","japaneseKana":"じょうしんこ","japaneseRomaji":"Jōshinko","substitute":{"substituteName":{"zh-TW":"全用一般糯米粉 + 嫩豆腐 120g 揉麵","en":"100% Glutinous Rice Flour + 120g Silken Tofu","ja":"白玉粉のみ ＋ 絹豆腐120g","ko":"찹쌀가루 100% + 연두부 120g","th":"แป้งข้าวเหนียว 100% ผสมเต้าหู้อ่อน 120 กรัม"},"ratio":"1:1","explanation":{"zh-TW":"用豆腐代替水揉糯米粉，放涼一整天依然像剛出爐一樣軟Q彈牙！","en":"Kneading with silken tofu instead of water keeps dango soft and pliable even when chilled.","ja":"水の代わりに絹豆腐で練ると、冷めても固くならず驚くほど柔らかいままです。","ko":"물 대신 연두부로 반죽하면 시간이 지나도 딱딱해지지 않고 말랑말랑합니다.","th":"นวดด้วยเต้าหู้อ่อนแทนน้ำ ขนมจะนุ่มหนึบได้ทั้งวันแม้ทิ้งไว้จนเย็น"},"whereToBuy":{"zh-TW":"任何超市均有售嫩豆腐與糯米粉","en":"Any local supermarket","ja":"スーパーの豆腐コーナー・粉売り場","ko":"일반 마트 두부 및 찹쌀가루 코너","th":"ซูเปอร์มาร์เก็ตทั่วไป"}}},{"id":"warm-water","name":{"zh-TW":"溫水 (Lukewarm Water)","en":"Warm Water","ja":"ぬるま湯","ko":"미온수","th":"น้ำอุ่น"},"amount":130,"unitMetric":"ml","unitUS":"0.5 cup","japaneseKanji":"ぬるま湯","japaneseKana":"ぬるまゆ","japaneseRomaji":"Nurumayu"},{"id":"shoyu","name":{"zh-TW":"濃口醬油 (Soy Sauce)","en":"Japanese Soy Sauce","ja":"醤油","ko":"간장","th":"โชยุญี่ปุ่น"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","isKeyFlavor":true,"japaneseKanji":"醤油","japaneseKana":"しょうゆ","japaneseRomaji":"Shōyu"},{"id":"mirin","name":{"zh-TW":"味醂 (Mirin)","en":"Mirin","ja":"みりん","ko":"미림","th":"มิริน"},"amount":20,"unitMetric":"ml","unitUS":"1.5 tbsp","japaneseKanji":"みりん","japaneseKana":"みりん","japaneseRomaji":"Mirin"},{"id":"sugar","name":{"zh-TW":"砂糖 (Sugar)","en":"Sugar","ja":"上白糖","ko":"설탕","th":"น้ำตาลทราย"},"amount":45,"unitMetric":"g","unitUS":"3 tbsp","isKeyFlavor":true,"japaneseKanji":"砂糖","japaneseKana":"さとう","japaneseRomaji":"Satō"},{"id":"katakuriko-water","name":{"zh-TW":"片栗粉水勾芡 (Potato Starch Slurry)","en":"Potato starch (1 tbsp) mixed with water (2 tbsp)","ja":"水溶き片栗粉","ko":"물전분","th":"แป้งมันฝรั่งละลายน้ำ"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","japaneseKanji":"片栗粉","japaneseKana":"かたくりこ","japaneseRomaji":"Katakuriko"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"揉合米糰搓圓 (Knead & Roll Dumplings)","en":"Knead Dough & Roll into Spheres","ja":"白玉粉を練り一口大の団子に丸める","ko":"가루를 치대어 한입 크기로 둥글리기","th":"นวดแป้งและปั้นเป็นก้อนกลมพอดีคำ"},"instruction":{"zh-TW":"盆中混合白玉粉與上新粉，分次加入溫水，用手揉捏成「如耳垂般柔軟」的光滑麵糰。將麵糰均勻分成約 15 顆小球（每顆約 18g），在手掌心中搓至表面圓潤光滑。","en":"Combine flours, add warm water gradually, kneading into a smooth dough pliable as an earlobe. Portion into 15 equal balls (~18g each) and roll smooth.","ja":"白玉粉と上新粉を合わせ、ぬるま湯を少しずつ加えながら「耳たぶの硬さ」になるまでよくこねます。15等分して手のひらで丸めます。","ko":"가루를 섞고 미온수를 조금씩 부어가며 귓볼 부드러움 정도로 반죽합니다. 15개로 나누어 매끄럽게 둥글립니다.","th":"ผสมแป้งทั้งสองชนิด ค่อยๆ เติมน้ำอุ่น นวดจนนุ่มเหมือนติ่งหู ปั้นเป็นก้อนกลม 15 ลูก"},"durationSeconds":300,"image":"/images/jp/mitarashi-dango-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"沸水煮透與冰鎮 (Boil & Ice Bath)","en":"Boil Floating Dumplings & Ice Bath","ja":"茹でて浮き上がったら冷水で締める","ko":"끓는 물에 삶아 떠오르면 얼음물에 식히기","th":"ต้มในน้ำเดือดจนลอยและแช่น้ำเย็นจัด"},"instruction":{"zh-TW":"起大鍋滾水，將糰子輕輕滑入鍋中。煮至所有糰子「完全浮上水面」後，再繼續煮 2 分鐘確保中心熟透。用漏勺撈起，立刻投入冰水中冷卻冰鎮（冰鎮能讓外皮瞬間收縮緊緻，更加Q彈牙！），瀝乾穿串（每支竹籤穿 3-4 顆）。","en":"Drop dumplings into boiling water. Once they float to the surface, boil 2 more mins. Shock in an ice water bath to set chewiness, then skewer 3-4 balls per stick.","ja":"沸騰したお湯に団子を入れ、プカプカ浮き上がってからさらに2分茹でます。氷水にとってキュッと締め、水気を切って串に3〜4個ずつ刺します。","ko":"끓는 물에 넣고 위로 떠오르면 2분간 더 삶아 얼음물에 담가 식힙니다. 꼬치에 3~4개씩 꿱니다.","th":"ต้มในน้ำเดือดจนลอยขึ้นมา ต้มต่ออีก 2 นาที ตักแช่น้ำเย็นจัดทันทีเพื่อความหนึบ เสียบไม้ละ 3-4 ลูก"},"durationSeconds":240,"image":"/images/jp/mitarashi-dango-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"乾烙炙烤迷人焦斑 (Sear Char Marks)","en":"Char the Dumplings on Pan or Grill","ja":"フライパンで香ばしい焼き目をつける","ko":"팬에서 노릇하게 불맛 나는 그을림 만들기","th":"นำไปย่างบนกระทะให้เกิดรอยเกรียมหอม"},"instruction":{"zh-TW":"平底鍋不放油（或極薄薄油），以中大火加熱。將糰子串平排鍋中，乾煎烘烤約 2 分鐘，翻面再煎 1 分鐘，直到表面出現一塊塊誘人的黑金焦斑與濃郁米香。","en":"Heat a dry skillet on medium-high. Sear skewered dumplings unglazed for 2 mins, flip for 1 min, creating signature roasted char blisters.","ja":"油を引かない（またはごく薄く引いた）フライパンで中火で両面を焼き、香ばしい焼き目をしっかりつけます。","ko":"마른 팬에 꼬치를 올리고 앞뒤로 1~2분씩 구워 먹음직스러운 갈색 그을림을 만듭니다.","th":"ย่างบนกระทะไม่ใช้น้ำมัน ย่างด้านละ 1-2 นาทีจนมีรอยไหม้เกรียมหอมกลิ่นข้าวคั่ว"},"durationSeconds":180,"image":"/images/jp/mitarashi-dango-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"熬製晶瑩琥珀蜜汁 (Simmer Glossy Glaze)","en":"Simmer Glossy Mitarashi Glaze","ja":"醤油、みりん、砂糖にとろみをつけてタレを作る","ko":"간장, 미림, 설탕에 물전분을 풀어 소스 졸이기","th":"เคี่ยวซอสโชยุหวานให้เหนียวใส"},"instruction":{"zh-TW":"小鍋中加入水 60ml、醬油、味醂、砂糖，小火煮融。緩緩淋入片栗粉水，用打蛋器邊倒邊快速攪拌，小火加熱至醬汁沸騰冒大泡，轉為透明晶瑩、濃稠流動的琥珀蜜汁，關火。","en":"In a saucepan, heat 60ml water, soy sauce, mirin, and sugar until melted. Whisk in potato starch slurry and simmer until bubbling, turning glossy and clear.","ja":"小鍋に水60ml、醤油、みりん、砂糖を入れ火にかける。水溶き片栗粉を回し入れ、木べらで絶えず混ぜながら透明感ととろみが出るまで煮詰めます。","ko":"냄비에 물 60ml, 간장, 미림, 설탕을 끓이다가 물전분을 넣고 저어가며 투명하고 걸쭉하게 조립니다.","th":"ต้มน้ำ 60 มล. โชยุ มิริน และน้ำตาล ใส่แป้งมันละลายน้ำ คนตลอดเวลาจนซอสใสเหนียวขึ้นเงา"},"durationSeconds":150,"image":"/images/jp/mitarashi-dango-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"厚淋醬汁與趁熱品嚐 (Glaze & Serve Warm)","en":"Generously Glaze & Serve Warm","ja":"アツアツのタレをたっぷり回しかけて完成","ko":"따뜻한 소스를 듬뿍 끼얹어 완성","th":"ราดซอสร้อนๆ ให้เคลือบชุ่มทั่วไม้"},"instruction":{"zh-TW":"將烤好的糰子排入盤中，用湯匙大方將滾燙的琥珀醬汁厚厚淋覆在糰子上，確保每顆糰子都被晶亮滑順的醬汁包裹。趁熱咬下，米香、焦香、鹹甜交織，幸福感滿溢！","en":"Plate hot charred dumplings. Ladle bubbling mitarashi glaze lavishly over the skewers. Savor the warm, sweet-savory harmony immediately!","ja":"焼きたての団子をお皿に並べ、たっぷりと温かいタレをまとわせます。甘じょっぱい至福のひとときをどうぞ！","ko":"접시에 담고 뜨거운 소스를 듬뿍 끼얹어줍니다. 단짠의 완벽한 조화를 즐기세요!","th":"จัดใส่จาน ตักซอสราดเคลือบจนทั่วทั้งไม้ เสิร์ฟอุ่นๆ หวานหอมเค็มลงตัว"},"durationSeconds":60,"image":"/images/jp/mitarashi-dango-step5.jpg"}],"troubleshooting":[{"id":"trouble-dango-1","problem":{"zh-TW":"為什麼醬汁冷卻後出水變稀，無法附著在糰子上？","en":"Why did the sauce become watery after cooling instead of staying thick?","ja":"タレが冷めるとサラサラになって団子に絡みません。","ko":"소스가 식으면서 묽어져 떡에 묻지 않아요.","th":"ทำไมซอสพอเย็นลงแล้วกลายเป็นน้ำเหลวไม่เกาะตัวแป้ง?"},"cause":{"zh-TW":"勾芡時澱粉水加入後加熱時間不足，澱粉分子尚未完全糊化膠融。","en":"Starch slurry was not cooked long enough after adding; starch needs full boiling to gelatinize properly.","ja":"片栗粉を入れた後の加熱が足りず、完全に糊化（アルファ化）していないためです。","ko":"물전분을 넣고 충분히 끓이지 않아 전분이 완전히 호화되지 않았기 때문입니다.","th":"หลังจากใส่แป้งละลายน้ำแล้วต้มไม่นานพอ แป้งยังไม่สุกเต็มที่จึงคืนตัว"},"solution":{"zh-TW":"加入片栗粉水後，務必小火持續攪拌加熱至「連續大冒泡」至少 30 秒，呈現透明光澤才關火。","en":"After adding starch, simmer gently for at least 30 seconds while bubbling until translucent before turning off.","ja":"片栗粉を入れたら、ブツブツと沸騰して透明になるまで弱火で30秒しっかり練り上げましょう。","ko":"물전분을 넣은 뒤 보글보글 끓으며 투명해질 때까지 30초 이상 계속 저어주며 끓이세요.","th":"เคี่ยวไฟอ่อนต่อ 30 วินาทีจนเดือดปุดๆ และใสขึ้นเงา จึงปิดไฟ"}}],"proTips":[{"zh-TW":"【白玉粉 + 豆腐神組合】：家庭製作時若無上新粉，可以用「白玉粉 100g + 嫩豆腐 100-110g」直接揉成糰，完全不加一滴水，煮出來軟Q度驚人，放冰箱冰過也不會硬化！","en":"Pro Baker secret: Mix 100g shiratamako with 100g silken tofu without any water. The dumplings stay pillowy soft even when refrigerated.","ja":"【豆腐白玉団子の裏技】：白玉粉100gに水ではなく絹豆腐100gを揉み込むと、冷蔵庫で冷やしてもモチモチがずっと続きます！","ko":"백옥분 100g에 물 없이 연두부 100g을 치대어 만들면 냉장고에 넣어도 굳지 않고 말랑말랑합니다.","th":"ผสมแป้งชิราทามะ 100 กรัมกับเต้าหู้อ่อน 100 กรัมโดยไม่ใช้น้ำเลย ขนมจะนุ่มนิ่มแม้แช่ตู้เย็น"}]},{"country":"jp","id":"tamagoyaki","slug":"japanese-dashimaki-tamago","title":{"zh-TW":"築地市場高湯玉子燒","en":"Tsukiji Style Dashimaki Tamago","ja":"築地場外市場 極上出汁巻き卵","ko":"츠키지 시장 스타일 다시마키 타마고 (일본식 계란말이)","th":"ไข่ม้วนดาชิสไตล์ตลาดปลาซึกิจิ"},"subtitle":{"zh-TW":"層層金黃折疊、輕輕一壓高湯如泉湧溢、軟嫩如果凍","en":"Layered golden egg roll, oozing dashi umami broth with jelly-like tender layers","ja":"箸を入れると溢れ出る芳醇なお出汁！ふんわりジューシーな職人仕込みの玉子焼き","ko":"젓가락을 대면 다시 육수가 촉촉하게 배어 나오는 부드러운 일본식 계란말이","th":"ไข่ม้วนสีทองเนื้อเนียนนุ่มดุจเจลลี่ น้ำซุปดาชิชุ่มฉ่ำทะลักทุกคำที่กัด"},"tagline":{"zh-TW":"日料職人基本功的極致展現！掌握 3 次折疊與廚房紙巾滾捲整形技巧。","en":"The ultimate test of a Japanese chef, simplified with the 3-fold towel-roll technique.","ja":"和食の技が光る逸品。四角いフライパンで誰でも綺麗に巻けるプロの裏技伝授。","ko":"일식 장인의 기본기를 집에서 완벽 재현! 3단계 말기와 키친타월 정형 꿀팁.","th":"บทพิสูจน์ฝีมือเชฟญี่ปุ่น ทำเองได้ง่ายๆ ด้วยเทคนิคม้วน 3 ทบและกระดาษซับน้ำมัน"},"heroImage":"/images/jp/tamagoyaki-hero.jpg","difficulty":"medium","prepTimeMinutes":10,"cookTimeMinutes":8,"defaultServings":2,"caloriesPerServing":160,"category":"yakimono","dietaryTags":["classic","vegetarian"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"東京都中央區・築地場外市場 (Tsukiji, Tokyo)","en":"Tsukiji Outer Market, Tokyo","ja":"東京都中央区築地場外市場","ko":"도쿄 츠키지 장외시장","th":"ตลาดนอกซึกิจิ โตเกียว"},"famousYataiMarkets":[{"zh-TW":"東京築地場外市場玉子燒老舖街（丸武、山長）","en":"Tsukiji Tamagoyaki Alley (Marutake & Yamacho)","ja":"築地玉子焼き専門店（丸武・山長など）","ko":"츠키지 계란말이 명점 거리","th":"ตรอกไข่ม้วนซึกิจิ (มารุทาเกะ, ยามาโจ)"},{"zh-TW":"京都錦市場三木雞卵","en":"Nishiki Market Miki Keiran, Kyoto","ja":"京都錦市場 三木鶏卵","ko":"교토 니시키 시장 미키 케이란","th":"ตลาดนิชิกิ มิคิเครัน เกียวโต"}],"historyStory":{"zh-TW":"在江戶壽司文化中，「玉子（Tamago）」是檢驗壽司職人功力最重要的一道考題。築地魚市旁因清晨勞動者需要迅速補充優質蛋白質，衍生出現烤現切的厚切高湯玉子燒，熱氣騰騰插上竹籤，成為世界各國遊客造訪東京必吃的國民早餐！","en":"In sushi tradition, Tamagoyaki tests a chef’s patience and heat control. In Tsukiji, morning fishmongers demanded quick, hearty protein, birthing the famous hot-skewer tamagoyaki stalls.","ja":"寿司職人の腕を測るバロメーター。築地では早朝から働く人々のために甘口や出汁たっぷりの焼きたてが串に刺して振る舞われ、名物となりました。","ko":"스시 장인의 실력을 가늠하는 기준 요리로, 츠키지 어시장에서 꼬치에 꽂아 팔기 시작하며 세계적인 명물이 되었습니다.","th":"บททดสอบฝีมือเชฟซูชิ ในตลาดซึกิจิเริ่มขายแบบเสียบไม้ร้อนๆ ให้คนงานทานตอนเช้าจนโด่งดัง"},"japaneseKanji":"出汁巻き卵","japaneseKana":"だしまきたまご","japaneseRomaji":"Dashimaki Tamago","audioPronunciationText":"出汁巻き卵","nativeName":"出汁巻き卵","nativePhonetics":"だしまきたまご"},"ingredients":[{"id":"eggs","name":{"zh-TW":"日本高品質生鮮雞蛋 (Fresh Eggs)","en":"Fresh large eggs","ja":"新鮮な鶏卵","ko":"신선한 달걀","th":"ไข่ไก่สดคัดพิเศษ"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"japaneseKanji":"鶏卵","japaneseKana":"けいらん","japaneseRomaji":"Keiran"},{"id":"dashi-stock","name":{"zh-TW":"鰹魚昆布高湯 (Dashi Stock chilled)","en":"Cold Dashi Stock","ja":"冷ました一番だし","ko":"식힌 가쓰오 다시마 육수","th":"น้ำซุปดาชิปลาแห้งและคอมบุเย็น"},"amount":80,"unitMetric":"ml","unitUS":"1/3 cup","isKeyFlavor":true,"japaneseKanji":"一番出汁","japaneseKana":"いちばんだし","japaneseRomaji":"Ichiban Dashi"},{"id":"usukuchi-shoyu","name":{"zh-TW":"薄口醬油 (Light Soy Sauce)","en":"Light Soy Sauce (Usukuchi)","ja":"薄口醤油","ko":"우스구치(연한) 간장","th":"โชยุสีอ่อน"},"amount":5,"unitMetric":"ml","unitUS":"1 tsp","japaneseKanji":"薄口醤油","japaneseKana":"うすくちしょうゆ","japaneseRomaji":"Usukuchi Shōyu"},{"id":"mirin","name":{"zh-TW":"本味醂 (Hon Mirin)","en":"Hon-Mirin","ja":"本みりん","ko":"미림","th":"มิริน"},"amount":15,"unitMetric":"ml","unitUS":"1 tbsp","japaneseKanji":"本みりん","japaneseKana":"ほんみりん","japaneseRomaji":"Hon-Mirin"},{"id":"sugar","name":{"zh-TW":"細砂糖 (Sugar - adjust to Kansai/Kanto style)","en":"Sugar (Kanto style is sweeter, Kansai is savory)","ja":"砂糖（関東風は甘め、関西風は少なめ）","ko":"설탕 (도쿄식은 달콤, 간사이식은 담백)","th":"น้ำตาลทราย"},"amount":10,"unitMetric":"g","unitUS":"2 tsp","japaneseKanji":"砂糖","japaneseKana":"さとう","japaneseRomaji":"Satō"},{"id":"daikon-oroshi","name":{"zh-TW":"白蘿蔔泥 (Grated Daikon Radish for garnish)","en":"Grated Daikon Radish","ja":"大根おろし","ko":"갈아낸 무 (다이콘 오로시)","th":"หัวไชเท้าขูดฝอย"},"amount":30,"unitMetric":"g","unitUS":"2 tbsp","japaneseKanji":"大根おろし","japaneseKana":"だいこんおろし","japaneseRomaji":"Daikon Oroshi"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"輕柔切斷蛋筋與調配 (Whisk Egg & Dashi)","en":"Whisk Eggs with Dashi without Froth","ja":"卵白のコシを切り出汁と合わせる","ko":"알끈을 끊어가며 육수와 섞기 (거품 내지 않기)","th":"ตีไข่ตัดเยื่อไข่ขาว ผสมน้ำซุปดาชิโดยไม่ให้เกิดฟอง"},"instruction":{"zh-TW":"在量杯中打入 4 顆雞蛋。用筷子緊貼杯底以「一字型」來回劃動切斷蛋白筋（切忌大肆打圈起泡，氣泡會導致玉子燒切面坑坑洞洞！）。加入高湯、薄口醬油、味醂與糖，攪勻後過細篩一次，確保液體如絲般細膩。","en":"Crack eggs into a measuring pitcher. Cut whites with chopsticks along the bottom without frothing. Stir in dashi, soy sauce, mirin, and sugar. Strain through a fine sieve for a mirror-smooth liquid.","ja":"ボウルに卵を割り入れ、箸を底につけたまま左右に動かして白身を切るようにほぐします（泡立てない）。出汁、薄口醤油、みりん、砂糖を加えて混ぜ、一度ザルで濾します。","ko":"젓가락을 바닥에 붙이고 좌우로 저어 알끈을 끊어줍니다 (거품 주의). 육수, 간장, 미림, 설탕을 섞고 체에 한 번 걸러줍니다.","th":"ตอกไข่ใส่ชาม ใช้ตะเกียบตัดเยื่อไข่ขาวโดยไม่ตีให้ขึ้นฟอง ใส่น้ำซุปดาชิและเครื่องปรุง กรองผ่านกระชอน 1 รอบ"},"durationSeconds":180,"image":"/images/jp/tamagoyaki-step1.jpg","crucialTips":{"zh-TW":"過篩（濾す）是做出如布丁般平滑細緻、毫無白斑點的關鍵一步，絕對不可偷懶！","en":"Straining the egg mixture through a fine mesh sieve removes chalaza and unmixed egg white for uniform color.","ja":"【濾すひと手間でプロの仕上がり】：ザルで一度濾すことで白身の塊がなくなり、どこを切っても美しい均一な黄色になります。","ko":"체에 거르는 과정이 푸딩처럼 매끄럽고 얼룩 없는 계란말이의 핵심입니다.","th":"การกรองผ่านกระชอนช่วยกำจัดเยื่อไข่ขาว ทำให้เนื้อเนียนละเอียดสีทองเสมอกัน"}},{"stepNumber":2,"title":{"zh-TW":"預熱專用鍋與第一層翻捲 (First Layer Roll)","en":"Preheat Tamagoyaki Pan & 1st Layer","ja":"玉子焼き器を温め、第一層を巻く","ko":"사각팬 예열 후 1차 계란물 붓고 말기","th":"วอร์มกระทะสี่เหลี่ยม เทไข่ชั้นแรกแล้วม้วน"},"instruction":{"zh-TW":"玉子燒方鍋以中火預熱，用紙巾沾油均勻塗抹鍋底與四壁。滴幾滴蛋液立刻凝固發出滋滋聲代表油溫正好。倒入約 1/4 的蛋液，轉動鍋子鋪平。戳破表面大氣泡，待表面半熟微凝時，用筷子從前方往自己的方向快速翻折 3 折，推回鍋子前端。","en":"Preheat square tamagoyaki pan on medium. Oil lightly with paper towel. Pour 1/4 of mixture. Pop big air bubbles. When half-set, fold 3 times towards you, then slide to the top.","ja":"四角い鍋を中火で温め油を引く。卵液の1/4を流し広げ、気泡を潰す。半熟になったら奥から手前にパタパタと3つ折りに巻き、奥へスライドさせます。","ko":"사각팬에 기름을 얇게 바르고 달걀물의 1/4을 붓습니다. 기포를 터뜨리고 반숙이 되면 앞쪽으로 말아 올린 뒤 다시 팬 안쪽으로 밉니다.","th":"ทาน้ำมันบางๆ เทไข่ 1/4 ส่วนลงไป เจาะฟองอากาศ เมื่อเริ่มสุกกึ่งสุกกึ่งดิบ ม้วน 3 ทบเข้ามาหาตัว แล้วเลื่อนไปไว้ด้านบน"},"durationSeconds":120,"image":"/images/jp/tamagoyaki-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"第二與第三層注入翻捲 (Subsequent Layers)","en":"Add 2nd & 3rd Layers (Lift to Flow)","ja":"卵を持ち上げて下にも流し入れ巻き重ねる","ko":"계란말이를 살짝 들어 밑으로 계란물 흘려 넣고 말기","th":"ยกไข่ก้อนเดิมขึ้น เทไข่ใหม่ให้ไหลลอดใต้ก้อนแล้วม้วนทบ"},"instruction":{"zh-TW":"空出的一半鍋底用紙巾再次補刷薄油。倒入另一份 1/4 蛋液，用筷子「抬起做好的第一卷蛋卷」，讓新蛋液流進下方底層。表面半熟時，再次從前端往後捲起包覆。重複此動作直到蛋液倒完，形成厚實金黃的大蛋卷。","en":"Re-oil empty space. Pour next batch. Lift the cooked roll with chopsticks so raw egg flows underneath. Roll towards you once set. Repeat until batter is finished.","ja":"空いたスペースに油を塗り、次の卵液を流す。巻いた卵を少し持ち上げて下にも卵液を流し込み、半熟になったら手前に巻き込みます。","ko":"빈 곳에 기름칠하고 다음 달걀물을 부은 뒤, 기존 계란말이를 살짝 들어 밑으로 흘려보냅니다. 반숙일 때 다시 말아줍니다.","th":"ทาน้ำมันซ้ำ เทไข่ส่วนต่อไป ใช้ตะเกียบยกไข่ม้วนเดิมขึ้นให้ไข่ใหม่ไหลลงไปข้างใต้ แล้วม้วนทับซ้ำจนหมด"},"durationSeconds":180,"image":"/images/jp/tamagoyaki-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"壽司竹簾整形與切塊 (Shape with Makisu)","en":"Shape with Bamboo Mat & Slice","ja":"巻きす（またはペーパー）で形を整えて切り分ける","ko":"김발이나 키친타월로 네모나게 각 잡고 썰기","th":"ห่อด้วยเสื่อม้วนซูชิจัดทรงสี่เหลี่ยมแล้วหั่น"},"instruction":{"zh-TW":"將熱騰騰的玉子燒滑出至壽司竹簾（或乾淨廚房紙巾）上，緊緊捲起，輕壓四個邊角整修成方正端莊的長方體，靜置 5 分鐘定型鎖住高湯。用利刀切成約 2-2.5 公分厚片，擠出白蘿蔔泥滴上一滴醬油佐餐，入口湯汁四溢！","en":"Slide hot egg roll onto a bamboo sushi mat (makisu). Wrap snugly and gently press to shape into crisp square edges. Rest 5 mins to settle juices. Slice into 2cm pieces, serve with grated daikon.","ja":"熱いうちに巻きす（またはキッチンペーパー）で包み、四角く形を整えて5分休ませます。2cm幅に切り分け、大根おろしと醤油を添えてどうぞ！","ko":"뜨거울 때 김발로 감싸 네모반듯하게 각을 잡고 5분간 두어 육수를 가둡니다. 2cm 두께로 썰어 무즙과 간장을 곁들입니다.","th":"นำไข่ม้วนวางบนเสื่อซูชิ ห่อและบีบให้เป็นทรงสี่เหลี่ยมสวยงาม พัก 5 นาที หั่นชิ้นหนา 2 ซม. เสิร์ฟพร้อมหัวไชเท้าขูด"},"durationSeconds":180,"image":"/images/jp/tamagoyaki-step4.jpg"}],"troubleshooting":[{"id":"trouble-tama-1","problem":{"zh-TW":"翻卷時蛋皮容易破碎撕裂？","en":"Why does the egg layer tear when attempting to fold?","ja":"巻く時に卵が破れてボロボロになってしまいます。","ko":"말 때 계란이 찢어지고 부서져요.","th":"ทำไมเวลาม้วนแล้วไข่ขาดแตกเป็นชิ้นๆ?"},"cause":{"zh-TW":"蛋液太早翻動（底部還沒凝固），或者高湯比例過高水分過多。","en":"Attempted to fold too early before the bottom sheet set, or added too much liquid dashi.","ja":"固まるのが早すぎたか、出汁の量が多すぎて柔らかくなりすぎたため。","ko":"밑면이 굳기 전에 너무 일찍 말았거나 육수 비율이 너무 높아 힘이 없기 때문입니다.","th":"ม้วนเร็วเกินไปขณะที่ไข่ยังไม่เซ็ตตัว หรือใส่น้ำซุปมากเกินไปจนไข่เหลว"},"solution":{"zh-TW":"新手可將高湯量稍微減少至 60ml，並等待表面從液態轉為「如果凍般微凝半熟」時再開始捲動。","en":"Beginners can reduce dashi to 60ml, and wait until the top looks like trembling jelly before rolling.","ja":"初心者は出汁を60mlに減らし、表面が半熟ゼリー状になるのを見極めてから巻きましょう。","ko":"초보자는 육수를 60ml로 줄이고 표면이 젤리처럼 살짝 굳었을 때 조심스럽게 마세요.","th":"สำหรับมือใหม่ให้ลดน้ำซุปเหลือ 60 มล. และรอให้ไข่เริ่มเซ็ตตัวดุจเจลลี่ก่อนค่อยม้วน"}}],"proTips":[{"zh-TW":"【每次補油用紙巾最均勻】：捲玉子燒時千萬不要拿油瓶直接倒油！準備一個浸滿沙拉油的小紙巾團，每捲一次就迅速輕擦一遍鍋面，保證受熱均勻且完全不油膩。","en":"Use an oil-soaked wad of paper towel to grease the pan between layers rather than pouring from a bottle.","ja":"【油引きはキッチンペーパーで】：油を直接注がず、ペーパーに染み込ませてサッと拭くように塗ると余分な油がつかず焦げ付きません。","ko":"기름을 직접 붓지 말고 키친타월에 기름을 적셔 매 단계마다 얇게 닦아주듯 발라주세요.","th":"ใช้ทิชชูชุบน้ำมันเช็ดกระทะแทนการเทน้ำมันโดยตรง จะทำให้ไข่สุกสม่ำเสมอและไม่อมน้ำมัน"}]},{"country":"jp","id":"yaki-gyoza","slug":"japanese-crispy-hanetsuki-gyoza","title":{"zh-TW":"宇都宮冰花脆皮煎餃","en":"Crispy Hanetsuki Pan-Fried Gyoza","ja":"宇都宮風 パリパリ羽根つき焼き餃子","ko":"우츠노미야 스타일 눈꽃 바삭 날개 군만두 (교자)","th":"เกี๊ยวซ่ากระทะร้อน แป้งกรอบรูปปีกนก"},"subtitle":{"zh-TW":"雪花蕾絲般極致薄脆冰花底、咬開爆汁的高麗菜豬肉餡","en":"Golden lace-winged crispy lattice bottom, bursting with juicy pork and sweet cabbage","ja":"パリッと香ばしいレース状の羽根！ジューシーな肉汁とキャベツの甘みが溢れる餃子","ko":"환상적인 레이스 모양의 바삭한 눈꽃 날개와 육즙이 팡팡 터지는 고기만두","th":"แป้งกรอบลายลูกไม้ดุจปีกนก ไส้หมูสับและกะหล่ำปลีหวานฉ่ำน้ำซุป"},"tagline":{"zh-TW":"全日本第一煎餃之都秘方！掌握麵粉水黃金比例，倒扣出整盤完美蕾絲冰花。","en":"Utsunomiya city’s signature: Master the starch slurry for perfect lace wings.","ja":"餃子の街・宇都宮の味！水溶き薄力粉の黄金比で誰でもきれいな羽根つきに。","ko":"교자의 도시 우츠노미야의 비법! 전분물 비율로 완벽한 눈꽃 날개 완성.","th":"สูตรเด็ดจากเมืองแห่งเกี๊ยวซ่า เคล็ดลับน้ำแป้งทอดให้เกิดเกล็ดกรอบสวยงาม"},"heroImage":"/images/jp/yaki-gyoza-hero.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":8,"defaultServings":3,"caloriesPerServing":310,"category":"konamono","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"栃木縣宇都宮市・靜岡縣濱松市 (Utsunomiya)","en":"Utsunomiya & Hamamatsu (Gyoza Capitals of Japan)","ja":"栃木県宇都宮市・静岡県浜松市","ko":"도치기현 우츠노미야시 & 시즈오카현 하마마츠시","th":"เมืองอุทสึโนะมิยะ จังหวัดโทจิกิ"},"famousYataiMarkets":[{"zh-TW":"宇都宮煎餃通商店街","en":"Utsunomiya Gyoza Street, Tochigi","ja":"宇都宮餃子通り","ko":"우츠노미야 교자 거리","th":"ถนนเกี๊ยวซ่าอุทสึโนะมิยะ"},{"zh-TW":"福岡博多一口餃子屋台","en":"Hakata Hitokuchi Gyoza Stalls, Fukuoka","ja":"博多一口餃子屋台","ko":"하카타 히토쿠치 교자 야타이","th":"ร้านยาไตเกี๊ยวซ่าคำเดียว ฮากาตะ"}],"historyStory":{"zh-TW":"二戰期間駐紮在中國東北的日本士兵退役回國後，在栃木縣宇都宮等地復刻並改良餃子。日式煎餃皮極薄、蔬菜（高麗菜與大蒜韭菜）比例高於肉餡，並發明以麵粉水煎出「羽（冰花脆翅）」的獨特工藝，成為日本最火爆的拉麵店與居酒屋靈魂副食！","en":"Brought back by Japanese soldiers from Manchuria post-WWII and adapted in Utsunomiya. Featuring paper-thin wrappers and a higher vegetable ratio, with a signature crispy starch lace lattice.","ja":"戦後、満州から復員した兵士によって宇都宮などで広まる。野菜多めの餡と薄皮、パリパリの羽根（羽付き）が日本独自の食文化へ発展しました。","ko":"전후 만주에서 돌아온 군인들에 의해 퍼져나갔으며, 얇은 피와 풍부한 채소, 바삭한 전분 날개가 특징입니다.","th":"ทหารญี่ปุ่นนำสูตรกลับมาดัดแปลงหลังสงคราม แป้งบางเฉียบ เน้นผักกะหล่ำปลีหวาน และแผ่นแป้งกรอบคล้ายปีกนก"},"japaneseKanji":"羽根つき焼き餃子","japaneseKana":"はねつきやきぎょうざ","japaneseRomaji":"Hanetsuki Yaki Gyōza","audioPronunciationText":"焼き餃子","nativeName":"羽根つき焼き餃子","nativePhonetics":"はねつきやきぎょうざ"},"ingredients":[{"id":"pork-mince","name":{"zh-TW":"豬細絞肉（肥瘦比 3:7） (Ground Pork)","en":"Ground pork (30% fat for juiciness)","ja":"豚ひき肉","ko":"돼지고기 다짐육","th":"หมูบดติดมัน 30%"},"amount":180,"unitMetric":"g","unitUS":"6.3 oz","isKeyFlavor":true,"japaneseKanji":"豚ひき肉","japaneseKana":"ぶたひきにく","japaneseRomaji":"Buta Hikiniku"},{"id":"cabbage-chopped","name":{"zh-TW":"高麗菜末與韭菜 (Minced Cabbage & Garlic Chives)","en":"Finely minced cabbage & nira chives","ja":"キャベツ・ニラ（みじん切り）","ko":"잘게 다진 양배추와 부추","th":"กะหล่ำปลีสับละเอียดและกุยช่าย"},"amount":160,"unitMetric":"g","unitUS":"5.6 oz","isKeyFlavor":true,"japaneseKanji":"キャベツ・ニラ","japaneseKana":"きゃべつ・にら","japaneseRomaji":"Kyabetsu / Nira"},{"id":"gyoza-wrappers","name":{"zh-TW":"日式薄煎餃皮 (Japanese Gyoza Wrappers)","en":"Thin Japanese gyoza wrappers","ja":"餃子の皮（薄め）","ko":"일본식 얇은 교자피","th":"แผ่นแป้งเกี๊ยวซ่าแบบบาง"},"amount":20,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"餃子の皮","japaneseKana":"ぎょうざのかわ","japaneseRomaji":"Gyōza no Kawa"},{"id":"ginger-garlic","name":{"zh-TW":"生薑泥與蒜泥 (Grated Ginger & Garlic)","en":"Grated ginger and garlic","ja":"すりおろし生姜・にんにく","ko":"간 생강과 다진 마늘","th":"ขิงขูดและกระเทียมขูด"},"amount":10,"unitMetric":"g","unitUS":"2 tsp","japaneseKanji":"生姜・にんにく","japaneseKana":"しょうが・にんにく","japaneseRomaji":"Shōga / Ninniku"},{"id":"sesame-oil","name":{"zh-TW":"純黑麻油 (Toasted Sesame Oil)","en":"Toasted Sesame Oil","ja":"ごま油","ko":"참기름","th":"น้ำมันงา"},"amount":15,"unitMetric":"ml","unitUS":"1 tbsp","japaneseKanji":"ごま油","japaneseKana":"ごまあぶら","japaneseRomaji":"Goma Abura"},{"id":"lace-slurry","name":{"zh-TW":"冰花蕾絲粉水 (Flour & Cornstarch Slurry)","en":"Lace Slurry (100ml water + 1 tsp flour + 1 tsp cornstarch)","ja":"羽根用の粉水（水100ml＋薄力粉小さじ1＋片栗粉小さじ1）","ko":"눈꽃 날개용 전분물 (물 100ml + 밀가루 1작은술 + 전분 1작은술)","th":"น้ำแป้งปีกนก (น้ำ 100 มล. + แป้งเค้ก 1 ชช. + แป้งมัน 1 ชช.)"},"amount":100,"unitMetric":"ml","unitUS":"3.4 fl oz","isKeyFlavor":true,"japaneseKanji":"羽根用粉水","japaneseKana":"はねようこなみず","japaneseRomaji":"Hane-yō Konamizu"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"攪打肉餡與包餃 (Mix Filling & Pleat)","en":"Season Filling & Pleat Dumplings","ja":"肉餡を練り、ヒダを寄せて包む","ko":"고기소 치대기 및 주름잡아 빚기","th":"นวดไส้หมูให้เหนียวและจับจีบห่อเกี๊ยว"},"instruction":{"zh-TW":"絞肉加入醬油、清酒、鹽、黑麻油、蒜泥、薑泥，用手同方向快速攪打至泛白起膠。擠乾高麗菜碎的水分，與韭菜一起輕拌入肉餡中。取餃子皮放約 15g 餡料，邊緣抹少許水，折出 4-5 個單側褶子捏緊密封。","en":"Vigorously beat ground pork with seasonings until pale and sticky. Fold in squeezed cabbage and chives. Place 15g filling per wrapper, brush rim with water, and crimp 4-5 pleats on one side.","ja":"豚ひき肉に調味料を加え、粘りが出るまでよく練る。水気を絞ったキャベツとニラをさっくり混ぜ、皮に包んで片側に4〜5つのヒダを寄せて閉じます。","ko":"고기에 양념을 넣고 끈기가 생길 때까지 치댄 후 물기 짠 양배추와 부추를 섞습니다. 만두피에 소를 넣고 한쪽으로만 주름을 잡아 빚습니다.","th":"นวดหมูสับกับเครื่องปรุงจนเหนียวหนึบ ใส่กะหล่ำปลีบีบน้ำและกุยช่าย ห่อแป้งเกี๊ยวจับจีบด้านเดียว 4-5 จีบ"},"durationSeconds":300,"image":"/images/jp/yaki-gyoza-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"排鍋乾煎定型 (Arrange & Sizzle)","en":"Arrange & Sizzle Base","ja":"フライパンに円形に並べ底を焼く","ko":"팬에 둥글게 둘러 담고 밑면 굽기","th":"เรียงเกี๊ยวเป็นวงกลมในกระทะย่างให้ก้นสุก"},"instruction":{"zh-TW":"平底鍋薄抹沙拉油，將煎餃以放射狀圓環（花輪陣）緊密排滿鍋底。開中大火煎 1-2 分鐘，至底面稍微凝固發白。","en":"Brush skillet with oil. Arrange gyoza snugly in a pinwheel circle. Sear on medium-high for 1-2 mins until bases turn opaque.","ja":"フライパンに油を引き、餃子を円形（菊花状）に隙間なく並べます。中火で1〜2分、底が白く固まるまで焼きます。","ko":"팬에 기름을 두르고 만두를 꽃 모양으로 둥글게 둘러 담아 중불에서 1~2분간 밑면을 살짝 굽습니다.","th":"ทาน้ำมัน เรียงเกี๊ยวเป็นรูปดอกไม้ให้ชิดกัน ย่างไฟกลาง 1-2 นาทีจนก้นเริ่มเซ็ตตัว"},"durationSeconds":90,"image":"/images/jp/yaki-gyoza-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"注入冰花水加蓋蒸熟 (Pour Slurry & Steam)","en":"Pour Slurry & Steam-Fry under Lid","ja":"羽根用の粉水を回し入れフタをして蒸し焼き","ko":"전분물을 붓고 뚜껑 덮어 찌기","th":"เทน้ำแป้งปีกนกลงไปและปิดฝาอบ"},"instruction":{"zh-TW":"將調好的冰花蕾絲粉水徹底攪勻，均勻淋入煎餃之間的縫隙中。立刻蓋上鍋蓋，轉中火蒸煎 5 分鐘，利用高溫蒸汽將水餃皮與肉餡完全蒸熟透。","en":"Stir slurry well, then pour all over the gaps between dumplings. Cover tightly with lid immediately. Steam-cook on medium for 5 mins.","ja":"よく混ぜた羽根用粉水を全体に回し入れ、すぐにフタを閉めます。中火で5分間蒸し焼きにし、中までしっかり火を通します。","ko":"전분물을 골고루 부은 즉시 뚜껑을 덮고 중불에서 5분간 수증기로 만두를 쪄냅니다.","th":"คนน้ำแป้งให้ละลาย เทลงตามช่องว่างระหว่างตัวเกี๊ยว ปิดฝาทันที อบไฟกลาง 5 นาทีจนเนื้อหมูสุกทั่ว"},"durationSeconds":300,"image":"/images/jp/yaki-gyoza-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"開蓋收乾與淋麻油 (Open Lid & Crisp Wings)","en":"Remove Lid, Drizzle Sesame Oil & Crisp Wings","ja":"フタを取り水分を飛ばし、ごま油でカリッと仕上げる","ko":"뚜껑 열고 수분 날린 뒤 참기름 둘러 바삭하게","th":"เปิดฝาเคี่ยวน้ำจนแห้ง หยอดน้ำมันงาให้ปีกกรอบ"},"instruction":{"zh-TW":"開蓋，水分此時已大半蒸發。轉中小火讓水分慢慢收乾，直到鍋底殘留的薄麵糊轉化為蜂巢狀網格。沿著鍋邊淋入 1 茶匙黑麻油（香氣四溢並幫助冰花脫模），煎約 1-2 分鐘至整張網翅轉為誘人的淡金黃薄脆狀！","en":"Uncover pan. Let residual moisture evaporate on medium-low until a honeycomb lattice appears. Drizzle 1 tsp sesame oil around edges; fry 1-2 mins until the lace turns crispy amber.","ja":"フタを開け、水分を完全に飛ばします。網目状の羽根が見えてきたら、鍋肌からごま油をひと回し。パリッと黄金色になるまで焼き上げます。","ko":"뚜껑을 열고 수분을 날려 그물망 모양이 생기면 참기름을 둘러 황금빛 바삭한 날개를 만듭니다.","th":"เปิดฝาให้น้ำระเหยจนเกิดรอยตาข่ายลูกไม้ หยอดน้ำมันงารอบขอบ ทอดต่อจนปีกเกล็ดกรอบเป็นสีเหลืองทอง"},"durationSeconds":150,"image":"/images/jp/yaki-gyoza-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"倒扣盛盤完美出鍋 (Flip Plate & Serve)","en":"Flip onto Plate & Serve with Dipping Sauce","ja":"お皿を被せて一気にひっくり返して完成","ko":"접시를 덮어 단숨에 뒤집어 서빙","th":"คว่ำจานลงบนกระทะแล้วพลิกขึ้นจัดเสิร์ฟ"},"instruction":{"zh-TW":"將大圓盤蓋在煎餃上方，一手壓緊盤底、一手握住鍋柄，果斷一口氣倒扣翻轉！整片薄如蟬翼、金黃透光的蕾絲冰花脆皮朝上呈現眼前。調製醬油 + 米醋 + 辣油蘸汁，趁熱咔滋咬下，滿嘴爆汁！","en":"Place a round platter over the skillet, press firmly, and flip in one swift motion! Gyoza rests with crisp golden lace facing up. Serve with soy sauce, rice vinegar, and rayu chili oil.","ja":"フライパンにお皿を被せ、一気に裏返します！見事なレース状の羽根が上に現れます。酢醤油とラー油につけて熱々をお召し上がりください！","ko":"접시를 덮고 단숨에 뒤집으면 환상적인 눈꽃 날개가 위로 펼쳐집니다. 식초 간장과 라유에 찍어 드세요!","th":"คว่ำจานใบใหญ่บนกระทะแล้วพลิกกลับด้านในครั้งเดียว จะได้แผ่นปีกกรอบสีทองหงายขึ้นด้านบน ทานคู่โชยุและน้ำมันพริกเผา"},"durationSeconds":60,"image":"/images/jp/yaki-gyoza-step5.jpg"}],"troubleshooting":[{"id":"trouble-gyoza-1","problem":{"zh-TW":"為什麼冰花無法連成整片，碎碎的不成形？","en":"Why didn’t the lace wings form a contiguous crisp sheet?","ja":"羽根がちぎれてバラバラになり、きれいなレース状になりません。","ko":"눈꽃 날개가 한 장으로 이어지지 않고 부서져요.","th":"ทำไมปีกกรอบไม่เกาะเป็นแผ่นเดียว แต่แตกหักเป็นชิ้นเล็กชิ้นน้อย?"},"cause":{"zh-TW":"粉水比例不對（水太多粉太少），或者在水份未完全乾透前太早起鍋。","en":"Slurry was too diluted, or turned out of the pan before the water had completely evaporated.","ja":"粉の濃度が薄すぎたか、水分が完全に飛ぶ前に火を止めてしまったため。","ko":"전분물이 너무 묽었거나 수분이 다 날아가기 전에 너무 일찍 불을 껐기 때문입니다.","th":"สัดส่วนแป้งน้อยเกินไป หรือปิดไฟก่อนที่น้ำจะระเหยแห้งสนิท"},"solution":{"zh-TW":"嚴格遵守：100ml 水配 1 茶匙低筋麵粉 + 1 茶匙片栗粉，並一定要煎到網狀完全透明金黃才倒扣。","en":"Adhere strictly to 100ml water + 1 tsp flour + 1 tsp potato starch. Cook until the lace is 100% dry and golden.","ja":"水100mlに対し小麦粉・片栗粉各小さじ1を守り、油がパチパチ音を立てるまでしっかり焼き切りましょう。","ko":"물 100ml에 밀가루와 전분 각 1작은술 비율을 지키고, 완전히 바삭해질 때까지 기다리세요.","th":"ใช้อัตราส่วนน้ำ 100 มล. ต่อแป้งสาลีและแป้งมันอย่างละ 1 ชช. และทอดจนแห้งกรอบจริงจึงคว่ำจาน"}}],"proTips":[{"zh-TW":"【低筋麵粉 + 片栗粉雙拼】：純麵粉的冰花偏硬厚，純片栗粉的冰花易破裂。將兩種粉 1:1 混合，即可打造出如蟬翼般輕透薄脆、入口即化的神級蕾絲花翅！","en":"The secret formula: 1:1 ratio of cake flour and potato starch produces ultra-crisp, translucent lace wings.","ja":"【小麦粉と片栗粉のW使い】：小麦粉の香ばしさと片栗粉の透明感・パリパリ感が合わさり、最強の羽根が完成します。","ko":"밀가루와 감자 전분을 1:1로 섞으면 잘 깨지지 않으면서도 가장 가볍고 바삭한 날개가 만들어집니다.","th":"ผสมแป้งเค้กและแป้งมันฝรั่งในอัตรา 1:1 จะได้ปีกกรอบบางใสและกรอบฟินที่สุด"}]},{"country":"jp","id":"ikayaki","slug":"japanese-grilled-ikayaki-squid","title":{"zh-TW":"函館屋台醬烤魷魚姿燒","en":"Hakodate Charred Whole Ikayaki Squid","ja":"函館朝市・屋台風 いかの姿焼き（照り焼きタレ）","ko":"하코다테 스타일 통오징어 간장 버터구이 (이카야키)","th":"อิกายากิ ปลาหมึกย่างซีอิ๊วทั้งตัวสไตล์ฮอกไกโด"},"subtitle":{"zh-TW":"整尾鮮嫩大魷魚劃花刀、甜鹹醬汁濃郁刷烤、炭香四溢","en":"Whole scored squid brushed with sweet tare soy sauce, butter, and shichimi pepper","ja":"香ばしい醤油の焦げた匂い！プリプリ肉厚イカに甘辛タレと七味が絡む屋台の華","ko":"칼집을 넣은 두툼한 통오징어에 단짠 간장 버터 소스를 덧발라 구워낸 최고의 술안주","th":"ปลาหมึกสดตัวโตบั้งลายสวยงาม ย่างเคลือบซอสโชยุเนยหอมกรุ่น โรยพริกเจ็ดรส"},"tagline":{"zh-TW":"日本海濱與夏日祭典人氣王！平底鍋或氣炸鍋 10 分鐘速成居酒屋下酒菜。","en":"A seaside festival favorite! Ready in 10 minutes on a skillet or air fryer.","ja":"海の家や縁日屋台の定番！フライパンや魚焼きグリルで手軽に専門店の味。","ko":"바닷가 축제 포장마차의 인기 메뉴! 프라이팬이나 에어프라이어로 10분 완성.","th":"เมนูยอดนิยมริมทะเลและงานเทศกาล ทำง่ายใน 10 นาทีด้วยกระทะหรือหม้อทอดไร้น้ำมัน"},"heroImage":"/images/jp/ikayaki-hero.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":8,"defaultServings":2,"caloriesPerServing":210,"category":"yakimono","dietaryTags":["classic","pescatarian","halal"],"supportedCookware":["traditional","airFryer","oven"],"culture":{"originRegion":{"zh-TW":"北海道函館市 (Hakodate, Hokkaido)","en":"Hakodate, Hokkaido","ja":"北海道函館市（イカの街）","ko":"홋카이도 하코다테","th":"เมืองฮาโกดาเตะ ฮอกไกโด"},"famousYataiMarkets":[{"zh-TW":"北海道函館朝市海鮮屋台","en":"Hakodate Morning Market Stalls, Hokkaido","ja":"函館朝市海鮮屋台","ko":"하코다테 아침시장 야타이","th":"ตลาดเช้าฮาโกดาเตะ ฮอกไกโด"},{"zh-TW":"東京新宿思出橫丁居酒屋","en":"Shinjuku Omoide Yokocho, Tokyo","ja":"新宿思い出横丁","ko":"신주쿠 오모이데 요코초","th":"ตรอกโอโมอิเดะ ชินจูกุ"}],"historyStory":{"zh-TW":"北海道函館號稱日本「烏賊之都」，津輕海峽捕獲的真烏賊肉質肥美甜脆。祭典屋台與居酒屋將整隻大魷魚在炭火上整尾烤製（姿焼き），刷上濃口醬油與味醂調和的甘鹹醬汁，魷魚受熱捲曲、醬汁在熱鐵板上發出焦糖噴香，是大人下酒無可替代的絕品！","en":"Hakodate is celebrated as Japan’s squid capital. Fresh whole squid is grilled over charcoal and glazed with sweet tare soy sauce until fragrant and tender.","ja":"イカの街・函館発祥。丸ごと一匹豪快に焼き上げる「姿焼き」は、甘辛い醤油ダレが焦げる匂いが食欲をそそる屋台の看板商品です。","ko":"오징어로 유명한 하코다테의 명물로, 통째로 구워 단짠 소스를 발라내는 대표적인 여름 포장마차 요리입니다.","th":"ฮาโกดาเตะเป็นเมืองหลวงแห่งปลาหมึก ย่างทั้งตัวด้วยซอสโชยุหวานกลิ่นหอมชวนน้ำลายสอ"},"japaneseKanji":"いかの姿焼き","japaneseKana":"いかのすがたやき","japaneseRomaji":"Ika no Sugatayaki","audioPronunciationText":"いか焼き","nativeName":"いかの姿焼き","nativePhonetics":"いかのすがたやき"},"ingredients":[{"id":"fresh-squid","name":{"zh-TW":"整尾新鮮透抽或魷魚 (Whole Fresh Squid)","en":"Whole fresh squid, cleaned","ja":"スルメイカ（真イカ）丸ごと1杯","ko":"신선한 통오징어 (손질된 것)","th":"ปลาหมึกกล้วยหรือหมึกศอกสดทั้งตัว"},"amount":1,"unitMetric":"piece","unitUS":"piece (approx 300g)","isKeyFlavor":true,"japaneseKanji":"スルメイカ","japaneseKana":"するめいか","japaneseRomaji":"Surume Ika"},{"id":"shoyu","name":{"zh-TW":"濃口醬油 (Koikuchi Soy Sauce)","en":"Japanese Soy Sauce","ja":"醤油","ko":"진간장","th":"โชยุญี่ปุ่น"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","isKeyFlavor":true,"japaneseKanji":"醤油","japaneseKana":"しょうゆ","japaneseRomaji":"Shōyu"},{"id":"mirin","name":{"zh-TW":"味醂 (Mirin)","en":"Mirin","ja":"みりん","ko":"미림","th":"มิริน"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","japaneseKanji":"本みりん","japaneseKana":"ほんみりん","japaneseRomaji":"Hon-Mirin"},{"id":"sake","name":{"zh-TW":"料理清酒 (Cooking Sake)","en":"Cooking Sake","ja":"清酒","ko":"청주","th":"สาเก"},"amount":15,"unitMetric":"ml","unitUS":"1 tbsp","japaneseKanji":"料理酒","japaneseKana":"りょうりしゅ","japaneseRomaji":"Ryōrishu"},{"id":"sugar","name":{"zh-TW":"砂糖 (Sugar)","en":"Sugar","ja":"砂糖","ko":"설탕","th":"น้ำตาลทราย"},"amount":10,"unitMetric":"g","unitUS":"2 tsp","japaneseKanji":"砂糖","japaneseKana":"さとう","japaneseRomaji":"Satō"},{"id":"butter","name":{"zh-TW":"無鹽奶油 (Butter - Hokkaido style twist)","en":"Unsalted butter (Hokkaido twist)","ja":"有塩または無塩バター","ko":"버터 (홋카이도 스타일)","th":"เนยสดจืด"},"amount":10,"unitMetric":"g","unitUS":"2 tsp","japaneseKanji":"バター","japaneseKana":"ばたー","japaneseRomaji":"Batā"},{"id":"shichimi","name":{"zh-TW":"七味粉與美乃滋 (Shichimi & Kewpie Mayo)","en":"Shichimi Togarashi & Kewpie Mayo for dipping","ja":"七味唐辛子・マヨネーズ","ko":"시치미와 마요네즈","th":"พริกชิจิมิและมายองเนส"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","japaneseKanji":"七味・マヨ","japaneseKana":"しちみ・まよ","japaneseRomaji":"Shichimi / Mayo"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"處理魷魚與劃花刀 (Clean & Score Squid)","en":"Clean Squid & Score Rings","ja":"イカを下処理し、等間隔に切り込みを入れる","ko":"오징어 내장 제거 후 일정한 간격으로 칼집 넣기","th":"ล้างทำความสะอาดปลาหมึกและบั้งลายตามขวาง"},"instruction":{"zh-TW":"將魷魚去除內臟、軟骨與眼睛洗淨，用紙巾徹底擦乾水分。在魷魚身兩側每隔 1.5 公分切入橫向刀口（切斷邊緣但保留中央脊骨不斷，形如排骨梳狀，能防止烤時劇烈捲縮受熱不均）。","en":"Clean squid, remove cartilage and ink sac, pat completely dry. Cut horizontal slits 1.5 cm apart down both sides (leaving the center intact) to prevent curling during searing.","ja":"ワタと軟骨を取り除いて水洗いし、ペーパーで水気をしっかり拭き取る。両脇から1.5cm幅で切り込みを入れます（中央は繋げたまま）。","ko":"내장과 뼈를 제거하고 물기를 닦아냅니다. 몸통 양옆으로 1.5cm 간격으로 칼집을 넣어 구울 때 말리지 않게 합니다.","th":"ควักไส้และกระดองออก ซับน้ำให้แห้งสนิท ใช้มีดบั้งด้านข้างทั้งสองข้างห่างกัน 1.5 ซม. โดยไม่ให้ขาดจากกัน"},"durationSeconds":180,"image":"/images/jp/ikayaki-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"調製甘甜照燒醬汁 (Whisk Teriyaki Glaze)","en":"Mix Tare Sauce","ja":"特製照り焼きダレを混ぜ合わせる","ko":"특제 데리야키 타레 소스 섞기","th":"ผสมซอสทาเระ"},"instruction":{"zh-TW":"在小碗中將醬油、味醂、清酒、砂糖攪拌均勻至糖完全融化備用。","en":"In a small bowl, whisk soy sauce, mirin, sake, and sugar until sugar dissolves completely.","ja":"容器に醤油、みりん、酒、砂糖を合わせ、よく混ぜておきます。","ko":"간장, 미림, 청주, 설탕을 볼에 넣고 설탕이 녹을 때까지 섞어둡니다.","th":"ผสมโชยุ มิริน สาเก และน้ำตาลทรายให้ละลายเข้ากัน"},"durationSeconds":60,"image":"/images/jp/ikayaki-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"高溫初煎至變白微焦 (First Sear)","en":"High-Heat Sear until Opaque","ja":"フライパンで素焼きし、表面に焼き色をつける","ko":"팬에서 양념 없이 1차로 구워 겉면 익히기","th":"ย่างบนกระทะร้อนโดยไม่ใส่ซอสจนเปลี่ยนเป็นสีขาวเกรียม"},"instruction":{"zh-TW":"平底鍋倒入少許沙拉油，中大火加熱至冒微煙。放入整尾魷魚與魷魚觸鬚（暫不刷醬！），用鍋鏟輕壓魚身，煎約 2 分鐘至魷魚變白膨起，翻面再煎 1.5 分鐘。","en":"Heat a lightly oiled skillet over medium-high heat. Lay whole squid and tentacles flat. Press lightly with spatula, searing unglazed for 2 mins until opaque, flip for 1.5 mins.","ja":"フライパンに薄く油を熱し、タレを塗らずにイカを入れます。ヘラで軽く押さえながら中火で2分、裏返して1分半焼きます。","ko":"팬을 달구고 양념 없이 오징어를 올려 뒤집개로 눌러가며 앞뒤로 1~2분씩 노릇하게 굽습니다.","th":"ตั้งกระทะไฟกลางค่อนแรง วางปลาหมึกลงไป ใช้ตะหลิวกดเบาๆ ย่างด้านละ 1.5 - 2 นาทีจนสุกขาว"},"durationSeconds":210,"image":"/images/jp/ikayaki-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"氣炸鍋模式：200°C (390°F) 烤 7 分鐘，第 4 分鐘刷醬翻面","instructionOverride":{"zh-TW":"氣炸鍋鋪烘焙紙，放入魷魚以 200°C 氣炸 4 分鐘，拉出兩面厚刷調味醬汁與奶油，再氣炸 3 分鐘至醬汁冒泡焦香。","en":"Air fry squid plain at 200°C for 4 mins. Generously brush both sides with tare sauce and butter, air fry 3 more mins.","ja":"ノンフライヤー200℃で4分素焼き。取り出してタレとバターをたっぷり塗り、さらに3分香ばしく焼きます。","ko":"에어프라이어 200도에서 4분간 초벌구이 후, 소스와 버터를 듬뿍 발라 3분간 더 굽습니다.","th":"อบในหม้อทอดไร้น้ำมัน 200°C นาน 4 นาที นำออกมาทาซอสและเนย อบต่ออีก 3 นาที"}}]},{"stepNumber":4,"title":{"zh-TW":"下奶油淋醬焦糖化 (Butter Glaze & Caramelize)","en":"Add Butter & Caramelize Tare Sauce","ja":"バターとタレを絡め、照りが出るまで一気に煮詰める","ko":"버터와 타레 소스를 둘러 윤기 나게 졸이기","th":"ใส่เนยและราดซอสเคี่ยวจนเคลือบเงาหอม"},"instruction":{"zh-TW":"轉中火，投入無鹽奶油塊融化，隨即倒入整份調好的照燒醬汁！大火迅速翻動魷魚裹上醬汁，煎約 1-2 分鐘，看醬汁劇烈沸騰濃縮轉化為濃黑油亮的糖蜜狀，關火。","en":"Drop butter into pan, immediately pour in the tare sauce! Baste squid vigorously for 1-2 mins until sauce bubbles into a thick, lustrous mahogany lacquer. Turn off heat.","ja":"バターを投入して溶かし、合わせ調味料を一気に流し込みます。スプーンで煮汁をかけながら強火で1〜2分、照り照りになるまで絡めます。","ko":"버터를 녹이고 소스를 한 번에 부어줍니다. 숟가락으로 끼얹어가며 1~2분간 걸쭉한 갈색 윤기가 돌 때까지 조려줍니다.","th":"ใส่เนยลงไป เทซอสตามลงทันที ตักซอสราดตัวปลาหมึกไปมา 1-2 นาทีจนซอสข้นงวดเคลือบเงา"},"durationSeconds":120,"image":"/images/jp/ikayaki-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"切圈盛盤蘸七味美乃滋 (Plate with Mayo & Shichimi)","en":"Plate with Mayo & Seven Spice","ja":"輪切りにして盛り付け、七味マヨを添える","ko":"먹기 좋게 썰어 접시에 담고 시치미 마요네즈 곁들이기","th":"หั่นเป็นแว่นพอดีคำ เสิร์ฟพร้อมมายองเนสและพริกชิจิมิ"},"instruction":{"zh-TW":"將整尾姿燒魷魚移至砧板切成圈狀排盤，淋上鍋內剩餘濃縮醬汁。盤緣擠上日式美乃滋並撒上七味唐辛子，蘸著酸甜微辣醬料，大口享用無敵海味！","en":"Slice crosswise into rings, drizzle pan drippings over top. Plate with a dollop of Kewpie mayo dusted with shichimi togarashi for the ultimate Izakaya bite.","ja":"食べやすく輪切りにして盛り付け、フライパンに残った濃厚なタレをかけます。七味マヨネーズをつけて召し上がれ！","ko":"도마에서 한입 크기로 썰어 담고 팬에 남은 소스를 끼얹습니다. 시치미 마요네즈에 콕 찍어 드세요!","th":"หั่นเป็นแว่นจัดใส่จาน ราดซอสที่เหลือในกระทะ จิ้มกับมายองเนสผสมพริกชิจิมิ หอมอร่อยเคี้ยวเพลิน"},"durationSeconds":30,"image":"/images/jp/ikayaki-step5.jpg"}],"troubleshooting":[{"id":"trouble-ika-1","problem":{"zh-TW":"魷魚烤出來口感像橡皮筋一樣死硬乾韌？","en":"Why did the squid turn out tough and rubbery like shoe leather?","ja":"イカが硬くなってしまい、ゴムのような食感になってしまいました。","ko":"오징어가 고무처럼 질겨졌어요.","th":"ทำไมปลาหมึกเหนียวแข็งเหมือนยางลบ?"},"cause":{"zh-TW":"煎烤時間過長（超過 5 分鐘），魷魚蛋白質變性脫水。","en":"Overcooked! Squid must be flash-cooked in under 4 minutes total; long heat denatures proteins into tough fibers.","ja":"加熱時間が長すぎたことが原因です。イカは数分で火が通るためスピード勝負です。","ko":"너무 오래 구웠기 때문입니다. 오징어는 3~4분 이내로 빠르게 조리해야 부드럽습니다.","th":"ย่างนานเกินไป ปลาหมึกสุกง่ายมาก หากเกิน 4-5 นาทีเนื้อจะหดตัวและเหนียว"},"solution":{"zh-TW":"先乾煎至轉白即可（兩面各約 1.5 分鐘），下醬汁後大火迅速收汁 1 分鐘立刻起鍋，保持鮮嫩多汁！","en":"Sear plain for only 1.5 mins per side, glaze sauce for 1 min, and remove from heat immediately.","ja":"両面サッと焼き、タレを入れたら強火で短時間で絡めてすぐに火を止めましょう。","ko":"앞뒤로 1.5분씩만 굽고 양념을 넣은 뒤 센 불에서 1분 만에 빠르게 졸여 불을 끄세요.","th":"ย่างด้านละ 1.5 นาทีพอ เมื่อใส่ซอสให้เคี่ยวไฟแรง 1 นาทีแล้วปิดไฟทันที"}}],"proTips":[{"zh-TW":"【加一小塊黃油的北海道魔法】：在最後收汁時投入 10g 奶油，能讓日式醬油的高溫焦香轉化為濃郁奶香的「焦がしバター醤油（焦香奶油醬油）」，風味瞬間升級頂級海鮮居酒屋水準！","en":"Adding a knob of butter at the end creates Japanese \"Kogashi Butter Shoyu\" (brown butter soy sauce), a legendary pairing for grilled seafood.","ja":"【焦がしバター醤油の魔法】：仕上げのバターが醤油の塩角を取り、コクと香ばしさを劇的に格上げします。","ko":"마지막에 넣는 버터 한 조각이 간장과 어우러져 환상적인 ‘버터 간장 불맛’을 만들어냅니다.","th":"ใส่เนยลงไปตอนท้ายจะเกิดเป็นซอส \"เนยโชยุไหม้\" สูตรลับของฮอกไกโดที่หอมล้ำลึก"}]},{"country":"jp","id":"korokke","slug":"japanese-beef-potato-korokke","title":{"zh-TW":"肉汁牛肉馬鈴薯可樂餅","en":"Crispy Japanese Beef Potato Korokke","ja":"お肉屋さんの絶品 牛肉ポテトコロッケ","ko":"정육점 스타일 바삭한 소고기 감자 고로케","th":"โคร็อกเกะ มันฝรั่งบดไส้เนื้อวัวทอดกรอบ"},"subtitle":{"zh-TW":"綿密鬆軟馬鈴薯、焦糖洋蔥香炒牛肉、麵包糠金黃酥脆","en":"Fluffy mashed Russet potatoes with caramelized onion & beef in a crunchy panko shell","ja":"外はサクサク中はホクホク！炒め玉ねぎの甘みとジューシーな牛肉の昔懐かしい下町味","ko":"겉은 바삭 속은 포슬포슬! 볶은 양파의 단맛과 소고기가 가득한 일본 정통 고로케","th":"มันฝรั่งบดเนื้อเนียนนุ่มผสมเนื้อวัวและหอมใหญ่ผัดหวาน คลุกเกล็ดขนมปังทอดกรอบ"},"tagline":{"zh-TW":"日本肉舖（精肉店）門口最難以抗拒的現炸美味！氣炸與油炸皆可完美出爐。","en":"The iconic Japanese butcher shop snack. Air fryer and deep fryer perfected.","ja":"商店街のお肉屋さんの揚げたてを自宅で再現！ノンフライヤーでも絶品の香ばしさ。","ko":"상점가 정육점 앞을 지나칠 수 없게 만드는 갓 튀긴 맛! 에어프라이어로도 손쉽게.","th":"ของว่างยอดนิยมหน้าเขียงเนื้อญี่ปุ่น ทำง่ายด้วยหม้อทอดไร้น้ำมันหรือทอดในกระทะ"},"heroImage":"/images/jp/korokke-hero.jpg","difficulty":"easy","prepTimeMinutes":25,"cookTimeMinutes":10,"defaultServings":4,"caloriesPerServing":260,"category":"agemono","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer","oven"],"culture":{"originRegion":{"zh-TW":"東京都銀座 (Ginza, Tokyo)","en":"Ginza, Tokyo","ja":"東京都中央区銀座","ko":"도쿄 긴자","th":"กินซ่า โตเกียว"},"famousYataiMarkets":[{"zh-TW":"京都錦市場炸可樂餅名店","en":"Nishiki Market Korokke Stalls, Kyoto","ja":"京都錦市場 コロッケ専門店","ko":"교토 니시키 시장 고로케 전문점","th":"ร้านโคร็อกเกะตลาดนิชิกิ เกียวโต"},{"zh-TW":"東京上野阿美橫町大山肉店","en":"Meat Oyama, Ueno Ameyoko, Tokyo","ja":"上野アメ横 肉の大山","ko":"우에노 아메요코 오오야마 정육점","th":"ร้านเนื้อโอยามะ อะเมโยโกะ อุเอโนะ"}],"historyStory":{"zh-TW":"可樂餅源自法國的炸肉丸（Croquette），明治時代傳入日本後，由於當時乳製品高昂，庶民將昂貴的白醬改為鬆軟綿密的蒸馬鈴薯，混入洋蔥碎與炒牛絞肉。大正年間與咖哩飯、炸豬排並列為「大正三大洋食」，成為日本家庭與街頭肉舖最親切的國民小吃！","en":"Adapted from French croquettes during the Meiji era by substituting expensive béchamel with fluffy steamed potatoes and seasoned ground beef. Crowned one of the \"Big Three Yōshoku Dishes\".","ja":"フランス料理のクロケットが明治期に日本風にアレンジされ、安価で栄養満点なジャガイモと牛肉を合わせるスタイルに。大正三大洋食の一つとして親しまれました。","ko":"프랑스 크로켓을 일본식으로 개량하여 감자와 다진 고기를 넣어 만든 다이쇼 시대 3대 양식 중 하나입니다.","th":"ดัดแปลงมาจากโครเกต์ฝรั่งเศสในยุคเมจิ โดยใช้มันฝรั่งบดแทนไวท์ซอสจนกลายเป็นอาหารยอดนิยม"},"japaneseKanji":"ポテトコロッケ","japaneseKana":"ぽてところっけ","japaneseRomaji":"Potato Korokke","audioPronunciationText":"コロッケ","nativeName":"ポテトコロッケ","nativePhonetics":"ぽてところっけ"},"ingredients":[{"id":"potatoes","name":{"zh-TW":"男爵馬鈴薯 (Russet / Danshaku Potatoes)","en":"Starchy Potatoes (Russet or Danshaku)","ja":"男爵じゃがいも","ko":"남작 감자 (포슬포슬한 감자)","th":"มันฝรั่งพันธุ์ดันชาคุ (เนื้อร่วนซุย)"},"amount":400,"unitMetric":"g","unitUS":"14 oz (approx 3 medium)","isKeyFlavor":true,"japaneseKanji":"じゃがいも","japaneseKana":"じゃがいも","japaneseRomaji":"Jagaimo"},{"id":"beef-mince","name":{"zh-TW":"牛絞肉或牛豬混合絞肉 (Ground Beef)","en":"Ground beef (or 70/30 beef-pork blend)","ja":"牛ひき肉または合挽き肉","ko":"소고기 다짐육","th":"เนื้อวัวบดละเอียด"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":true,"japaneseKanji":"牛ひき肉","japaneseKana":"ぎゅうひきにく","japaneseRomaji":"Gyū Hikiniku"},{"id":"onion","name":{"zh-TW":"洋蔥碎 (Finely chopped onion)","en":"Yellow onion, finely minced","ja":"玉ねぎ（みじん切り）","ko":"잘게 다진 양파","th":"หอมใหญ่สับละเอียด"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz (1/2 medium)","japaneseKanji":"玉ねぎ","japaneseKana":"たまねぎ","japaneseRomaji":"Tamanegi"},{"id":"butter","name":{"zh-TW":"無鹽奶油 (Butter)","en":"Butter","ja":"バター","ko":"버터","th":"เนยสดจืด"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","japaneseKanji":"バター","japaneseKana":"ばたー","japaneseRomaji":"Batā"},{"id":"panko","name":{"zh-TW":"日式麵包粉 (Japanese Panko Breadcrumbs)","en":"Japanese Panko breadcrumbs","ja":"パン粉","ko":"빵가루","th":"เกล็ดขนมปังญี่ปุ่น"},"amount":80,"unitMetric":"g","unitUS":"1 cup","isKeyFlavor":true,"japaneseKanji":"パン粉","japaneseKana":"ぱんこ","japaneseRomaji":"Panko"},{"id":"flour-egg","name":{"zh-TW":"中筋麵粉與打散全蛋 (Flour & Egg for breading)","en":"Flour and beaten egg for standard breading","ja":"小麦粉・溶き卵（衣用）","ko":"밀가루와 달걀물","th":"แป้งสาลีและไข่ไก่ตีฟูสำหรับชุบทอด"},"amount":1,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"衣用卵","japaneseKana":"ころもようたまご","japaneseRomaji":"Koromo-yō Tamago"},{"id":"tonkatsu-sauce","name":{"zh-TW":"日式炸豬排/可樂餅濃醬 (Tonkatsu Sauce)","en":"Bull-Dog Tonkatsu / Korokke Sauce","ja":"中濃ソースまたはとんかつソース","ko":"돈가스 / 고로케 소스","th":"ซอสทงคัตสึ"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","isKeyFlavor":true,"japaneseKanji":"とんかつソース","japaneseKana":"とんかつそーす","japaneseRomaji":"Tonkatsu Sōsu"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"蒸透馬鈴薯與粉化搗泥 (Steam & Dry Mash)","en":"Steam & Mash Potatoes Dry","ja":"じゃがいもを蒸して熱いうちにつぶす","ko":"감자를 찌고 뜨거울 때 포슬포슬하게 으깨기","th":"นึ่งมันฝรั่งให้สุกและบดตอนร้อน"},"instruction":{"zh-TW":"馬鈴薯去皮切滾刀塊，放入蒸鍋大火蒸 20 分鐘至筷子能輕易穿透。取出倒入大盆，趁熱用壓泥器壓碎。放在微火上輕輕翻炒 1 分鐘蒸散水氣（粉吹き処理，去除多餘水分是可樂餅外酥內鬆的關鍵！），拌入無鹽奶油與少許鹽。","en":"Peel and cut potatoes into chunks; steam 20 mins until fork-tender. Mash hot in a bowl. Gently stir over low heat for 1 min to steam off excess water. Fold in butter and salt.","ja":"じゃがいもは皮をむいて一口大に切り、竹串が通るまで約20分蒸す。熱いうちにつぶし、鍋肌でサッと加熱して余分な水分を飛ばします（粉ふき）。バターと塩を加えます。","ko":"감자를 20분간 푹 쪄서 뜨거울 때 으깹니다. 약불에서 1분간 저어가며 수분을 날린 뒤 버터와 소금을 섞습니다.","th":"ปอกเปลือกหั่นชิ้น นึ่ง 20 นาทีจนนิ่ม บดให้ละเอียดตอนร้อน ตั้งไฟอ่อนกวนไล่ความชื้น 1 นาที ใส่เนยและเกลือ"},"durationSeconds":1200,"image":"/images/jp/korokke-step1.jpg","crucialTips":{"zh-TW":"「去除水分」是可樂餅下鍋油炸不爆漿裂開的第一法則！趁熱搗碎並利用餘熱蒸發水分。","en":"Moisture is the enemy! Excess steam trapped in the potato will cause the croquette to burst open in the hot oil.","ja":"【水分をしっかり飛ばす】：水分が多いと油の中で膨張して爆発する原因になります。","ko":"수분이 많으면 튀길 때 터집니다! 감자의 수분을 반드시 날려주세요.","th":"ต้องไล่ความชื้นออกจากมันฝรั่งให้หมด ไม่เช่นนั้นเวลาทอดจะระเบิดแตกออก"}},{"stepNumber":2,"title":{"zh-TW":"煸炒焦糖洋蔥與牛絞肉 (Sauté Beef & Onions)","en":"Sauté Minced Beef & Caramelized Onions","ja":"玉ねぎと牛ひき肉を甘辛く炒める","ko":"양파와 소고기를 달콤 짭조름하게 볶기","th":"ผัดหอมใหญ่และเนื้อวัวสับให้หอม"},"instruction":{"zh-TW":"平底鍋熱少許油，下洋蔥末慢炒至透明焦黃帶甜味。加入牛絞肉翻炒至變色散開，以醬油 1 大匙、砂糖 1 茶匙、黑胡椒粉調味，炒至肉汁完全收乾。倒入搗好的馬鈴薯泥中拌勻，放涼冷卻 20 分鐘（冷卻後更容易捏塑成型！）。","en":"Sauté onions until golden and sweet. Add minced beef, cooking until browned. Season with soy sauce, sugar, and black pepper; simmer dry. Mix into potato mash and cool for 20 mins.","ja":"フライパンで玉ねぎを透き通るまで炒め、牛ひき肉を加えて炒め合わせる。醤油、砂糖、胡椒で味付けし、水分を飛ばしてじゃがいもと混ぜ合わせ、冷まします。","ko":"양파를 볶아 단맛을 낸 뒤 소고기를 넣고 간장, 설탕, 후추로 볶습니다. 으깬 감자에 섞어 완전히 식힙니다.","th":"ผัดหอมใหญ่จนหวานหอม ใส่เนื้อวัวบด ปรุงรสด้วยโชยุ น้ำตาล และพริกไทย คลุกกับมันฝรั่งบด พักให้เย็น"},"durationSeconds":480,"image":"/images/jp/korokke-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"捏製橢圓餅與三層裹衣 (Shape & Triple Dredge)","en":"Shape Oval Patties & Flour-Egg-Panko Dredge","ja":"小判形に成形し、小麦粉・卵・パン粉をつける","ko":"타원형으로 빚고 밀가루, 계란물, 빵가루 입히기","th":"ปั้นเป็นทรงรี ชุบแป้ง ไข่ และเกล็ดขนมปัง"},"instruction":{"zh-TW":"雙手抹少許沙拉油，將冷卻的馬鈴薯餡分成 4 等份，雙手來回拋接拍出內部空氣，捏成經典的「小判形」厚橢圓扁餅（厚度約 2 公分）。依序沾上：1. 中筋麵粉（輕拍抖掉多餘粉）-> 2. 打散的蛋液 -> 3. 日式麵包粉（輕壓使麵包粉牢牢貼合）。","en":"Portion into 4 oval patties (~2 cm thick), clapping between hands to expel air pockets. Dredge in flour, beaten egg, then press into panko until coated entirely.","ja":"4等分にして両手でキャッチボールしながら空気を抜き、小判形に成形します。小麦粉→溶き卵→パン粉の順にしっかり衣をつけます。","ko":"반죽을 4등분해 손바닥으로 쳐서 공기를 빼고 도톰한 타원형으로 빚습니다. 밀가루, 달걀물, 빵가루 순으로 꼼꼼히 묻힙니다.","th":"แบ่ง 4 ส่วน โยนไปมาระหว่างมือไล่อากาศ ปั้นเป็นทรงรีแบน ชุบแป้งสาลี ชุบไข่ และคลุกเกล็ดขนมปัง"},"durationSeconds":300,"image":"/images/jp/korokke-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"氣炸鍋模式：200°C (390°F) 氣炸 12 分鐘（建議先將麵包粉乾鍋炒成金黃色再裹上）","instructionOverride":{"zh-TW":"氣炸前先將乾麵包粉放乾鍋炒成誘人的金黃焦色放涼後再裹粉。噴少許油，放入氣炸鍋以 200°C 氣炸 12 分鐘，出爐外殼超酥脆又低卡！","en":"Toast panko in a dry pan until golden before breading for the air fryer. Mist with oil, air fry at 200°C for 12 mins.","ja":"ノンフライヤーの場合、パン粉をあらかじめ乾煎りしてキツネ色にしてからまぶすと、200℃で12分加熱するだけで完璧な揚げ色に。","ko":"빵가루를 마른 팬에 먼저 노릇하게 볶아 묻힌 뒤 오일을 뿌려 200도에서 12분간 에어프라이어로 구워냅니다.","th":"คั่วเกล็ดขนมปังในกระทะให้เหลืองทองก่อนนำมาชุบ ฉีดน้ำมัน อบในหม้อทอดไร้น้ำมัน 200°C นาน 12 นาที"}}]},{"stepNumber":4,"title":{"zh-TW":"高溫炸出金黃脆殼 (Fry to Golden Crunch)","en":"Deep-Fry at 180°C (355°F) for 3 Mins","ja":"180℃の高温で3分！サッとキツネ色に揚げる","ko":"180도 기름에서 3분간 빠르게 튀기기","th":"ทอดในน้ำมันร้อน 180°C นาน 3 นาทีจนกรอบทอง"},"instruction":{"zh-TW":"油溫加熱至 180°C。將可樂餅輕輕滑入熱油中，由於內餡本來就是全熟的，只需油炸 2.5-3 分鐘至麵包粉轉為深金黃酥脆！下鍋前 1 分鐘內絕對不要去用夾子翻動，待外皮硬化後輕輕翻面一次即可起鍋瀝油。","en":"Heat oil to 180°C. Deep-fry gently for 2.5-3 mins. Since the filling is already cooked, focus only on crisping the panko to a rich amber crust. Do not poke for the first minute!","ja":"180℃に熱した油に入れ、2分半〜3分揚げます（中身は火が通っているので衣だけキツネ色になればOK）。最初の1分は触らないのがコツ。","ko":"180도 기름에 넣고 2분 30초~3분간 튀깁니다 (속은 이미 익었으므로 겉면만 노릇해지면 완성). 처음 1분간은 건드리지 마세요.","th":"ทอดในน้ำมัน 180°C นาน 2.5-3 นาที เนื่องจากไส้สุกแล้ว ทอดแค่ให้เกล็ดขนมปังกรอบทอง ห้ามคนใน 1 นาทีแรก"},"durationSeconds":180,"image":"/images/jp/korokke-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"淋豬排醬大口享用 (Serve with Tonkatsu Sauce)","en":"Plate with Cabbage & Tonkatsu Sauce","ja":"千切りキャベツを添え、ソースをかけて熱々をいただく","ko":"양배추 채와 돈가스 소스를 곁들여 완성","th":"เสิร์ฟพร้อมกะหล่ำปลีซอยและราดซอสทงคัตสึ"},"instruction":{"zh-TW":"可樂餅瀝乾油份擺盤，旁邊搭配細脆的冰鎮高麗菜絲。豪邁淋上酸甜濃郁的日式中濃炸豬排醬（Tonkatsu Sauce），咔滋咬破熱騰騰的酥脆外殼，享受融化在舌尖的綿密甘甜牛肉馬鈴薯餡！","en":"Drain on a rack. Serve with finely shredded chilled cabbage and a generous drizzle of savory-sweet Tonkatsu sauce. Crunch into the golden shell and savor the comforting melt-in-mouth filling!","ja":"油を切ってお皿に盛り、千切りキャベツを添えてとんかつソースをたっぷり回しかけます。サクッと頬張る幸せをどうぞ！","ko":"바삭하게 기름을 뺀 뒤 양배추 채와 돈가스 소스를 곁들입니다. 바삭한 튀김옷과 부드러운 감자의 환상적인 조화!","th":"ตักสะเด็ดน้ำมัน เสิร์ฟคู่กะหล่ำปลีฝอย ราดซอสทงคัตสึเข้มข้น กัดคำแรกสัมผัสความกรอบนอกนุ่มละมุนใน"},"durationSeconds":30,"image":"/images/jp/korokke-step5.jpg"}],"troubleshooting":[{"id":"trouble-koro-1","problem":{"zh-TW":"可樂餅在油鍋中突然爆漿裂開，油煙四濺？","en":"Why did the croquettes burst open and crack inside the fryer?","ja":"揚げている最中に破裂して中身が油に飛び散ってしまいました。","ko":"튀기는 도중에 터져서 속이 밖으로 흘러나왔어요.","th":"ทำไมเวลาทอดแล้วโคร็อกเกะระเบิดแตก ไส้ทะลักออกมาในกระทะ?"},"cause":{"zh-TW":"馬鈴薯水分太多、捏餅時內部留有大氣泡，或者是低溫炸太久導致內部蒸氣過度膨脹。","en":"Excess moisture in potatoes, trapped air inside patties, or fried too long at low temperature causing steam explosion.","ja":"ポテトの水分が多かった、成形時の空気抜き不足、または低すぎる温度で長時間揚げすぎたため。","ko":"감자 수분 과다, 공기 빼기 부족, 또는 낮은 온도에서 오래 튀겨 내부 수증기가 폭발했기 때문입니다.","th":"มันฝรั่งมีความชื้นมากเกินไป ไม่ได้ตบไล่อากาศตอนปั้น หรือใช้น้ำมันไม่ร้อนพอทำให้ไอน้ำดันแตก"},"solution":{"zh-TW":"務必先「粉吹き（乾炒散除水氣）」，捏餅時雙手用力拍擊排空空氣，並在 180°C 高溫下於 3 分鐘內完成油炸！","en":"Dry mash potatoes over heat, firmly slap patties between hands to expel air, and fry in hot 180°C oil for under 3 mins.","ja":"粉吹きで水分を飛ばし、手でパンパンと叩いて空気を抜き、180℃の油でサッと3分以内で揚げましょう。","ko":"수분을 충분히 날리고 손뼉을 치듯 공기를 뺀 뒤, 180도 고온에서 3분 이내로 빠르게 튀겨내세요.","th":"กวนไล่ความชื้นก่อนปั้น ตบไล่อากาศระหว่างมือให้แน่น และทอดไฟแรง 180°C ไม่เกิน 3 นาที"}}],"proTips":[{"zh-TW":"【成型後先冷藏 15 分鐘】：將裹好麵包粉的可樂餅生胚放入冰箱冷藏 15-20 分鐘，能讓麵包粉與蛋液徹底咬合、餅體緊實冷卻，下熱油鍋時外殼立刻鎖住定型，保證零爆裂！","en":"Chill breaded patties in the fridge for 15 mins before frying. Cold interior meets scorching oil = zero bursting guaranteed.","ja":"【揚げる前に冷やす】：衣をつけた後、冷蔵庫で15分冷やすと衣がしっかり密着し、破裂を劇的に防げます。","ko":"튀기기 전에 냉장고에 15분간 넣어두면 겉면이 단단해져 뜨거운 기름에 넣어도 절대 터지지 않습니다.","th":"นำเข้าแช่เย็น 15 นาทีก่อนทอด แป้งจะเซ็ตตัวแน่น ทอดแล้วไม่แตกแน่นอน"}]},{"country":"jp","id":"uji-kakigori","slug":"uji-kintoki-matcha-kakigori","title":{"zh-TW":"京都宇治金時抹茶刨冰","en":"Kyoto Uji Kintoki Matcha Shaved Ice","ja":"京都発祥 極上宇治金時かき氷（白玉・練乳添え）","ko":"교토 정통 우지킨토키 말차 빙수","th":"อุจิคินโทกิ น้ำแข็งไสมัทฉะและถั่วแดงสไตล์เกียวโต"},"subtitle":{"zh-TW":"綿密羽毛雪花冰、石臼宇治濃抹茶蜜、軟糯白玉糰子與蜜紅豆","en":"Feather-light shaved snow drenched in ceremonial Uji matcha syrup, sweet azuki & chewy mochi","ja":"ふわふわ淡雪氷に濃厚な宇治抹茶蜜がたっぷり！もちもち白玉と北海道小豆の至高のハーモニー","ko":"눈처럼 부드러운 빙수에 진한 우지 말차 시럽, 쫄깃한 백옥 경단과 통단팥","th":"เกล็ดน้ำแข็งไสนุ่มฟูราดไซรัปมัทฉะอุจิเข้มข้น โปะถั่วแดงกวนและโมจิชิราทามะเหนียวนุ่ม"},"tagline":{"zh-TW":"日本夏日祭典與百年喫茶店的不敗經典，一口沁涼洗淨夏日暑氣！","en":"The iconic Japanese summer dessert from ancient Kyoto tea houses, ready in minutes.","ja":"京都の甘味処の看板メニュー！濃厚な自家製抹茶蜜の作り方を伝授。","ko":"백년 전통 교토 찻집의 그 맛! 진한 수제 말차 시럽으로 완성하는 여름의 맛.","th":"ขนมหวานยอดฮิตในงานเทศกาลฤดูร้อนและร้านน้ำชาเกียวโต ดับร้อนได้สดชื่นถึงใจ"},"heroImage":"/images/jp/uji-kakigori-hero.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":5,"defaultServings":2,"caloriesPerServing":220,"category":"sweets","dietaryTags":["classic","vegetarian"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"京都府宇治市 (Uji, Kyoto)","en":"Uji, Kyoto Prefecture","ja":"京都府宇治市","ko":"교토부 우지시","th":"เมืองอุจิ เกียวโต"},"famousYataiMarkets":[{"zh-TW":"京都宇治中村藤吉・伊藤久右衛門老舖","en":"Nakamura Tokichi & Itohkyuemon, Uji","ja":"宇治 中村藤吉本店・伊藤久右衛門","ko":"교토 우지 나카무라 토키치 본점","th":"ร้านชาโบราณอุจิ เกียวโต"},{"zh-TW":"東京淺草寺夏祭屋台","en":"Asakusa Summer Festival Stalls, Tokyo","ja":"浅草縁日かき氷屋台","ko":"아사쿠사 축제 빙수 야타이","th":"แผงลอยน้ำแข็งไสเทศกาลอาซากุสะ"}],"historyStory":{"zh-TW":"「宇治（Uji）」代表頂級宇治抹茶，「金時（Kintoki）」源於民間傳說英雄坂田金時（金太郎）臉紅的意象，借代為甜紅豆粒。「宇治金時」將茶道級的高苦甜抹茶糖漿淋在晶瑩冰晶上，冷熱茶甜交融，是日本平安時代宮廷冰室文化與茶道美學結合的極致巔峰！","en":"\"Uji\" represents the famous Kyoto tea region, and \"Kintoki\" refers to the sweet red beans. Dating back to Heian court ice chambers, this dessert is the pinnacle of Japanese confectionery art.","ja":"「宇治」は高級抹茶、「金時」は金太郎（坂田金時）の赤い顔に見立てた小豆のこと。平安貴族の氷室の贅沢が、現代に受け継がれた夏の風物詩。","ko":"‘우지’는 최고급 말차를, ‘킨토키’는 붉은 단팥을 의미합니다. 헤이안 귀족들이 즐기던 얼음 문화가 대중화된 여름 별미.","th":"\"อุจิ\" คือมัทฉะเกรดดี ส่วน \"คินโทกิ\" หมายถึงถั่วแดงกวน เป็นสุดยอดขนมหวานดับร้อนของญี่ปุ่น"},"japaneseKanji":"宇治金時かき氷","japaneseKana":"うじきんときかきごおり","japaneseRomaji":"Uji Kintoki Kakigōri","audioPronunciationText":"宇治金時","nativeName":"宇治金時かき氷","nativePhonetics":"うじきんときかきごおり"},"ingredients":[{"id":"pure-ice","name":{"zh-TW":"純淨水冰塊 (Pure Ice Block or Cubes)","en":"Pure clear water ice blocks","ja":"純氷（かき氷用ブロック氷または角氷）","ko":"단단하고 투명한 얼음","th":"น้ำแข็งก้อนใสบริสุทธิ์"},"amount":350,"unitMetric":"g","unitUS":"12 oz","isKeyFlavor":true,"japaneseKanji":"氷","japaneseKana":"こおり","japaneseRomaji":"Kōri"},{"id":"matcha-powder","name":{"zh-TW":"京都宇治抹茶粉 (Ceremonial Uji Matcha Powder)","en":"Ceremonial grade Uji Matcha powder","ja":"京都宇治高級抹茶パウダー","ko":"교토 우지 고급 말차 가루","th":"ผงมัทฉะอุจิแท้เกรดพรีเมียม"},"amount":15,"unitMetric":"g","unitUS":"2 tbsp","isKeyFlavor":true,"japaneseKanji":"抹茶","japaneseKana":"まっちゃ","japaneseRomaji":"Matcha"},{"id":"sugar","name":{"zh-TW":"細砂糖 (Caster Sugar)","en":"Sugar for syrup","ja":"上白糖またはグラニュー糖","ko":"설탕","th":"น้ำตาลทราย"},"amount":50,"unitMetric":"g","unitUS":"3.5 tbsp","japaneseKanji":"砂糖","japaneseKana":"さとう","japaneseRomaji":"Satō"},{"id":"hot-water","name":{"zh-TW":"熱水 (Hot Water 80°C)","en":"Hot water (80°C / 176°F)","ja":"お湯（80℃）","ko":"따뜻한 물 (80도)","th":"น้ำร้อน 80°C"},"amount":60,"unitMetric":"ml","unitUS":"1/4 cup","japaneseKanji":"お湯","japaneseKana":"おゆ","japaneseRomaji":"Oyu"},{"id":"anko","name":{"zh-TW":"北海道十勝蜜紅豆粒餡 (Sweet Azuki Beans)","en":"Hokkaido Tokachi Sweet Azuki Beans","ja":"北海道十勝産 粒あん","ko":"통단팥 앙금","th":"ถั่วแดงกวนฮอกไกโด"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"japaneseKanji":"粒あん","japaneseKana":"つぶあん","japaneseRomaji":"Tsubuan"},{"id":"shiratama","name":{"zh-TW":"手作白玉糰子 (Cooked Shiratama Mochi)","en":"Cooked Shiratama mochi pearls","ja":"白玉団子","ko":"시라타마 찹쌀 경단","th":"ลูกชิ้นโมจิชิราทามะ"},"amount":6,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"白玉団子","japaneseKana":"しらたまだんご","japaneseRomaji":"Shiratama Dango"},{"id":"condensed-milk","name":{"zh-TW":"特濃煉乳 (Sweetened Condensed Milk)","en":"Sweetened Condensed Milk","ja":"加糖練乳（コンデンスミルク）","ko":"연유","th":"นมข้นหวาน"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","isKeyFlavor":true,"japaneseKanji":"練乳","japaneseKana":"れんにゅう","japaneseRomaji":"Rennyū"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"現刷調製極濃抹茶蜜 (Whisk Fresh Matcha Syrup)","en":"Whisk Thick Matcha Syrup","ja":"抹茶と砂糖をお湯で溶き、濃厚な抹茶蜜を作る","ko":"말차가루와 설탕을 따뜻한 물에 개어 진한 시럽 만들기","th":"ตีผงมัทฉะ น้ำตาล และน้ำร้อนเป็นไซรัปเข้มข้น"},"instruction":{"zh-TW":"在茶碗中混合抹茶粉與細砂糖。注入 80°C 熱水，用竹筌（或小打蛋器）快速在碗底刷拂約 1 分鐘，直到粉末完全融解、無任何微小結塊，呈現翠綠絲滑的濃抹茶糖漿，放入冰箱冷藏降溫至冰涼。","en":"Whisk matcha powder and sugar in a tea bowl. Pour in 80°C hot water, whisking vigorously with a chasen for 1 min until completely lump-free. Chill in the fridge until ice cold.","ja":"抹茶と砂糖を茶碗に入れ、80℃のお湯を注ぎます。茶筅でダマがなくなるまでよく泡立て、滑らかな抹茶シロップを作り冷蔵庫でしっかり冷やします。","ko":"말차가루와 설탕을 섞고 따뜻한 물을 부어 차센으로 멍울 없이 곱게 갠 뒤 냉장고에서 차갑게 식힙니다.","th":"ผสมผงมัทฉะกับน้ำตาลในถ้วย เทน้ำร้อน 80°C ลงไป ใช้แปรงชงชาตีให้ละลายเนียน แช่เย็นจนเย็นเจี๊ยบ"},"durationSeconds":180,"image":"/images/jp/uji-kakigori-step1.jpg","crucialTips":{"zh-TW":"抹茶蜜「必須徹底冷卻」才能淋在冰上！熱的抹茶蜜淋上去會讓雪花冰瞬間融化成一灘綠水。","en":"Syrup MUST be cold! Pouring warm syrup immediately collapses fluffy shaved ice into a puddle of water.","ja":"【シロップは必ず冷やす】：温かいままかけると氷が一瞬で溶けてしまいます。しっかり冷やすのが鉄則。","ko":"시럽을 반드시 차갑게 식힌 후 뿌려야 눈꽃 얼음이 녹지 않고 유지됩니다.","th":"น้ำเชื่อมมัทฉะต้องแช่ให้เย็นจัดก่อนราด มิฉะนั้นน้ำแข็งจะละลายในพริบตา"}},{"stepNumber":2,"title":{"zh-TW":"刨削綿密羽毛雪花冰 (Shave Fluffy Snow)","en":"Shave Fluffy Ice Mountain","ja":"氷を薄く削り、ふわふわの氷の山を作る","ko":"얼음을 얇게 갈아 눈꽃 빙수 산 만들기","th":"ไสน้ำแข็งให้เป็นปุยหิมะบางเบาทรงภูเขา"},"instruction":{"zh-TW":"將冰塊從冷凍庫取出在室溫回溫 3-5 分鐘（讓冰塊表面轉為透明微光，是削出如鵝毛般綿密羽冰的秘訣）。放入刨冰機中，調至最細刀片，在深碗中刨出高聳鬆軟的白雪冰山。","en":"Rest ice at room temp for 3-5 mins until sweating slightly (the secret to ultra-fine feathery ribbons). Shave onto a bowl to form a fluffy snow peak.","ja":"氷を冷凍庫から出して少し常温で汗をかかせる（透明になるまで置くのがフワフワの秘訣）。細かく削って山高に盛り付けます。","ko":"얼음을 상온에 3~5분 두어 살짝 녹인 뒤(투명해질 때), 빙수기로 얇게 갈아 눈처럼 소복하게 담습니다.","th":"นำน้ำแข็งออกมาพักอุณหภูมิห้อง 3-5 นาทีจนเริ่มใส ปรับใบมีดให้ละเอียดที่สุดแล้วไสเป็นทรงภูเขาฟูสวยงาม"},"durationSeconds":120,"image":"/images/jp/uji-kakigori-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"淋浸翡翠抹茶蜜 (Drizzle Matcha Syrup)","en":"Drench in Emerald Matcha Glaze","ja":"冷えた濃厚な宇治抹茶蜜をまんべんなく回しかける","ko":"차갑게 식힌 우지 말차 시럽 골고루 끼얹기","th":"ราดไซรัปมัทฉะสีเขียวมรกตให้ทั่ว"},"instruction":{"zh-TW":"先將 1/2 的冰涼抹茶蜜均勻澆淋在雪花冰球四周。再續刨薄薄一層白雪冰覆蓋，隨後將剩下的抹茶蜜全部淋上，讓冰體內外都滲透著濃郁的翠綠茶香。","en":"Drizzle half of chilled matcha syrup over the ice. Shave a light extra layer on top, then pour remaining syrup so the entire core is infused with rich green tea.","ja":"シロップの半分を回しかけ、上から少し氷を削り足して残りのシロップをかけます。中まで緑色に染み込ませるのがコツ。","ko":"시럽 절반을 먼저 뿌리고 얼음을 살짝 더 올린 뒤 남은 시럽을 골고루 끼얹어 속까지 말차 향이 배게 합니다.","th":"ราดไซรัปครึ่งหนึ่ง ไสน้ำแข็งทับอีกชั้น แล้วราดไซรัปที่เหลือให้ชุ่มฉ่ำถึงด้านใน"},"durationSeconds":60,"image":"/images/jp/uji-kakigori-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"點綴金時紅豆與白玉 (Crown with Azuki & Shiratama)","en":"Garnish with Sweet Azuki, Mochi & Condensed Milk","ja":"粒あんと白玉を添え、仕上げに練乳をとろりとかける","ko":"통단팥과 백옥 경단을 올리고 연유 뿌려 완성","th":"วางถั่วแดงกวน โมจิชิราทามะ และราดนมข้นหวาน"},"instruction":{"zh-TW":"在冰山側邊挖出小凹槽，輕輕放上一大球軟糯香甜的十勝蜜紅豆，圍繞擺上 4-6 顆現煮冰鎮白玉糰子。最後由頂部淋下一圈醇香白潤的煉乳，冷冽甘醇、苦甜平衡，大口挖下享受極致和風夏天！","en":"Nestle a generous scoop of sweet azuki red beans on the side, arrange chewy shiratama mochi around the bowl, and crown with a swirl of rich condensed milk. Dive in with a spoon!","ja":"氷の脇に粒あんをこんもり乗せ、白玉を並べます。最後に頂上から練乳をたっぷり回しかけて完成！","ko":"빙수 옆에 달콤한 통단팥을 듬뿍 얹고 쫄깃한 시라타마를 곁들인 뒤, 연유를 듬뿍 뿌려 완성합니다.","th":"วางถั่วแดงกวนลูกโตไว้ข้างชาม เรียงโมจิชิราทามะรอบๆ แล้วราดนมข้นหวานด้านบนสุด ทานได้ทันที"},"durationSeconds":60,"image":"/images/jp/uji-kakigori-step4.jpg"}],"troubleshooting":[{"id":"trouble-kaki-1","problem":{"zh-TW":"削出來的冰塊粗糙如碎碎冰渣，而不是柔軟的雪花？","en":"Why is the shaved ice crunchy and gritty like ice cubes instead of snow?","ja":"氷がガリガリと粗く、ふわふわの羽のようになりません。","ko":"얼음이 부드럽지 않고 서걱거리며 거칠게 갈려요.","th":"ทำไมน้ำแข็งไสออกมาเป็นเกล็ดหยาบกรุบกรอบ ไม่เป็นปุยหิมะนุ่มฟู?"},"cause":{"zh-TW":"冰塊剛從 -18°C 冰箱拿出直接削太硬脆，或者刀片調得太凸出。","en":"Ice was frozen too hard directly from freezer; it must sweat at room temperature before shaving.","ja":"冷凍庫から出したばかりの冷たすぎる氷を削ったため。表面が少し溶けて透明になるまで待ちます。","ko":"냉동실에서 꺼내자마자 너무 꽁꽁 얼어붙은 상태에서 갈았기 때문입니다.","th":"ใช้น้ำแข็งที่เพิ่งเอาออกจากช่องฟรีซแข็งจัด หรือปรับใบมีดหนาเกินไป"},"solution":{"zh-TW":"將冰塊放常溫靜置 3-5 分鐘，表面摸起來滑溜全透明才上機削，並把刀刃微調至最薄！","en":"Let ice sit at room temp until wet and glossy before shaving with the thinnest blade setting.","ja":"氷の表面が濡れて透明になるまで常温に置き、刃の出し具合を極力薄く調整しましょう。","ko":"상온에 잠시 두어 겉면에 물방울이 맺히고 투명해졌을 때 가장 얇은 날로 가세요.","th":"พักน้ำแข็งให้ละลายที่ผิวนอกจนใสลื่น และปรับใบมีดให้บางที่สุดก่อนไส"}}],"proTips":[{"zh-TW":"【加少許糖水冷凍冰塊】：如果在製作刨冰的純水中加入 2-3% 的砂糖（如 500ml 水加 10g 糖）溶解後再冷凍，冰塊結晶會大幅變細，削出來能達到專業喫茶店「入口即化」的極品羽毛口感！","en":"Freeze ice with 2% sugar (10g sugar per 500ml water). The sugar disrupts rigid ice crystal lattice, yielding impossibly fine snow ribbons.","ja":"【砂糖水で氷を作る裏技】：水500mlに砂糖大さじ1を溶かして凍らせると、氷の結晶が細かくなり、プロの専門店のふわとろ氷になります！","ko":"얼음 얼릴 때 물 500ml당 설탕 1큰술을 녹여 얼리면 빙수 전문점의 부드러운 눈꽃 얼음이 만들어집니다.","th":"ใส่น้ำตาล 1 ช้อนโต๊ะต่อน้ำ 500 มล. ก่อนนำไปแช่แข็ง จะได้ผลึกน้ำแข็งที่ละเอียดนุ่มละลายในปาก"}]},{"country":"jp","id":"dorayaki","slug":"classic-honey-dorayaki","title":{"zh-TW":"經典蜂蜜紅豆銅鑼燒","en":"Classic Honey Red Bean Dorayaki","ja":"浅草・上野老舗の味 黄金どら焼き","ko":"클래식 꿀 통단팥 도라야키","th":"โดรายากิ ขนมแป้งแพนเค้กสอดไส้ถั่วแดงฮอกไกโด"},"subtitle":{"zh-TW":"蜂蜜味醂黃金鬆餅皮、深棕如鏡、夾裹綿密香甜十勝粒餡","en":"Honey & mirin infused golden pancakes sandwiching luscious sweet azuki red bean paste","ja":"蜂蜜とみりんのしっとり黄金色の生地で、上品な粒あんをたっぷり挟んだ国民的銘菓","ko":"꿀과 미림의 은은한 단맛이 밴 촉촉한 팬케이크 사이에 통단팥이 가득","th":"แป้งแพนเค้กเนื้อนุ่มฉ่ำน้ำผึ้งและมิริน ประกบไส้ถั่วแดงกวนหวานละมุน"},"tagline":{"zh-TW":"哆啦A夢最愛、日本三大銅鑼燒老舖配方！平底鍋零毛孔均勻上色技法。","en":"Doraemon’s beloved confection! Master the pore-free, mirror-smooth pancake technique.","ja":"ドラえもんの大好物！フライパンで油を引かずに焼く「つるピカ」焼き色の極意。","ko":"도라에몽의 최애 간식! 기름 없이 매끄럽게 구워내는 황금빛 도라야키.","th":"ขนมโปรดของโดราเอมอน เคล็ดลับทอดบนกระทะให้ผิวเนียนสวยไร้รูพรุน"},"heroImage":"/images/jp/dorayaki-hero.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":10,"defaultServings":4,"caloriesPerServing":205,"category":"sweets","dietaryTags":["classic","vegetarian"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"東京都上野・淺草 (Ueno/Asakusa, Tokyo)","en":"Ueno & Asakusa, Tokyo","ja":"東京都台東区上野（うさぎや）および浅草","ko":"도쿄 우에노 및 아사쿠사","th":"ย่านอุเอโนะและอาซากุสะ โตเกียว"},"famousYataiMarkets":[{"zh-TW":"上野百年老舖兔屋（うさぎや）","en":"Usagiya, Ueno, Tokyo","ja":"上野 うさぎや","ko":"우에노 우사기야 본점","th":"ร้านอุซางิยะ อุเอโนะ"},{"zh-TW":"淺草雷門龜十（亀十）","en":"Kameju, Asakusa, Tokyo","ja":"浅草 亀十","ko":"아사쿠사 카메쥬","th":"ร้านคาเมะจู อาซากุสะ"}],"historyStory":{"zh-TW":"相傳平安時代末期名將武藏坊弁慶在受傷養傷時，將麵糊倒在隨身銅鑼（Dora）上煎成圓餅，包裹紅豆餡感謝收留他的農家，故名「銅鑼燒」。大正三年（1914年）上野名店「兔屋」改為現代的「雙片夾餡」形式，從此成為全日本最具代表性的和菓子！","en":"Legend says the warrior Benkei baked cakes on a copper gong (dora) after battle. In 1914, Tokyo’s Usagiya innovated the modern double-pancake sandwich format.","ja":"弁慶が治療を受けた農家で銅鑼（どら）を使って丸く焼いたのが名前の由来。大正3年に上野「うさぎや」が2枚の生地で挟む現在の形を完成させました。","ko":"무사 벤케이가 징(도라) 위에 반죽을 구워 먹은 것에서 유래하여, 1914년 우에노 우사기야에서 현재의 샌드 형태로 완성했습니다.","th":"ตำนานเล่าว่านักรบเบงเคย์ใช้ฆ้องทองแดงย่างแป้ง ต่อมาร้านอุซางิยะในโตเกียวได้พัฒนาเป็นทรงแซนด์วิชในปี 1914"},"japaneseKanji":"どら焼き","japaneseKana":"どらやき","japaneseRomaji":"Dorayaki","audioPronunciationText":"どら焼き","nativeName":"どら焼き","nativePhonetics":"どらやき"},"ingredients":[{"id":"anko","name":{"zh-TW":"十勝甜紅豆餡 (Japanese Sweet Red Bean Paste)","en":"Japanese Sweet Red Bean Paste (Tsubuan)","ja":"北海道産 粒あん","ko":"통단팥 앙금","th":"ถั่วแดงกวนฮอกไกโด"},"amount":160,"unitMetric":"g","unitUS":"5.6 oz","isKeyFlavor":true,"japaneseKanji":"粒あん","japaneseKana":"つぶあん","japaneseRomaji":"Tsubuan"},{"id":"eggs","name":{"zh-TW":"全蛋 (Eggs)","en":"Large eggs","ja":"鶏卵","ko":"달걀","th":"ไข่ไก่"},"amount":2,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"卵","japaneseKana":"たまご","japaneseRomaji":"Tamago"},{"id":"honey","name":{"zh-TW":"純蜂蜜 (Pure Honey)","en":"Honey (crucial for golden crust & moisture)","ja":"蜂蜜","ko":"꿀","th":"น้ำผึ้งแท้"},"amount":20,"unitMetric":"g","unitUS":"1 tbsp","isKeyFlavor":true,"japaneseKanji":"蜂蜜","japaneseKana":"はちみつ","japaneseRomaji":"Hachimitsu"},{"id":"mirin","name":{"zh-TW":"味醂 (Hon Mirin)","en":"Hon-Mirin (adds shine & depth)","ja":"本みりん","ko":"미림","th":"มิริน"},"amount":10,"unitMetric":"ml","unitUS":"2 tsp","japaneseKanji":"本みりん","japaneseKana":"ほんみりん","japaneseRomaji":"Hon-Mirin"},{"id":"sugar","name":{"zh-TW":"細砂糖 (Caster Sugar)","en":"Sugar","ja":"上白糖","ko":"설탕","th":"น้ำตาลทราย"},"amount":50,"unitMetric":"g","unitUS":"3.5 tbsp","japaneseKanji":"砂糖","japaneseKana":"さとう","japaneseRomaji":"Satō"},{"id":"flour","name":{"zh-TW":"低筋麵粉 (Cake Flour)","en":"Cake Flour","ja":"薄力粉","ko":"박력분","th":"แป้งเค้ก"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","japaneseKanji":"薄力粉","japaneseKana":"はくりきこ","japaneseRomaji":"Hakurikiko"},{"id":"baking-soda-water","name":{"zh-TW":"小蘇打粉與水 (Baking Soda & Water)","en":"1/2 tsp baking soda dissolved in 1 tbsp water","ja":"重曹（小さじ1/2を水大さじ1で溶く）","ko":"베이킹소다 1/2작은술 + 물 1큰술","th":"เบกกิ้งโซดา 1/2 ชช. ละลายน้ำ 1 ชต."},"amount":15,"unitMetric":"ml","unitUS":"1 tbsp","isKeyFlavor":true,"japaneseKanji":"重曹水","japaneseKana":"じゅうそうすい","japaneseRomaji":"Jūsō Sui"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"打發蛋糖與蜂蜜味醂 (Whisk Eggs & Honey)","en":"Whisk Eggs, Sugar, Honey & Mirin","ja":"卵、砂糖、蜂蜜、みりんを白っぽくなるまで泡立てる","ko":"달걀, 설탕, 꿀, 미림을 뽀얗게 거품 내기","th":"ตีไข่ น้ำตาล น้ำผึ้ง และมิรินจนฟูเนียนสีอ่อน"},"instruction":{"zh-TW":"在碗中打入雞蛋與砂糖，用打蛋器打至稍微泛白膨鬆。加入蜂蜜、味醂與溶化的小蘇打水攪勻。篩入低筋麵粉，以刮刀由下往上切拌至無乾粉顆粒，覆蓋保鮮膜冷藏靜置 15 分鐘鬆弛消泡。","en":"Beat eggs and sugar until pale and frothy. Whisk in honey, mirin, and baking soda slurry. Sift in cake flour, gently fold until smooth. Rest in fridge for 15 mins.","ja":"ボウルに卵と砂糖を入れ、白っぽくもったりするまで泡立てます。蜂蜜、みりん、水で溶いた重曹を加えます。薄力粉をふるい入れてサックリ混ぜ、15分休ませます。","ko":"볼에 달걀과 설탕을 뽀얗게 거품을 낸 뒤 꿀, 미림, 베이킹소다 녹인 물을 섞습니다. 밀가루를 체 쳐 넣고 가볍게 섞어 15분간 휴지합니다.","th":"ตีไข่และน้ำตาลจนเป็นครีมฟูสีอ่อน ใส่น้ำผึ้ง มิริน และเบกกิ้งโซดาละลายน้ำ ร่อนแป้งเค้กลงไป ตะล่อมให้เข้ากัน พักไว้ 15 นาที"},"durationSeconds":300,"image":"/images/jp/dorayaki-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"調整濃度至絲滑飄帶 (Adjust Consistency)","en":"Adjust Batter Consistency with Water","ja":"水（小さじ1〜2）で生地のとろみを調整する","ko":"물 1~2작은술로 반죽 농도 조절하기","th":"เติมน้ำ 1-2 ช้อนชาปรับความข้นให้ไหลเป็นสายริบบิ้น"},"instruction":{"zh-TW":"從冰箱取出麵糊，加入 1-2 茶匙清水輕輕調勻，直到麵糊提起時會像絲綢緞帶般平滑連續流落，此時流動性最佳，煎出來的圓餅才會自然攤成正圓形。","en":"Stir in 1-2 tsp water so the batter ribbons smoothly off the whisk like a silk ribbon. This ensures it pools into perfect round discs.","ja":"冷蔵庫から出し、水小さじ1〜2を加えて調整。すくい上げるとリボン状にとろとろと落ちる硬さが理想です。","ko":"물 1~2작은술을 넣어 떨어뜨렸을 때 리본 모양을 그리며 차르르 흐르는 농도로 맞춥니다.","th":"เติมน้ำ 1-2 ชช. กวนให้เนียน เมื่อยกพายขึ้นแป้งจะไหลเป็นสายริบบิ้นอย่างสม่ำเสมอ แป้งจะแผ่เป็นวงกลมสวย"},"durationSeconds":60,"image":"/images/jp/dorayaki-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"零油低溫定點注入 (Pore-Free Pouring)","en":"Wipe Oil Off & Central Pour at Low Heat","ja":"油を完全に拭き取り、真上から一点集中で流す","ko":"기름을 완전히 닦아내고 정중앙에 수직으로 붓기","th":"เช็ดน้ำมันให้แห้งสนิทและเทแป้งลงตรงกลางจากที่สูง"},"instruction":{"zh-TW":"不沾平底鍋以極小火預熱。用廚房紙巾抹少許油，隨後「用另一張乾紙巾徹底把油擦乾淨」（鍋面有油滴會形成斑駁花紋！無油乾煎才能燒出鏡面深棕）。手持湯勺距鍋底約 15 公分高，定點垂直倒入麵糊，麵糊會自然流成直徑約 9 公分的完美正圓。","en":"Preheat non-stick pan on lowest heat. Wipe oil completely off with a dry paper towel. Hold ladle 15cm high and pour steadily in the exact center; it pools naturally into a 9cm circle.","ja":"フッ素加工フライパンを極弱火で温める。油を薄く塗ったらペーパーで「完全に拭き取る」（油が残るとムラになります）。高い位置から真ん中に流すと自然に綺麗な円になります。","ko":"약불로 달군 팬에 기름을 칠하고 마른 키친타월로 완전히 닦아냅니다 (기름 방울이 없어야 매끈함). 15cm 높이에서 정중앙에 수직으로 떨어뜨립니다.","th":"ตั้งกระทะไฟอ่อนสุด เช็ดน้ำมันออกให้แห้งสนิทด้วยทิชชู เทแป้งจากระดับความสูง 15 ซม. ลงตรงกลาง แป้งจะแผ่เป็นวงกลมมน"},"durationSeconds":90,"image":"/images/jp/dorayaki-step3.jpg","crucialTips":{"zh-TW":"鍋面「絕對不能看到任何油花」！無油不沾乾煎是銅鑼燒表面光滑如鏡、呈現焦糖深棕色的第一秘技。","en":"Zero oil droplets on pan! Dry searing on nonstick creates that pore-free, satin-smooth mahogany skin.","ja":"【油を完全に拭き取る】：油滴が残っているとマダラ模様になります。サラサラの鍋肌で焼くのが極意。","ko":"기름 방울이 전혀 없어야 얼룩 없이 도라에몽처럼 완벽하게 매끈한 갈색 구움색이 나옵니다.","th":"ห้ามมีหยดน้ำมันบนกระทะเด็ดขาด ต้องเช็ดให้แห้งเพื่อให้ผิวเรียบเนียนเป็นสีน้ำตาลทองไร้รอยด่าง"}},{"stepNumber":4,"title":{"zh-TW":"冒細密氣孔與秒速翻面 (Flip upon Bubbles)","en":"Flip as Bubbles Burst","ja":"ポツポツと気泡が出たら素早く裏返す","ko":"기포가 보글보글 터지면 잽싸게 뒤집기","th":"เมื่อฟองอากาศปุดขึ้นเต็มหน้า ให้พลิกกลับด้านทันที"},"instruction":{"zh-TW":"小火煎約 1.5-2 分鐘，看到表面均勻冒出許多細密的小氣孔並破裂時，用薄矽膠鏟一氣呵成滑入翻面！反面僅需烘烤 20-30 秒即可起鍋。","en":"Cook for ~90s. When fine bubbles perforate the surface and pop, slide a thin spatula underneath and flip decisively! Cook the reverse side for only 20-30 seconds.","ja":"弱火で約1分半、表面全体にプツプツと穴が開いてきたら、ヘラを差し込んで一気に返します！裏面はサッと20〜30秒で焼き上がります。","ko":"약불에서 1분 30초 후 표면에 기포가 보글보글 터지면 뒤집개로 단숨에 뒤집습니다. 뒷면은 20~30초만 굽고 꺼냅니다.","th":"ย่างไฟอ่อน 1.5 นาที เมื่อฟองอากาศผุดขึ้นทั่วหน้า ให้สอดตะหลิวพลิกกลับด้านอย่างรวดเร็ว ย่างต่อเพียง 20-30 วินาทีแล้วตักขึ้น"},"durationSeconds":120,"image":"/images/jp/dorayaki-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"覆蓋保濕與夾餡捏合 (Sandwich Azuki Paste)","en":"Cover with Damp Towel, Fill & Crimp","ja":"濡れ布巾をかけて保湿し、あんこを挟んでフチを抑える","ko":"젖은 면포 덮어 촉촉함 유지 후 팥앙금 넣고 봉하기","th":"คลุมผ้าชื้นรักษาความนุ่ม สอดไส้ถั่วแดงแล้วบีบขอบประกบ"},"instruction":{"zh-TW":"出鍋的鬆餅立刻用微濕乾淨布巾或保鮮膜蓋住（防止水分蒸發變乾變硬！）。取一片鬆餅，在中央放上一大球約 40g 的十勝蜜紅豆粒餡（中間厚、邊緣薄）。蓋上另一片鬆餅，用雙手手掌與指腹由外圍輕輕捏合四周邊緣，形成圓潤飽滿如銅鑼形狀的經典甜點！","en":"Immediately cover hot pancakes with a damp towel to trap moisture. Place a 40g mound of red bean paste in the center (thicker in middle). Top with second pancake and gently pinch rims together.","ja":"焼き上がったらすぐに乾いた布巾（またはラップ）を被せて乾燥を防ぎます。あんこを中央高めに40g乗せ、もう1枚を重ねて周りを指で軽く押さえて閉じます。","ko":"구워낸 팬케이크는 젖은 면포로 덮어 수분을 지킵니다. 팥앙금을 중앙에 볼록하게 올리고 다른 팬케이크를 덮어 가장자리를 살짝 눌러 완성합니다.","th":"นำขึ้นคลุมด้วยผ้าชื้นทันทีไม่ให้แห้ง ใส่ถั่วแดงกวน 40 กรัมตรงกลาง ประกบด้วยแป้งอีกแผ่น ใช้นิ้วบีบขอบรอบๆ ให้ติดกัน"},"durationSeconds":120,"image":"/images/jp/dorayaki-step5.jpg"}],"troubleshooting":[{"id":"trouble-dora-1","problem":{"zh-TW":"表面顏色花花的不均勻，有很多白圈斑點？","en":"Why is the pancake surface blotchy with white spots instead of uniform brown?","ja":"表面がトラ模様のようにまだらになってしまい、均一な茶色になりません。","ko":"표면이 호랑이 무늬처럼 얼룩덜룩하고 고른 갈색이 안 나와요.","th":"ทำไมผิวหน้าแพนเค้กด่างเป็นรอยกระดำกระด่าง ไม่เป็นสีน้ำตาลเนียนสม่ำเสมอ?"},"cause":{"zh-TW":"鍋面油抹太多沒有擦拭乾淨，油滴阻隔了熱度直接接觸麵糊。","en":"Residual oil on the pan created bubbles that insulated spots from searing evenly.","ja":"フライパンの油の拭き取りが不十分で、油の膜が熱伝導を邪魔したため。","ko":"팬에 남은 기름이 열전달을 방해하여 얼룩을 만들기 때문입니다.","th":"เช็ดน้ำมันบนกระทะออกไม่หมด คราบน้ำมันจะกั้นความร้อนทำให้สีไม่สม่ำเสมอ"},"solution":{"zh-TW":"塗油後務必用乾廚房紙巾徹底擦乾淨，鍋面乾爽如初才是正確狀態！","en":"Wipe pan thoroughly dry with paper towel after greasing before pouring each batch.","ja":"油を引いた後は、乾いたペーパーで油分が完全に消えるまで拭き上げましょう。","ko":"기름을 두른 뒤 마른 키친타월로 완전히 뽀송하게 닦아낸 뒤 반죽을 부으세요.","th":"ทาน้ำมันแล้วต้องใช้ทิชชูแห้งเช็ดให้สะอาดหมดจดก่อนหยอดแป้งทุกครั้ง"}}],"proTips":[{"zh-TW":"【加少許小蘇打水（重曹）的秘密】：銅鑼燒之所以色澤比西式美式鬆餅更深邃紅潤、香氣更濃，全靠微量小蘇打與蜂蜜產生的焦糖化梅納反應！","en":"Baking soda (alkaline) reacts with honey acids to produce that deep mahogany color and classic Japanese aroma.","ja":"【重曹が魅惑の焼き色を生む】：重曹を入れることでアルカリ性になり、蜂蜜のアミノ酸と反応して美しい赤銅色と独特の芳香が生まれます。","ko":"베이킹소다의 알칼리 성분이 꿀과 반응하여 서양식 팬케이크와 다른 짙은 구리빛과 풍미를 완성합니다.","th":"เบกกิ้งโซดาจะทำปฏิกิริยากับน้ำผึ้ง ทำให้สีเข้มเป็นสีทองแดงสวยงามและมีกลิ่นหอมเฉพาะตัว"}]},{"country":"jp","id":"tonkatsu","slug":"thick-cut-japanese-tonkatsu","title":{"zh-TW":"極上厚切黃金炸豬排","en":"Crispy Thick-Cut Japanese Tonkatsu","ja":"専門店直伝 極厚ジューシーとんかつ","ko":"전문점 스타일 극상 두툼한 로스카츠 (돈카츠)","th":"ทงคัตสึ หมูชุบเกล็ดขนมปังทอดกรอบชิ้นหนาพิเศษ"},"subtitle":{"zh-TW":"立體白雪生麵包粉花、粉紅粉嫩多汁斷面、高溫雙炸逼油","en":"Thick tender pork loin encased in needle-crisp fresh panko, with a blush pink juicy center","ja":"生パン粉の剣立ちサクサク！低温じっくり＆高温二度揚げでしっとり柔らかジューシー","ko":"생빵가루의 눈꽃 바삭함! 저온 숙성과 고온 2차 튀김으로 촉촉한 육즙의 절정","th":"เกล็ดขนมปังสดกรอบฟูฟ่อง เนื้อหมูสันนอกชิ้นหนานุ่มชุ่มฉ่ำ ทอดสองอุณหภูมิ"},"tagline":{"zh-TW":"日本洋食之王！掌握「斷筋拍打、生麵包粉與餘熱熟成」三把鑰匙。","en":"The undisputed King of Yoshoku! Master tendon-notching and residual heat resting.","ja":"筋切りと余熱調理が勝負の分かれ目！専門店と同じ極上の柔らかさを食卓へ。","ko":"힘줄 끊기와 잔열 레스팅으로 완성하는 인생 돈카츠 비법.","th":"ราชาแห่งอาหารตะวันตกสไตล์ญี่ปุ่น เคล็ดลับบั้งตัดพังผืดและพักเนื้อให้อมความชุ่มฉ่ำ"},"heroImage":"/images/jp/tonkatsu-hero.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":12,"defaultServings":2,"caloriesPerServing":520,"category":"agemono","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"東京都上野・銀座 (Tokyo)","en":"Ueno & Ginza, Tokyo","ja":"東京都台東区上野（ぽん多本家・とんかつ発祥の地）","ko":"도쿄 우에노 및 긴자","th":"ย่านอุเอโนะและกินซ่า โตเกียว"},"famousYataiMarkets":[{"zh-TW":"東京上野炸豬排老舖一條街","en":"Ueno Tonkatsu Historic Stalls, Tokyo","ja":"上野とんかつ老舗街","ko":"우에노 돈카츠 골목","th":"ย่านทงคัตสึเก่าแก่อุเอโนะ โตเกียว"}],"historyStory":{"zh-TW":"明治 32 年（1899 年），銀座西餐廳「煉瓦亭」將歐洲煎牛排（Côtelette）改以深油厚炸豬排骨肉，並首創搭配清爽解油膩的切細高麗菜絲與米飯，開創了現代日式炸豬排。大正年間上野「ぽん多本家」去骨改用厚切里肌，正式奠定了世界聞名的黃金厚切炸豬排地位！","en":"Invented in 1899 at Rengatei in Ginza as \"Pork Cutlet\", pioneering the iconic shredded cabbage side. Later refined in Ueno into the boneless thick-cut masterpiece we relish today.","ja":"明治32年、銀座「煉瓦亭」がカツレツを日本人向けに天ぷらのように深鍋で揚げ、千切りキャベツを添えたのが始まり。後に上野で厚切りロースのスタイルが確立されました。","ko":"1899년 긴자 렌가테이에서 시작되어 우에노에서 두툼한 등심을 튀겨내는 형태로 완성된 대표적인 일식 요리입니다.","th":"กำเนิดขึ้นในปี 1899 ที่กินซ่า โดยดัดแปลงคัตเล็ตยุโรปให้ทอดในน้ำมันท่วม เสิร์ฟคู่กะหล่ำปลีซอย"},"japaneseKanji":"とんかつ（豚カツ）","japaneseKana":"とんかつ","japaneseRomaji":"Tonkatsu","audioPronunciationText":"とんかつ","nativeName":"とんかつ（豚カツ）","nativePhonetics":"とんかつ"},"ingredients":[{"id":"pork-loin","name":{"zh-TW":"厚切豬里肌肉排 (Thick-Cut Pork Loin Steak)","en":"Thick-cut boneless pork loin chops (2.5cm thick)","ja":"豚ロース肉（厚さ2.5cm）","ko":"돼지 등심 (두께 2.5cm)","th":"หมูสันนอกหั่นหนาพิเศษ 2.5 ซม."},"amount":300,"unitMetric":"g","unitUS":"10.5 oz (approx 2 steaks)","isKeyFlavor":true,"japaneseKanji":"豚ロース肉","japaneseKana":"ぶたろーすにく","japaneseRomaji":"Buta Rōsu Niku"},{"id":"fresh-panko","name":{"zh-TW":"日式生麵包粉 (Fresh Japanese Nama Panko)","en":"Coarse fresh Japanese panko breadcrumbs","ja":"生パン粉（粗目）","ko":"생빵가루 (굵은 입자)","th":"เกล็ดขนมปังสด (นามะแพนโกะ)"},"amount":90,"unitMetric":"g","unitUS":"1.2 cups","isKeyFlavor":true,"japaneseKanji":"生パン粉","japaneseKana":"なまぱんこ","japaneseRomaji":"Nama Panko"},{"id":"flour","name":{"zh-TW":"中筋或低筋麵粉 (Flour for dusting)","en":"Flour for dusting","ja":"薄力粉","ko":"밀가루","th":"แป้งสาลี"},"amount":40,"unitMetric":"g","unitUS":"1/3 cup","japaneseKanji":"薄力粉","japaneseKana":"はくりきこ","japaneseRomaji":"Hakurikiko"},{"id":"egg-wash","name":{"zh-TW":"打散全蛋加 1 茶匙植物油 (Egg Wash with a drop of oil)","en":"Beaten egg with 1 tsp oil (improves adhesion)","ja":"溶き卵（油小さじ1を加えると結着力UP）","ko":"달걀물 (식용유 1작은술 섞음)","th":"ไข่ไก่ตีผสมน้ำมัน 1 ช้อนชา"},"amount":1,"unitMetric":"piece","unitUS":"piece","japaneseKanji":"溶き卵","japaneseKana":"ときたまご","japaneseRomaji":"Toki Tamago"},{"id":"cabbage","name":{"zh-TW":"極細高麗菜絲 (Finely shredded cabbage, ice-chilled)","en":"Shredded cabbage chilled in ice water","ja":"千切りキャベツ（氷水にさらしたもの）","ko":"얼음물에 담가 아삭해진 양배추 채","th":"กะหล่ำปลีซอยละเอียดแช่น้ำแข็ง"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","japaneseKanji":"千切りキャベツ","japaneseKana":"せんぎりきゃべつ","japaneseRomaji":"Sengiri Kyabetsu"},{"id":"tonkatsu-sauce","name":{"zh-TW":"炸豬排醬與研磨白芝麻 (Tonkatsu Sauce & Toasted Sesame)","en":"Tonkatsu sauce with freshly ground sesame seeds","ja":"とんかつソース・すりごま・からし","ko":"돈카츠 소스, 간 참깨, 연겨자","th":"ซอสทงคัตสึ งาขาวคั่วบด และคาราชิ"},"amount":40,"unitMetric":"ml","unitUS":"2.5 tbsp","isKeyFlavor":true,"japaneseKanji":"とんかつソース","japaneseKana":"とんかつそーす","japaneseRomaji":"Tonkatsu Sōsu"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"斷筋切刀與拍整 (Score Tendons & Season)","en":"Score Tendons & Light Seasoning","ja":"赤身と脂身の間の筋を切り、塩胡椒する","ko":"비계와 살코기 사이 힘줄 끊고 밑간하기","th":"ใช้มีดบั้งตัดพังผืดระหว่างเนื้อกับมัน โรยเกลือพริกไทย"},"instruction":{"zh-TW":"豬里肌在室溫回溫 15 分鐘。觀察肉片，在瘦肉與外圍白色肥肉交界處，每隔 1.5 公分用刀尖切入垂直小刀口（筋切り，切斷透明筋膜，防止下油鍋時肉質捲曲緊縮變厚變硬）。用肉槌或刀背輕拍兩面，抹上一層海鹽與研磨黑胡椒。","en":"Rest pork at room temp for 15 mins. Notch the connective tendon between the fat rim and red meat every 1.5 cm with knife tip to prevent curling. Lightly pound both sides; season with salt and pepper.","ja":"肉を室温に戻す。赤身と脂身の境目にある白いスジを包丁の先で数箇所刺して切ります（筋切り）。包丁の背で軽く叩いて元の形に整え、塩コショウを振ります。","ko":"고기를 실온에 15분 두어 냉기를 뺍니다. 살코기와 비계 경계면의 질긴 힘줄을 1.5cm 간격으로 칼끝으로 끊어준 뒤 칼등으로 두드리고 소금, 후추로 밑간합니다.","th":"พักหมูคลายเย็น 15 นาที ใช้ปลายมีดบั้งพังผืดระหว่างเนื้อแดงกับมันทุก 1.5 ซม. ใช้สันมีดทุบเบาๆ โรยเกลือและพริกไทย"},"durationSeconds":180,"image":"/images/jp/tonkatsu-step1.jpg","crucialTips":{"zh-TW":"「筋切り（切斷筋膜）」是厚切豬排平整受熱、肉質軟嫩咬得斷的最核心秘密！筋膜受熱收縮力極強，不切斷會導致豬排整塊弓起夾生。","en":"Notching the membrane prevents the pork from buckling into a curled bowl shape in the fryer.","ja":"【筋切りで縮み防止】：スジを切らないと熱で肉が弓なりに反り返り、真ん中が生焼けになってしまいます。","ko":"힘줄을 끊지 않으면 튀길 때 고기가 오그라들어 가운데가 익지 않고 질겨집니다.","th":"การตัดพังผืดจะช่วยให้เนื้อหมูแบนเรียบและสุกสม่ำเสมอทั่วทั้งชิ้น ไม่โค้งงอ"}},{"stepNumber":2,"title":{"zh-TW":"輕拍薄粉與裹生麵包粉 (Flour, Egg & Nama Panko)","en":"Flour Dust, Egg Wash & Fluffy Panko Coat","ja":"小麦粉を薄くはたき、卵液、生パン粉をふんわりまぶす","ko":"밀가루 털어내고 달걀물 거쳐 생빵가루 눈꽃 입히기","th":"ชุบแป้งบางๆ ชุบไข่ และคลุกเกล็ดขนมปังสดเบามือ"},"instruction":{"zh-TW":"肉片均勻裹上麵粉，雙手用力拍打抖掉所有多餘乾粉（只留一層極薄半透明膜）。浸入加入少許油調勻的蛋液中，隨後放入生麵包粉中，由兩側撥起麵包粉輕輕覆蓋（切忌用力按壓！保留麵包粉的立體「劍立ち」針狀直立感，炸出來才會如白雪般輕盈挺立）。","en":"Dust pork in flour, shaking off all excess until translucent. Dip in egg wash, then bury in fresh panko, pressing very gently without crushing. Leave breadcrumbs standing like needles.","ja":"小麦粉をまぶして余分な粉をしっかり叩き落とす。卵液にくぐらせ、生パン粉の上に置いて優しく上からパン粉を被せます（強く押し付けないこと）。","ko":"밀가루를 묻혀 탁탁 털어내고 달걀물을 적신 뒤, 생빵가루를 얹어 누르지 않고 가볍게 감싸듯 입힙니다 (가시처럼 서 있어야 바삭함).","th":"คลุกแป้งสาลีแล้วตบออกให้เหลือบางเฉียบ ชุบไข่ วางลงบนเกล็ดขนมปังสด กอบเกล็ดขนมปังกลบเบาๆ โดยไม่กดทับ"},"durationSeconds":180,"image":"/images/jp/tonkatsu-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"氣炸鍋模式：190°C (375°F) 氣炸 14 分鐘，出爐靜置 4 分鐘","instructionOverride":{"zh-TW":"使用預先乾炒成金黃色的麵包粉包裹豬排。表面均勻噴油，放入氣炸鍋 190°C 氣炸 10 分鐘，翻面再氣炸 4 分鐘，取出用鋁箔紙包覆靜置 4 分鐘切塊。","en":"Use pre-toasted golden panko. Mist with oil, air fry at 190°C for 10 mins, flip, fry 4 more mins. Rest tented in foil for 4 mins before slicing.","ja":"乾煎りしたパン粉を使用。油をスプレーし190℃で10分、裏返して4分加熱。アルミホイルに包み4分余熱を通します。","ko":"미리 볶아둔 빵가루를 묻히고 오일을 뿌려 190도에서 10분, 뒤집어 4분간 에어프라이어로 구운 뒤 은박지에 싸서 4분간 레스팅합니다.","th":"ใช้เกล็ดขนมปังคั่วสีทอง ฉีดน้ำมัน อบในหม้อทอดไร้น้ำมัน 190°C นาน 10 นาที กลับด้านอบต่อ 4 นาที ห่อฟอยล์พัก 4 นาที"}}]},{"stepNumber":3,"title":{"zh-TW":"第一炸：中低溫浸熟肉芯 (1st Fry: Gentle Cook)","en":"First Fry at 160°C (320°F) for 5 Mins","ja":"一度目：160℃の低温でじっくり5分揚げる","ko":"1차 튀김: 160도 중저온에서 5분간 속 익히기","th":"ทอดรอบแรก: ไฟกลาง 160°C นาน 5 นาทีให้สุกถึงใจกลาง"},"instruction":{"zh-TW":"厚鍋中倒入足量沙拉油（油深至少能完全沒過豬排），升溫至 160°C。輕柔滑入豬排，小火油炸約 5 分鐘（中途翻面一次），氣泡細小溫和。炸至外表呈現淺米黃色，夾起瀝油。","en":"Heat ample oil to 160°C (320°F). Slide pork in gently; fry for 5 mins (turning once) with gentle sizzling bubbles. Remove onto a rack.","ja":"160℃の油に静かに入れ、弱火で約5分（途中で一度裏返す）。細かい泡が静かに立つ状態で揚げ、バットに取り出します。","ko":"160도 기름에 넣고 약불에서 잔잔하게 5분간 튀깁니다 (중간에 한 번 뒤집기). 연한 노란색이 되면 건져냅니다.","th":"ทอดในน้ำมัน 160°C นาน 5 นาที พลิกกลับด้าน 1 ครั้ง ทอดจนสีเหลืองอ่อนแล้วตักขึ้นสะเด็ดน้ำมัน"},"durationSeconds":300,"image":"/images/jp/tonkatsu-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"餘熱熟成與高溫復炸 (Resting & Flash Crisping)","en":"Rest 4 Mins & Flash Fry at 185°C (365°F)","ja":"4分間余熱で休ませ、185℃で1分カリッと二度揚げ","ko":"4분간 잔열 레스팅 후 185도에서 1분간 바삭하게 2차 튀김","th":"พักเนื้อ 4 นาที แล้วทอดรอบสอง 185°C นาน 1 นาทีให้กรอบสนั่น"},"instruction":{"zh-TW":"【關鍵核心步驟】：將第一炸出鍋的豬排直立架在金屬網架上「靜置 4 分鐘」！利用肉排內部高溫將中心慢慢燜至多汁柔嫩的淡粉色。隨後將油溫拉高至 185°C，投入豬排高溫復炸 60 秒，逼出油脂並將麵包粉炸出金棕誘人酥脆感，立刻起鍋！","en":"CRITICAL STEP: Rest pork on a wire rack for 4 mins! Residual heat gently finishes the pink juicy center. Crank oil to 185°C and flash-fry for 60s for a crackly golden crunch.","ja":"【最重要】：金網の上で4分間しっかり休ませます（余熱で肉の中心がロゼ色にしっとり仕上がる）。油を185℃に上げ、1分だけ二度揚げして油を切り、外側をカリカリに仕上げます。","ko":"핵심 비법: 망 위에서 4분간 그대로 두어 잔열로 속을 핑크빛 촉촉하게 익힙니다. 기름 온도를 185도로 올려 1분간 바삭하게 튀겨 기름을 뺍니다.","th":"เคล็ดลับสำคัญ: พักเนื้อบนตะแกรง 4 นาทีให้ความร้อนระอุเข้าเนื้อใน เร่งน้ำมัน 185°C ทอดรอบสอง 60 วินาทีให้กรอบจัด"},"durationSeconds":300,"image":"/images/jp/tonkatsu-step4.jpg","crucialTips":{"zh-TW":"「中間靜置 4 分鐘」是頂級炸豬排名店能炸出粉嫩多汁斷面的天機！直接高溫炸到底只會讓外皮焦黑、內部乾硬如柴。","en":"The resting interval allows protein juices to redistribute while cooking the center gently without burning the crust.","ja":"【余熱調理こそプロの極意】：休ませずに揚げ続けるとパサパサになります。余熱で火を通すからこそジューシー！","ko":"쉬어가는 시간(레스팅)이 육즙을 가두고 부드러운 분홍빛 단면을 만드는 결정적 차이입니다.","th":"การพักเนื้อ 4 นาทีทำให้เนื้อหมูด้านในสุกเป็นสีชมพูอ่อนชุ่มฉ่ำ ไม่แห้งกระด้าง"}},{"stepNumber":5,"title":{"zh-TW":"立切厚塊與排盤盛裝 (Slice & Serve with Cabbage)","en":"Slice Upright & Serve with Tonkatsu Sauce","ja":"包丁を立ててサクッと切り、キャベツとソースを添える","ko":"칼을 수직으로 눌러 썰고 양배추와 소스 곁들이기","th":"หั่นแนวตรงเสียงกรอบลั่น เสิร์ฟคู่กะหล่ำปลีซอยและซอส"},"instruction":{"zh-TW":"將豬排豎立靜置 1 分鐘瀝乾油滴。一刀切下，發出清脆悅耳的咔滋碎響，切面微泛淡粉色肉汁光澤。將切塊豬排移入裝滿冰鎮高麗菜絲的大盤中，佐以現磨白芝麻、日式炸豬排濃醬與一抹黃芥末，大口咬下肉汁四溢！","en":"Slice decisively with a sharp chef’s knife, listening to the crunch. Serve alongside a mountain of shredded chilled cabbage, ground sesame, tonkatsu sauce, and spicy karashi mustard.","ja":"包丁を前後に動かさず上からサクッと一気に切ります。山盛りの千切りキャベツ、すりごま入りとんかつソース、辛子を添えて完成！","ko":"칼을 톱질하지 말고 위에서 아래로 단숨에 썰어냅니다. 수북한 양배추 채와 깨소금 돈가스 소스를 곁들여 바삭함을 만끽하세요!","th":"ใช้มีดคมกดหั่นลงไปในครั้งเดียว เสิร์ฟคู่กะหล่ำปลีซอยภูเขา งาบด ซอสทงคัตสึ และมัสตาร์ดคาราชิ"},"durationSeconds":60,"image":"/images/jp/tonkatsu-step5.jpg"}],"troubleshooting":[{"id":"trouble-ton-1","problem":{"zh-TW":"切開時麵衣與豬肉完全分離脫落？","en":"Why did the crispy panko shell separate and detach from the meat when sliced?","ja":"切った時に衣と肉がパカッと剥がれてしまいます。","ko":"썰었을 때 튀김옷과 고기가 분리되어 떨어져 나가요.","th":"ทำไมเวลาหั่นแล้วแป้งทอดกรอบหลุดลอกออกจากชิ้นเนื้อหมู?"},"cause":{"zh-TW":"裹粉前豬肉表面太濕或麵粉裹太厚，未徹底拍掉多餘乾粉；或者蛋液沒有均勻沾滿。","en":"Pork was wet before dusting, or excess dry flour created a flour barrier preventing egg and panko from bonding.","ja":"肉の表面の水分が残っていたか、小麦粉を付けすぎて余分な粉を落とさなかったため。","ko":"고기 표면 물기를 덜 닦았거나, 밀가루를 털어내지 않아 밀가루 막이 형성되어 분리된 것입니다.","th":"เนื้อหมูเปียก หรือคลุกแป้งหนาเกินไปโดยไม่ได้เคาะออก แป้งส่วนเกินจะเป็นกำแพงกั้น"},"solution":{"zh-TW":"肉身先用紙巾徹底擦乾，沾粉後用雙手大力拍打直到只剩極薄半透明霧狀，蛋液中滴幾滴油拌勻增強黏著力！","en":"Pat meat completely dry, slap off 90% of flour, and mix 1 tsp oil into the egg wash to boost adhesion.","ja":"ペーパーで完璧に水気を取り、小麦粉は叩いて透明になるまで落としましょう。卵液に油少々を入れると密着度UP。","ko":"고기 수분을 완벽히 닦고, 밀가루를 거의 털어낸 뒤 달걀물에 기름 1작은술을 섞어 접착력을 높이세요.","th":"ซับเนื้อให้แห้งสนิท เคาะแป้งออกจนเหลือบางใส และผสมน้ำมันลงในไข่เล็กน้อยเพื่อช่วยยึดเกาะ"}}],"proTips":[{"zh-TW":"【使用生麵包粉（Nama Panko）】：生麵包粉含有約 30% 天然水分，下鍋時麵包屑會如針狀立體挺立（劍立ち），炸出來比一般乾燥麵包粉酥脆十倍，且口感鬆脆完全不刮上顎！","en":"Fresh coarse panko contains moisture that blooms into airy needle shards in hot oil, infinitely crisper than hard dry breadcrumbs.","ja":"【生パン粉で「剣立ち」】：乾燥パン粉ではなく生パン粉を使うことで、専門店のようなトゲトゲとした立体的で軽い衣になります。","ko":"건조 빵가루 대신 수분이 있는 생빵가루를 쓰면 입천장이 까지지 않는 극상의 눈꽃 바삭함을 얻을 수 있습니다.","th":"ใช้เกล็ดขนมปังสดจะช่วยให้ผิวด้านนอกฟูเป็นเกล็ดแหลมคมสวยงาม กรอบโปร่งไม่บาดเหงือก"}]},{"country":"jp","id":"gyudon","slug":"classic-tokyo-gyudon","title":{"zh-TW":"經典吉野家風味日式牛丼","en":"Classic Tokyo Gyudon Beef Rice Bowl","ja":"吉野家風 極上牛丼（つゆだく・紅生姜添え）","ko":"요시노야 스타일 클래식 소고기 덮밥 (규동)","th":"กิวด้ง ข้าวหน้าเนื้อสไตล์โตเกียวดั้งเดิม"},"subtitle":{"zh-TW":"雪花牛五花慢火微沸浸熟、焦甜洋蔥與高湯甜醬汁淋透熱米飯","en":"Tender shaved beef and sweet onions simmered in sweet dashi soy broth, ladled over hot rice","ja":"出汁の効いた秘伝の甘辛ダレで、柔らかい牛バラ肉と甘い玉ねぎをとろけるように煮込む名物丼","ko":"부드러운 우삼겹과 달콤한 양파에 비법 육수가 촉촉하게 밴 밥도둑 규동","th":"เนื้อสไลซ์นุ่มละลายในปากและหอมใหญ่เคี่ยวในซอสโชยุดาชิ ราดบนข้าวสวยร้อนๆ"},"tagline":{"zh-TW":"日本百年速食國民代表作！掌握「微沸不老肉」與紅生薑溫泉蛋神級吃法。","en":"Japan’s iconic 100-year comfort bowl, ready in 15 mins with onsen egg and beni shoga.","ja":"15分で名店の味を完全再現！牛肉を煮立たせず柔らかく仕上げるのがプロの掟。","ko":"15분 완성! 고기가 질겨지지 않도록 불 조절하는 비법과 온천달걀 꿀조합.","th":"เมนูข้าวหน้าเนื้ออันดับหนึ่งของญี่ปุ่น ทำง่ายใน 15 นาที ทานคู่ออนเซ็นทามาโกะ"},"heroImage":"/images/jp/gyudon-hero.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":560,"category":"yakimono","dietaryTags":["classic","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"東京都中央區・日本橋與築地 (Tokyo)","en":"Nihonbashi & Tsukiji, Tokyo","ja":"東京都中央区日本橋（吉野家1号店は築地）","ko":"도쿄 니혼바시 및 츠키지 시장","th":"นิฮงบาชิและตลาดซึกิจิ โตเกียว"},"famousYataiMarkets":[{"zh-TW":"東京築地市場吉野家 1 號店遺跡","en":"Tsukiji Market Yoshinoya Original Store Site, Tokyo","ja":"築地市場 吉野家1号店","ko":"츠키지 시장 요시노야 1호점","th":"ร้านโยชิโนยะสาขาแรก ตลาดซึกิจิ"},{"zh-TW":"東京新宿思出橫丁深夜食堂","en":"Shinjuku Midnight Diners, Tokyo","ja":"新宿深夜食堂","ko":"신주쿠 심야식당","th":"ร้านอาหารรอบดึกชินจูกุ"}],"historyStory":{"zh-TW":"牛丼前身源自明治維新時期的「牛鍋（Gyūnabe）」，庶民將昂貴的牛肉碎與魔芋、洋蔥澆在飯上食用。明治 32 年（1899 年），松田榮吉在東京日本橋魚市場創辦「吉野家」，發明了「快速、平價、美味（うまい、やすい、はやい）」的牛丼，成為現代日本上班族最依賴的能量源泉！","en":"Born during the Meiji Restoration as an offshoot of beef hotpot (Gyunabe). In 1899, Eikichi Matsuda founded Yoshinoya in Nihonbashi, revolutionizing fast, affordable, hearty comfort food.","ja":"明治の文明開化で誕生した「牛鍋」の具材を丼飯に乗せたのがルーツ。1899年創業の吉野家が「早い、うまい、安い」を確立し、日本屈指のソウルフードとなりました。","ko":"메이지 유신 시절 소고기 전골에서 유래하여 1899년 니혼바시 어시장에서 탄생한 패스트푸드의 원조입니다.","th":"มีต้นกำเนิดจากหม้อไฟเนื้อในยุคเมจิ ต่อมาในปี 1899 ได้พัฒนาเป็นข้าวหน้าเนื้อที่รวดเร็วและคุ้มค่า"},"japaneseKanji":"牛丼","japaneseKana":"ぎゅうどん","japaneseRomaji":"Gyūdon","audioPronunciationText":"牛丼","nativeName":"牛丼","nativePhonetics":"ぎゅうどん"},"ingredients":[{"id":"beef-short-plate","name":{"zh-TW":"薄切雪花牛五花肉片 (Thinly Shaved Beef Short Plate)","en":"Thinly shaved beef short plate (or ribeye)","ja":"牛バラ薄切り肉（牛丼用スライス）","ko":"우삼겹 또는 소고기 불고기감 (얇게 썬 것)","th":"เนื้อวัวสไลซ์บางติดมัน (เนื้อสามชั้นสไลซ์)"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"japaneseKanji":"牛バラ薄切り肉","japaneseKana":"ぎゅうばらうすぎりにく","japaneseRomaji":"Gyūbara Usugiri Niku"},{"id":"onion","name":{"zh-TW":"洋蔥粗絲 (Sliced Yellow Onion)","en":"Yellow onion, sliced 1cm thick","ja":"玉ねぎ（くし形切り）","ko":"양파 굵게 채 썬 것","th":"หอมใหญ่หั่นเสี้ยวหนา 1 ซม."},"amount":150,"unitMetric":"g","unitUS":"1 medium","isKeyFlavor":true,"japaneseKanji":"玉ねぎ","japaneseKana":"たまねぎ","japaneseRomaji":"Tamanegi"},{"id":"dashi-stock","name":{"zh-TW":"鰹魚昆布高湯 (Dashi Stock)","en":"Dashi Broth","ja":"和風だし汁","ko":"다시 육수","th":"น้ำซุปดาชิ"},"amount":200,"unitMetric":"ml","unitUS":"0.8 cup","japaneseKanji":"だし汁","japaneseKana":"だしじる","japaneseRomaji":"Dashi Jiru"},{"id":"shoyu","name":{"zh-TW":"濃口醬油 (Koikuchi Soy Sauce)","en":"Japanese Soy Sauce","ja":"醤油","ko":"진간장","th":"โชยุญี่ปุ่น"},"amount":45,"unitMetric":"ml","unitUS":"3 tbsp","isKeyFlavor":true,"japaneseKanji":"醤油","japaneseKana":"しょうゆ","japaneseRomaji":"Shōyu"},{"id":"mirin","name":{"zh-TW":"本味醂 (Hon Mirin)","en":"Hon-Mirin","ja":"本みりん","ko":"미림","th":"มิริน"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","japaneseKanji":"本みりん","japaneseKana":"ほんみりん","japaneseRomaji":"Hon-Mirin"},{"id":"sake","name":{"zh-TW":"料理清酒 (Cooking Sake)","en":"Cooking Sake","ja":"清酒","ko":"청주","th":"สาเก"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","japaneseKanji":"料理酒","japaneseKana":"りょうりしゅ","japaneseRomaji":"Ryōrishu"},{"id":"sugar","name":{"zh-TW":"細砂糖 (Sugar)","en":"Sugar","ja":"砂糖","ko":"설탕","th":"น้ำตาลทราย"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","japaneseKanji":"砂糖","japaneseKana":"さとう","japaneseRomaji":"Satō"},{"id":"ginger-juice","name":{"zh-TW":"現磨生薑汁 (Grated Ginger Juice)","en":"Fresh ginger juice","ja":"生姜の搾り汁","ko":"생강즙","th":"น้ำขิงคั้นสด"},"amount":5,"unitMetric":"ml","unitUS":"1 tsp","japaneseKanji":"生姜汁","japaneseKana":"しょうがじる","japaneseRomaji":"Shōga Jiru"},{"id":"steamed-rice","name":{"zh-TW":"熱騰騰越光米飯 (Steamed Japanese Rice)","en":"Hot steamed short-grain Japanese rice","ja":"炊きたて白ご飯","ko":"따끈한 흰 쌀밥","th":"ข้าวสวยญี่ปุ่นร้อนๆ"},"amount":350,"unitMetric":"g","unitUS":"2 large bowls","japaneseKanji":"白飯","japaneseKana":"しろめし","japaneseRomaji":"Shiromeshi"},{"id":"beni-shoga","name":{"zh-TW":"紅生薑與溫泉蛋 (Beni Shoga & Onsen Egg)","en":"Beni Shoga pickled red ginger & Onsen soft-boiled egg","ja":"紅生姜・温泉卵","ko":"초생강과 온천달걀","th":"ขิงดองสีแดงและไข่ออนเซ็น"},"amount":20,"unitMetric":"g","unitUS":"garnish","japaneseKanji":"紅生姜・温泉卵","japaneseKana":"べにしょうが・おんせんたまご","japaneseRomaji":"Beni Shōga / Onsen Tamago"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"煮軟焦甜洋蔥 (Simmer Onions First)","en":"Simmer Onions in Sweet Dashi","ja":"出汁と調味料で玉ねぎをしんなりするまで煮る","ko":"육수와 양념에 양파를 먼저 투명하게 졸이기","th":"ต้มหอมใหญ่ในน้ำซุปดาชิให้หวานนุ่ม"},"instruction":{"zh-TW":"平底深鍋中倒入高湯、醬油、味醂、清酒、砂糖與生薑汁，大火煮滾。加入切成寬條的洋蔥，轉中火加蓋煮 4-5 分鐘，直到洋蔥呈現半透明狀、充分吸收甜醬汁。","en":"In a shallow pot, bring dashi, soy sauce, mirin, sake, sugar, and ginger juice to a boil. Add sliced onions; simmer covered for 4-5 mins until translucent and sweet.","ja":"鍋に出汁、醤油、みりん、酒、砂糖、生姜汁を入れて煮立てる。玉ねぎを加え、フタをして中火で約4〜5分、透き通るまで煮ます。","ko":"냄비에 육수, 간장, 미림, 청주, 설탕, 생강즙을 끓이고 양파를 넣어 뚜껑 덮고 4~5분간 투명해질 때까지 졸입니다.","th":"ต้มน้ำซุปดาชิ โชยุ มิริน สาเก น้ำตาล และน้ำขิง ใส่หอมใหญ่ ปิดฝาต้ม 4-5 นาทีจนนุ่มใส"},"durationSeconds":300,"image":"/images/jp/gyudon-step1.jpg","crucialTips":{"zh-TW":"洋蔥一定要「先煮軟」才放牛肉！因為牛肉只需要煮 2-3 分鐘，若一起下鍋，等洋蔥煮軟時牛肉早就老硬如皮鞋。","en":"Cook onions first! Beef only needs 2-3 minutes; throwing them in together results in leathery overcooked beef.","ja":"【玉ねぎを先に煮る】：牛肉は数分で火が通るため、必ず玉ねぎが柔らかくなってから投入するのが絶対ルールです。","ko":"양파를 먼저 익혀야 합니다! 소고기는 2~3분만 끓여야 하므로 나중에 넣어야 부드럽습니다.","th":"ต้องต้มหอมใหญ่ให้สุกนุ่มก่อนใส่เนื้อวัว เพราะเนื้อสุกเร็วมาก หากใส่พร้อมกันเนื้อจะเหนียว"}},{"stepNumber":2,"title":{"zh-TW":"展肉下鍋微沸浸熟 (Poach Shaved Beef)","en":"Add Beef & Gentle Poach on Low","ja":"牛肉を広げ入れ、弱火でアクを取りながらサッと煮る","ko":"소고기를 한 장씩 펴서 넣고 거품 걷어내며 살짝 익히기","th":"คลี่เนื้อวัวใส่ลงไป ช้อนฟองออก เคี่ยวไฟอ่อนพอสุก"},"instruction":{"zh-TW":"將火調至「極小火微沸狀態」。用筷子將薄切牛五花肉一片片展開放入鍋中（切忌整坨丟進去），輕輕撥散在熱湯汁中。用勺子撈除表面浮沫雜質，小火微煮 2-3 分鐘至肉色轉為粉棕色即可關火。","en":"Lower heat to a gentle simmer. Unfurl shaved beef slice-by-slice into the bubbling broth (never dump as a clump). Skim off grey scum. Simmer for only 2-3 mins until just cooked. Turn off heat.","ja":"弱火にし、牛肉を1枚ずつ広げながら加えます。アクを丁寧にすくい取り、煮立てずに2〜3分サッと煮て火を止めます。","ko":"약불로 줄이고 소고기를 뭉치지 않게 한 장씩 펼쳐 넣습니다. 떠오르는 거품을 걷어내고 2~3분만 살짝 익힌 뒤 불을 끕니다.","th":"หรี่ไฟอ่อนสุด คลี่แผ่นเนื้อใส่ลงไปทีละชิ้น ช้อนฟองดำทิ้ง เคี่ยวไฟอ่อน 2-3 นาทีพอเนื้อเปลี่ยนสีให้ปิดไฟทันที"},"durationSeconds":180,"image":"/images/jp/gyudon-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"盛飯鋪肉與澆汁 (Ladle onto Hot Rice)","en":"Ladle Beef & Tsuyudaku Broth over Rice","ja":"丼ご飯に肉と玉ねぎを盛り、つゆを回しかける","ko":"따뜻한 밥 위에 고기와 양파를 얹고 국물 끼얹기","th":"ตักเนื้อและหอมใหญ่วางบนข้าว ราดน้ำซุปให้ชุ่มฉ่ำ"},"instruction":{"zh-TW":"在大碗中盛入熱騰騰的白米飯。用漏勺將軟嫩的牛五花肉與焦甜洋蔥鋪滿整個飯面（完全看不到白飯），隨後舀起一大勺濃郁的高湯肉汁（吉野家名詞「つゆだく Tsuyudaku，多湯汁」）澆淋在飯上，讓每一粒米都吸飽牛肉鮮甜！","en":"Fill a bowl with steaming hot rice. Ladle tender beef and onions across the top until no rice is visible. Pour a generous spoonful of savory broth over the rice (\"Tsuyudaku\" style).","ja":"丼に炊きたてのご飯を盛り、牛肉と玉ねぎをたっぷりと敷き詰めます。お好みで煮汁をたっぷり回しかけます（つゆだく）。","ko":"따뜻한 밥 위에 고기와 양파를 빈틈없이 덮고, 달콤 짭조름한 국물을 넉넉히 둘러줍니다 (츠유다쿠 스타일).","th":"ตักข้าวสวยใส่ชาม ตักเนื้อและหอมใหญ่วางทับจนมิดข้าว ราดน้ำซุปตามลงไปให้ชุ่มฉ่ำ"},"durationSeconds":60,"image":"/images/jp/gyudon-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"放溫泉蛋與紅生薑 (Onsen Egg & Pickled Ginger)","en":"Crown with Onsen Egg & Red Ginger","ja":"温泉卵と紅生姜を乗せ、七味唐辛子を振る","ko":"온천달걀과 초생강 올리고 시치미 톡톡","th":"วางไข่ออนเซ็น ขิงดองสีแดง และโรยพริกชิจิมิ"},"instruction":{"zh-TW":"在牛丼中央輕輕敲入一顆溫泉蛋（或新鮮無菌生蛋黃），側邊擺上一大坨酸脆爽口的日式紅生薑，撒上少許七味唐辛子。戳破流心蛋黃，拌著裹滿牛肉湯汁的米飯大口扒入嘴裡，人間美味！","en":"Nestle a wobbly onsen egg in the center and heap red pickled beni shoga ginger on the side. Dust with shichimi pepper. Break the yolk into the beefy rice and dig in!","ja":"中央にくぼみを作り、温泉卵（または生卵）を落とします。紅生姜をたっぷり添え、七味唐辛子を振ってかき込みましょう！","ko":"가운데 온천달걀(또는 노른자)을 얹고 초생강을 곁들인 뒤 시치미를 뿌립니다. 노른자를 터뜨려 밥과 함께 비벼 드세요!","th":"วางไข่ออนเซ็นเยิ้มๆ ตรงกลาง แนบด้วยขิงดอง โรยพริกชิจิมิ เจาะไข่แดงคลุกเคล้ากับข้าวหน้าเนื้อ ทานฟินสุดๆ"},"durationSeconds":30,"image":"/images/jp/gyudon-step4.jpg"}],"troubleshooting":[{"id":"trouble-gyu-1","problem":{"zh-TW":"牛肉吃起來很柴很老，完全沒有吉野家入口即化的滑嫩感？","en":"Why is the beef tough and dry instead of melt-in-mouth tender?","ja":"牛肉が固くパサパサになってしまいました。","ko":"소고기가 질기고 퍽퍽해요.","th":"ทำไมเนื้อวัวเหนียวกระด้าง ไม่นุ่มละลายเหมือนร้านดัง?"},"cause":{"zh-TW":"火開太大、大火滾煮時間太長，或者是買錯了油脂過少的純瘦肉。","en":"Boiled on high heat for too long, or used lean cut instead of well-marbled short plate with fat ribbons.","ja":"グラグラ強火で煮立てすぎたか、脂身の少ない赤身肉を使ったため。","ko":"센 불에서 너무 오래 끓였거나 지방이 적은 부위를 사용했기 때문입니다.","th":"ใช้ไฟแรงต้มเดือดนานเกินไป หรือใช้เนื้อแดงล้วนไม่มีมันแทรก"},"solution":{"zh-TW":"務必指名購買帶油花的「牛五花肉薄切片（Short Plate）」，下鍋後轉微火煮 2 分鐘轉色就關火！","en":"Use fatty shaved beef short plate (brisket), and simmer on the lowest heat for just 2 mins.","ja":"適度に脂の乗った牛バラ肉を選び、弱火で2〜3分さっと火を通すだけに留めましょう。","ko":"지방이 적당히 섞인 우삼겹 부위를 선택하고, 약불에서 2~3분만 익혀 불을 끄세요.","th":"เลือกเนื้อสามชั้นติดมันสไลซ์บาง และเคี่ยวไฟอ่อนเพียง 2-3 นาทีพอสุก"}}],"proTips":[{"zh-TW":"【加少許生薑汁去腥提鮮】：吉野家百年配方的秘密，在於湯底加入了少許現榨生薑汁與微量白葡萄酒，能在加熱中分解牛肉的羶味，引出深層的甘甜與醇厚回味！","en":"The secret touch: A teaspoon of fresh ginger juice cuts beef fat gaminess and imparts that signature Yoshinoya aroma.","ja":"【生姜汁でキレのある後味】：少量の生姜の搾り汁を加えることで、牛脂のくどさを消し、後味すっきり名店の味になります。","ko":"생강즙 1작은술이 소고기 특유의 기름진 냄새를 잡아주고 깔끔하고 깊은 풍미를 더해줍니다.","th":"น้ำขิงคั้นสด 1 ช้อนชาช่วยดับเลี่ยนไขมันเนื้อ และดึงรสชาติหวานกลมกล่อมตามแบบฉบับโยชิโนยะ"}]},{"country":"jp","id":"yaki-onigiri","slug":"izakaya-crispy-yaki-onigiri","title":{"zh-TW":"居酒屋焦香醬烤飯糰","en":"Crispy Izakaya Grilled Yaki Onigiri","ja":"居酒屋の〆 定番香ばし焼きおにぎり（醤油バター味）","ko":"이자카야 스타일 바삭한 구운 주먹밥 (야키 오니기리)","th":"ยากิโอนิกิริ ข้าวปั้นย่างซีอิ๊วเนยกรอบหอมสไตล์อิซากายะ"},"subtitle":{"zh-TW":"外層鍋巴薄脆嘎吱作響、內心鬆軟熱氣米香、日式醬油奶油焦香","en":"Crackly browned rice crust on the outside, fluffy and steaming inside, brushed with soy butter","ja":"外はカリッとおこげが香ばしく、中はふっくらアツアツ！特製醤油ダレが染み渡る逸品","ko":"겉은 누룽지처럼 바삭바삭, 속은 촉촉한 밥알에 간장 버터 향이 가득 밴 구운 삼각김밥","th":"ผิวนอกกรอบเกรียมคล้ายข้าวตัง ด้านในนุ่มหอมข้าวญี่ปุ่น ราดซอสโชยุเนยย่างเตาถ่าน"},"tagline":{"zh-TW":"居酒屋深夜完美的收尾之作！平底鍋或氣炸鍋輕鬆烤出金黃脆鍋巴。","en":"The ultimate Izakaya finale! Crisp golden rice crust effortlessly made on a skillet or air fryer.","ja":"飲んだ後の最高の締めくくり！フライパンやトースターで手軽におこげの極意。","ko":"이자카야 마무리의 정석! 프라이팬이나 에어프라이어로 바삭한 누룽지 주먹밥 완성.","th":"เมนูปิดท้ายมื้ออันดับหนึ่งของร้านอิซากายะ กรอบนอกนุ่มใน หอมกลิ่นกระทะ"},"heroImage":"/images/jp/yaki-onigiri-hero.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":12,"defaultServings":2,"caloriesPerServing":210,"category":"yakimono","dietaryTags":["classic","vegetarian","vegan"],"supportedCookware":["traditional","airFryer","oven"],"culture":{"originRegion":{"zh-TW":"日本全國・居酒屋與露營文化","en":"Izakayas & Festival Camps across Japan","ja":"日本全国の居酒屋・屋台","ko":"일본 전역의 이자카야","th":"ร้านอิซากายะและแคมป์ปิ้งทั่วประเทศญี่ปุ่น"},"famousYataiMarkets":[{"zh-TW":"東京新宿思出橫丁炭烤攤","en":"Omoide Yokocho Stalls, Shinjuku, Tokyo","ja":"新宿思い出横丁 焼きおにぎり","ko":"신주쿠 오모이데 요코초","th":"ตรอกโอโมอิเดะ ชินจูกุ โตเกียว"},{"zh-TW":"京都錦市場炭火小吃店","en":"Nishiki Market Skewer Stalls, Kyoto","ja":"京都錦市場","ko":"교토 니시키 시장","th":"ตลาดนิชิกิ เกียวโต"}],"historyStory":{"zh-TW":"烤飯糰源於古時日本農家在農忙或冬季時，將吃剩的冷米飯捏成三角形，塗抹味噌或醬油放在圍爐裏（Irori）木炭灰燼旁慢慢烘乾焙烤。外層結成一層脆硬芳香的鍋巴，防止飯糰在搬運中散碎，如今成為日本深夜居酒屋酒後暖胃的靈魂定番！","en":"Rooted in rural farming traditions of baking leftover rice over open hearths (Irori) with miso or soy sauce. The charred outer crust protected the soft rice core during travel.","ja":"囲炉裏の灰のそばで冷や飯を味噌や醤油で香ばしく焼いたのがルーツ。お酒を飲んだ後の「最後の締め」として不動の人気を誇ります。","ko":"화로 곁에서 찬밥에 된장이나 간장을 발라 구워 먹던 전통에서 유래하여 이자카야의 완벽한 마무리 메뉴로 자리 잡았습니다.","th":"มีต้นกำเนิดจากการนำข้าวที่เหลือมาย่างบนเตาผิงโบราณ ทาด้วยมิโซะหรือโชยุเพื่อให้เก็บได้นาน"},"japaneseKanji":"焼きおにぎり","japaneseKana":"やきおにぎり","japaneseRomaji":"Yaki Onigiri","audioPronunciationText":"焼きおにぎり","nativeName":"焼きおにぎり","nativePhonetics":"やきおにぎり"},"ingredients":[{"id":"rice","name":{"zh-TW":"煮熟的日本越光短圓米飯 (Warm Short-Grain Rice)","en":"Warm cooked Japanese short-grain rice","ja":"温かいご飯（コシヒカリなど）","ko":"따뜻한 밥 (고시히카리)","th":"ข้าวญี่ปุ่นหุงสุกอุ่นๆ"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz (approx 2 bowls)","isKeyFlavor":true,"japaneseKanji":"ご飯","japaneseKana":"ごはん","japaneseRomaji":"Gohan"},{"id":"shoyu","name":{"zh-TW":"濃口醬油 (Soy Sauce)","en":"Japanese Soy Sauce","ja":"濃口醤油","ko":"진간장","th":"โชยุญี่ปุ่น"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","isKeyFlavor":true,"japaneseKanji":"醤油","japaneseKana":"しょうゆ","japaneseRomaji":"Shōyu"},{"id":"mirin","name":{"zh-TW":"本味醂 (Hon Mirin)","en":"Hon-Mirin","ja":"本みりん","ko":"미림","th":"มิริน"},"amount":15,"unitMetric":"ml","unitUS":"1 tbsp","japaneseKanji":"本みりん","japaneseKana":"ほんみりん","japaneseRomaji":"Hon-Mirin"},{"id":"butter","name":{"zh-TW":"無鹽奶油 (Butter)","en":"Butter","ja":"バター","ko":"버터","th":"เนยสดจืด"},"amount":10,"unitMetric":"g","unitUS":"2 tsp","isKeyFlavor":true,"japaneseKanji":"バター","japaneseKana":"ばたー","japaneseRomaji":"Batā"},{"id":"hondashi","name":{"zh-TW":"烹大師鰹魚粉 (Hondashi Dashi Powder)","en":"Hondashi Dashi granules","ja":"ほんだし（だしの素）","ko":"혼다시 가루","th":"ผงซุปดาชิปลาแห้ง"},"amount":3,"unitMetric":"g","unitUS":"1/2 tsp","japaneseKanji":"だしの素","japaneseKana":"だしの素","japaneseRomaji":"Dashi no Moto"},{"id":"sesame-oil","name":{"zh-TW":"純黑芝麻油 (Toasted Sesame Oil)","en":"Sesame Oil","ja":"ごま油","ko":"참기름","th":"น้ำมันงา"},"amount":5,"unitMetric":"ml","unitUS":"1 tsp","japaneseKanji":"ごま油","japaneseKana":"ごまあぶら","japaneseRomaji":"Goma Abura"},{"id":"nori-sheets","name":{"zh-TW":"烘烤海苔片 (Crisp Nori Seaweed strips)","en":"Toasted Nori seaweed strips","ja":"焼き海苔","ko":"구운 김","th":"สาหร่ายแผ่นย่างกรอบ"},"amount":2,"unitMetric":"sheet","unitUS":"sheet","japaneseKanji":"焼き海苔","japaneseKana":"やきのり","japaneseRomaji":"Yaki Nori"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"拌入底味與緊密捏角 (Flavor & Pack Triangle)","en":"Mix Seasoning & Compress Triangle Onigiri","ja":"ご飯に鰹出汁とごま油を混ぜ、固めに三角に握る","ko":"밥에 다시가루와 참기름을 섞고 단단하게 삼각형으로 쥐기","th":"คลุกผงดาชิและน้ำมันงาในข้าว ปั้นสามเหลี่ยมให้แน่น"},"instruction":{"zh-TW":"在溫熱的白米飯中加入 1/2 茶匙烹大師高湯粉與少許黑麻油拌勻（讓飯粒內部帶有高湯底蘊）。雙手沾少許冷水與鹽，將米飯均勻分成 4 等份。雙手掌心成山字形，「緊密用力擠壓捏成厚實的三角形」（切記：烤飯糰必須比普通飯糰捏得更緊實，下鍋翻面時才絕不散碎！）。","en":"Mix warm rice with dashi powder and a few drops of sesame oil. Moisten hands with water and salt. Divide into 4 portions; press firmly into compact, dense triangles (must pack tighter than regular onigiri so they don’t crumble during grilling).","ja":"ご飯にだしの素とごま油を混ぜる。手に水と塩をつけ、ギュッと固めに三角形に握ります（しっかり固く握らないと焼く時に崩れるので注意！）。","ko":"밥에 다시가루와 참기름을 섞습니다. 손에 물과 소금을 묻히고 부서지지 않도록 평소보다 훨씬 단단하게 삼각형으로 쥐어줍니다.","th":"ผสมผงดาชิและน้ำมันงากับข้าวอุ่น ชุบมือด้วยน้ำเกลือ ปั้นเป็นรูปสามเหลี่ยมให้แน่นกว่าปกติเพื่อไม่ให้แตกตอนย่าง"},"durationSeconds":240,"image":"/images/jp/yaki-onigiri-step1.jpg","crucialTips":{"zh-TW":"「一定要捏得非常緊實」！鬆散的飯糰一下鍋遇到翻動立刻變成炒飯碎屑。","en":"Pack firmly! Loose onigiri will disintegrate into loose fried rice grains upon contact with the hot spatula.","ja":"【固くしっかり握る】：ふんわり握ると焼く時にボロボロ崩れます。両手で体重をかけてしっかり成形しましょう。","ko":"단단하게 뭉치지 않으면 뒤집을 때 밥알이 다 흩어져 볶음밥이 됩니다. 꼭꼭 쥐어주세요.","th":"ต้องปั้นให้แน่นกระชับ ไม่เช่นนั้นเวลาพลิกกลับด้านข้าวจะร่วงแตกกระจาย"}},{"stepNumber":2,"title":{"zh-TW":"乾烙雙面烤出硬殼鍋巴 (Dry Sear Rice Crust)","en":"Dry Sear until Rice Crust Forms","ja":"まずはタレを塗らずに素焼きし、表面に硬い膜を作る","ko":"양념 바르지 않고 구워 단단한 누룽지 막 만들기","th":"ย่างข้าวเปล่าโดยไม่ทาซอสจนผิวด้านนอกแข็งเป็นข้าวตัง"},"instruction":{"zh-TW":"平底不沾鍋抹極薄油，開中小火。將白米飯糰平排鍋中（暫時不要刷醬油！先刷醬會焦黑且不易形成硬殼）。乾烙烘烤約 3-4 分鐘至底面泛白硬化、結出一層堅固的硬米粒膜，翻面再烤 3 分鐘，側邊三個邊緣也豎立稍微烘乾。","en":"Heat a lightly greased non-stick skillet on medium-low. Place onigiri unglazed (brushing soy sauce too early burns the sugar without crisping). Sear for 3-4 mins until a rigid white crust forms; flip and sear 3 mins.","ja":"フライパンを弱めの中火で熱し、タレを塗らずに並べます。触らずに3〜4分、底面がカリッと白く固まるまで素焼きし、裏返して同様に焼きます。","ko":"팬에 양념 없이 주먹밥을 올리고 약불에서 3~4분간 겉면이 하얗고 단단하게 누룽지처럼 굳을 때까지 굽고 뒤집습니다.","th":"วางลงบนกระทะโดยยังไม่ทาซอส ย่างด้านละ 3-4 นาทีจนเม็ดข้าวรอบนอกแห้งเกรียมเป็นแผ่นข้าวตังแข็ง"},"durationSeconds":300,"image":"/images/jp/yaki-onigiri-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"氣炸鍋模式：190°C (375°F) 烤 10 分鐘，第 6 分鐘刷醬翻面","instructionOverride":{"zh-TW":"氣炸鍋鋪烘焙紙，將白飯糰以 190°C 乾氣炸 6 分鐘定型出硬殼，拉出兩面刷滿醬汁與奶油，再氣炸 4 分鐘至金黃酥脆！","en":"Air fry unglazed onigiri at 190°C for 6 mins to set the crust. Brush both sides with soy sauce and butter, air fry 4 more mins.","ja":"ノンフライヤー190℃でまず6分素焼き。取り出してタレとバターをたっぷり塗り、さらに4分香ばしく焼き上げます。","ko":"에어프라이어 190도에서 6분간 먼저 겉면을 굳힌 뒤, 소스와 버터를 발라 4분간 더 바삭하게 굽습니다.","th":"อบในหม้อทอดไร้น้ำมัน 190°C นาน 6 นาทีจนผิวนอกแข็ง นำออกมาทาซอสและเนย อบต่ออีก 4 นาที"}}]},{"stepNumber":3,"title":{"zh-TW":"反覆厚刷醬汁與奶油 (Brush Soy Sauce & Butter)","en":"Brush Tare Sauce & Sizzle with Butter","ja":"醤油ダレを塗り、バターを溶かして香ばしく焦がす","ko":"간장 타레 바르고 버터 녹여 불맛 입히기","th":"ทาซอสโชยุและละลายเนยย่างให้หอมกรุ่น"},"instruction":{"zh-TW":"在小碟中調合醬油、味醂與少許糖。用油刷將醬汁厚厚刷在烘硬的飯糰表面，翻面讓沾醬的那面朝下，立刻發出滋滋作響的焦糖香氣！煎 30 秒後，給另一面也刷上醬汁翻面。最後在鍋邊投入無鹽奶油融化，讓飯糰吸附一層濃郁的焦香奶油！","en":"Mix soy sauce, mirin, and sugar. Generously brush onto the hardened rice crust. Flip onto the sauced face, sizzling for 30s. Brush the reverse side, flip again. Melt butter into pan to infuse rich buttery aroma.","ja":"醤油、みりん、砂糖を合わせたタレをハケでたっぷり塗り、返して30秒。反対側にも塗って返します。最後にバターを投入して絡め、香ばしい醤油バター味に仕上げます。","ko":"간장, 미림, 설탕 소스를 붓으로 듬뿍 바르고 뒤집어 30초, 반대쪽도 바른 뒤 버터를 녹여 둘러줍니다.","th":"ทาซอสโชยุผสมมิรินลงบนผิวข้าวที่แข็งแล้ว พลิกย่าง 30 วินาที ทาอีกด้านพลิกซ้ำ ใส่เนยลงกระทะให้เคลือบหอม"},"durationSeconds":150,"image":"/images/jp/yaki-onigiri-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"裹上酥脆海苔起鍋 (Wrap Crisp Nori & Serve)","en":"Wrap in Crisp Nori & Serve Hot","ja":"パリパリの焼き海苔を巻いて完成","ko":"바삭한 구운 김을 둘러 완성","th":"ห่อด้วยสาหร่ายแผ่นย่างกรอบพร้อมเสิร์ฟ"},"instruction":{"zh-TW":"起鍋前將飯糰底部包上一片酥脆的長條烤海苔。拿在手中熱騰騰、咬破外層咔滋嘎吱作響的黃金醬油鍋巴，內部鬆軟米飯夾帶著淡淡高湯甜香，簡單卻無比震撼！","en":"Wrap the base with a crisp toasted nori strip. Hold while steaming hot; crunch through the crackly soy-butter rice crust into the fluffy fragrant center!","ja":"熱いうちにパリパリの焼き海苔を巻いて完成！おこげの香ばしさとバター醤油のコクがたまらない、居酒屋の大満足グルメ。","ko":"바삭한 김을 감싸 완성합니다. 겉은 바삭한 누룽지, 속은 부드러운 밥알의 식감을 뜨거울 때 즐기세요!","th":"พันด้วยสาหร่ายย่างกรอบที่ก้น กัดคำแรกสัมผัสความกรอบกร๊วบของข้าวตังโชยุเนยและข้าวเนื้อนุ่มหอมด้านใน"},"durationSeconds":30,"image":"/images/jp/yaki-onigiri-step4.jpg"}],"troubleshooting":[{"id":"trouble-onigiri-1","problem":{"zh-TW":"一刷上醬油，飯糰立刻碎開散落成一地？","en":"Why did the rice ball crumble apart as soon as soy sauce was brushed on?","ja":"醤油を塗った瞬間にご飯が崩れてバラバラになってしまいました。","ko":"간장을 바르자마자 밥알이 다 흩어지고 부서졌어요.","th":"ทำไมพอทาโชยุแล้วข้าวปั้นแตกกระจายไม่เป็นก้อน?"},"cause":{"zh-TW":"乾烙時間不夠長、米粒表面尚未形成硬硬的保護殼就急著刷醬，醬汁的水分讓米飯鬆脫。","en":"Brushed soy sauce before a hardened rice crust formed. Liquid dissolved the starch bond.","ja":"素焼きが不十分で表面が固まる前に水分（醤油）を塗ってしまったため。","ko":"초벌구이로 겉면 누룽지가 충분히 굳기 전에 액체 소스를 발라 밥알이 풀렸기 때문입니다.","th":"ย่างข้าวเปล่าไม่นานพอ ผิวยังไม่แข็งเป็นข้าวตัง เมื่อโดนของเหลวจะทำให้ข้าวคลายตัวแตก"},"solution":{"zh-TW":"耐心乾烤至少 3-4 分鐘，用鏟子輕敲感覺「硬邦邦如薄殼」時，才能刷醬！","en":"Patience is key: Sear dry for full 3-4 mins until tapping sounds crisp and firm before glazing.","ja":"フライ返しでトントンと叩いて「カチッ」と硬い音がするまでしっかり素焼きしてから塗りましょう。","ko":"뒤집개로 톡톡 쳤을 때 딱딱한 소리가 날 정도로 누룽지가 생긴 후에 소스를 바르세요.","th":"ต้องย่างข้าวเปล่าจนใช้ตะหลิวเคาะแล้วมีเสียงกรอบแข็ง จึงค่อยเริ่มทาซอส"}}],"proTips":[{"zh-TW":"【加少許味醂提升光澤與脆度】：純醬油容易過鹹且易焦黑，調合 1/3 的味醂，味醂中的天然糖分能讓表面形成一層漂亮的焦糖硬化玻璃膜，酥度翻倍！","en":"Always blend soy sauce with mirin (2:1 ratio). Mirin sugars caramelize into a shiny, glass-like crackly glaze.","ja":"【醤油＋みりんの黄金比】：醤油だけで焼くと焦げやすく塩辛くなります。みりんを加えることで綺麗な照りと香ばしい飴状のおこげができます。","ko":"간장만 쓰면 짜고 타기 쉽습니다. 미림을 섞으면 윤기 나는 캐러멜 코팅이 형성되어 훨씬 바삭해집니다.","th":"ผสมโชยุกระเทียมกับมิริน น้ำตาลในมิรินจะช่วยเคลือบผิวข้าวให้เงางามและกรอบขึ้นเป็นทวีคูณ"}]},{"country":"jp","id":"japanese-curry","slug":"rich-japanese-beef-curry","title":{"zh-TW":"極濃日式牛肉黑咖哩","en":"Rich Japanese Beef Curry Rice","ja":"洋食屋仕込み 濃厚熟成ビーフカレー","ko":"양식당 비법 농후 숙성 비프 카레","th":"แกงกะหรี่เนื้อสไตล์ญี่ปุ่นเข้มข้น"},"subtitle":{"zh-TW":"焦糖焦化洋蔥基底、慢燉牛肋條軟爛入味、蘋果蜂蜜甘醇隱味","en":"Caramelized onion base, meltingly tender beef chuck, infused with grated apple and dark chocolate","ja":"飴色玉ねぎの深いコク！じっくり煮込んだホロホロ牛肉とすりおろしリンゴの隠し味","ko":"갈색 양파의 깊은 풍미와 부드럽게 부서지는 소고기, 사과와 초콜릿의 특급 비밀","th":"เคี่ยวหอมใหญ่จนเป็นสีคาราเมล เนื้อวัวตุ๋นเปื่อยนุ่มละลาย แอปเปิ้ลขูดและน้ำผึ้ง"},"tagline":{"zh-TW":"日本國民最愛家庭與屋台靈魂暖心料理！解鎖 3 種日式大廚秘密隱味。","en":"Japan’s premier national comfort dish. Unlock the 3 secret umami boosters.","ja":"国民的人気メニュー！一晩寝かせたような深いコクを生み出す隠し味テクニック。","ko":"일본 국민들이 가장 사랑하는 힐링 푸드! 하루 숙성한 듯 깊은 맛의 비법.","th":"อาหารยอดนิยมประจำชาติญี่ปุ่น เคล็ดลับเพิ่มรสอูมามิด้วยวัตถุดิบลับ 3 ชนิด"},"heroImage":"/images/jp/japanese-curry-hero.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":45,"defaultServings":4,"caloriesPerServing":580,"category":"nimono","dietaryTags":["classic","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"神奈川縣橫須賀市 (Yokosuka, Kanagawa)","en":"Yokosuka Naval Base, Kanagawa","ja":"神奈川県横須賀市（海軍カレー発祥の地）","ko":"가나가와현 요코스카시 (해군 카레의 발상지)","th":"เมืองโยโกสุกะ จังหวัดคานากาวะ"},"famousYataiMarkets":[{"zh-TW":"橫須賀海軍咖哩街","en":"Yokosuka Kaigun Curry Street, Kanagawa","ja":"横須賀海軍カレー本舗","ko":"요코스카 해군 카레 거리","th":"ถนนแกงกะหรี่ทหารเรือ โยโกสุกะ"},{"zh-TW":"大阪難波自由軒百年名物咖哩","en":"Jiyuken Famous Curry, Namba, Osaka","ja":"大阪難波 自由軒名物カレー","ko":"오사카 난바 지유켄 카레","th":"ร้านจิยูเกน นัมบะ โอซาก้า"}],"historyStory":{"zh-TW":"明治時期日本帝國海軍借鑒英國皇家海軍的牛肉濃湯，結合印度香料與小麥粉炒製成濃稠濃郁的日式咖哩，澆在白米飯上防止士兵因暈船灑翻，並固定每週五供應（防止海軍在茫茫大海中喪失星期觀念）。昭和時代普及至日本家家戶戶，演變為融合蘋果泥、蜂蜜與高湯的日式獨創滋味！","en":"Introduced to Japan via the Royal Navy in the Meiji era, thickened with a flour roux so it wouldn’t spill on rolling seas. Fixed as the Friday naval meal, it evolved into Japan’s #1 home comfort food.","ja":"明治時代、日本海軍がイギリス海軍のカレーシチューを改良し、揺れる船上でもこぼれないよう小麦粉でとろみをつけたのが発祥。金曜日に食べる習慣は今も海上自衛隊に続いています。","ko":"메이지 시대 해군에서 흔들리는 배 위에서 쏟아지지 않도록 걸쭉하게 만들어 밥과 함께 먹던 것에서 유래했습니다.","th":"กองทัพเรือญี่ปุ่นนำสูตรมาจากราชนาวีอังกฤษ ปรับให้ข้นเพื่อไม่ให้หกเวลากลางทะเล"},"japaneseKanji":"日本のカレーライス","japaneseKana":"にほんのかれーらいす","japaneseRomaji":"Nihon no Karē Raisu","audioPronunciationText":"カレーライス","nativeName":"日本のカレーライス","nativePhonetics":"にほんのかれーらいす"},"ingredients":[{"id":"beef-chuck","name":{"zh-TW":"牛肋條或牛肩肉塊 (Beef Chuck or Short Rib cut into 3cm cubes)","en":"Beef chuck or boneless short rib, cut into cubes","ja":"牛すね肉または牛バラ角切り肉","ko":"소고기 양지 또는 사태 깍둑썰기","th":"เนื้อวัวส่วนสะโพกหรือเนื้อติดมันหั่นเต๋า 3 ซม."},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"japaneseKanji":"牛肉角切り","japaneseKana":"ぎゅうにくかくぎり","japaneseRomaji":"Gyūniku Kakugiri"},{"id":"onions","name":{"zh-TW":"洋蔥薄絲 (Thinly sliced yellow onions - for caramelization)","en":"Yellow onions, thinly sliced","ja":"玉ねぎ（薄切り・飴色炒め用）","ko":"얇게 채 썬 양파 (캐러멜라이징용)","th":"หอมใหญ่ซอยบางสำหรับผัดคาราเมล"},"amount":300,"unitMetric":"g","unitUS":"2 large onions","isKeyFlavor":true,"japaneseKanji":"玉ねぎ","japaneseKana":"たまねぎ","japaneseRomaji":"Tamanegi"},{"id":"carrots-potatoes","name":{"zh-TW":"胡蘿蔔與馬鈴薯滾刀塊 (Carrots & Potatoes)","en":"Carrots and potatoes, cut into bite-sized chunks","ja":"にんじん・じゃがいも（乱切り）","ko":"당근과 감자 큼직하게 썬 것","th":"แครอทและมันฝรั่งหั่นชิ้นพอดีคำ"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","japaneseKanji":"人参・じゃがいも","japaneseKana":"にんじん・じゃがいも","japaneseRomaji":"Ninjin / Jagaimo"},{"id":"curry-roux","name":{"zh-TW":"日式咖哩塊 (Japanese Curry Roux Blocks - e.g. S&B Golden or Vermont)","en":"Japanese Curry Roux blocks (Medium Hot)","ja":"市販のカレールー（中辛または辛口）","ko":"일본 고형 카레 (골든카레 또는 바몬드카레)","th":"ก้อนแกงกะหรี่ญี่ปุ่นสำเร็จรูป"},"amount":100,"unitMetric":"g","unitUS":"1/2 pack (4-5 cubes)","isKeyFlavor":true,"japaneseKanji":"カレールー","japaneseKana":"かれーるー","japaneseRomaji":"Karē Rū"},{"id":"grated-apple","name":{"zh-TW":"現磨蘋果泥 (Grated Fresh Sweet Apple)","en":"Freshly grated Fuji apple (Secret booster)","ja":"すりおろしリンゴ（隠し味）","ko":"갈아 넣은 사과","th":"แอปเปิ้ลขูดละเอียด (เคล็ดลับความหวาน)"},"amount":60,"unitMetric":"g","unitUS":"1/4 cup","isKeyFlavor":true,"japaneseKanji":"すりおろしリンゴ","japaneseKana":"すりおろしりんご","japaneseRomaji":"Surioroshi Ringo"},{"id":"dark-chocolate-or-coffee","name":{"zh-TW":"黑巧克力 1 塊或即溶黑咖啡 1/2 茶匙 (Dark Chocolate/Coffee)","en":"1 square dark chocolate (or 1/2 tsp instant coffee)","ja":"ビターチョコレート1片（またはインスタントコーヒー少々）","ko":"다크 초콜릿 1조각 (또는 인스턴트 블랙커피 약간)","th":"ดาร์กช็อกโกแลต 1 ชิ้น หรือผงกาแฟดำ"},"amount":10,"unitMetric":"g","unitUS":"1 piece","isKeyFlavor":true,"japaneseKanji":"チョコレート","japaneseKana":"ちょこれーと","japaneseRomaji":"Chokorēto"},{"id":"water-or-broth","name":{"zh-TW":"清水或高湯 (Water or Dashi)","en":"Water or light dashi broth","ja":"水または出汁","ko":"물 또는 육수","th":"น้ำเปล่าหรือน้ำซุปดาชิ"},"amount":800,"unitMetric":"ml","unitUS":"3.4 cups","japaneseKanji":"水","japaneseKana":"みず","japaneseRomaji":"Mizu"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"耐性炒出琥珀焦糖洋蔥 (Caramelize Onions)","en":"Slow Caramelize Sliced Onions","ja":"玉ねぎを弱火でじっくり飴色になるまで炒める","ko":"양파를 갈색(아메이로)이 될 때까지 정성껏 볶기","th":"ผัดหอมใหญ่ด้วยไฟอ่อนจนเป็นสีน้ำตาลคาราเมล"},"instruction":{"zh-TW":"深燉鍋中加 1 大匙油與少許奶油，放入薄切洋蔥絲。中小火翻炒，耐心地炒約 15-20 分鐘，直到洋蔥體積縮小至 1/4、散發濃郁天然糖焦香、色澤轉為深琥珀金棕色（飴色玉ねぎ，這是日式洋食咖哩厚重底蘊的第一靈魂！）。","en":"In a heavy pot, heat oil and butter. Sauté sliced onions over medium-low heat for 15-20 mins until reduced to 1/4 volume, deep golden brown and fragrant with rich natural sweetness.","ja":"深鍋に油とバターを熱し、玉ねぎを投入。弱火で15〜20分じっくり炒め、水分を飛ばして芳醇な「飴色玉ねぎ」を作ります（プロのコクの源泉泉）。","ko":"냄비에 기름과 버터를 두르고 양파를 약불에서 15~20분간 캐러멜 색이 될 때까지 볶아줍니다 (카레의 감칠맛을 결정하는 핵심).","th":"ผัดหอมใหญ่กับเนยด้วยไฟอ่อน 15-20 นาทีจนยุบตัวและเปลี่ยนเป็นสีน้ำตาลคาราเมลหอมหวาน"},"durationSeconds":1200,"image":"/images/jp/japanese-curry-step1.jpg","crucialTips":{"zh-TW":"洋蔥炒成「飴色」能去除洋蔥辛辣，轉化為不可思議的水果般焦糖甘甜，決定了咖哩的深度！","en":"Caramelizing onions builds deep umami sugars that cannot be replicated by commercial roux cubes alone.","ja":"【飴色玉ねぎをケチらない】：焦がさないように少しずつ水を足しながら炒めると早く綺麗な飴色になります。","ko":"양파를 볶을 때 물을 한 스푼씩 둘러가며 볶으면 타지 않고 빠르게 갈색으로 변합니다.","th":"การผัดหอมใหญ่จนเป็นสีคาราเมลจะให้ความหวานกลมกล่อมล้ำลึกที่ผงกะหรี่ทั่วไปไม่มี"}},{"stepNumber":2,"title":{"zh-TW":"煎香牛肉與根莖蔬菜 (Sear Beef & Root Veggies)","en":"Brown Beef & Sauté Carrots and Potatoes","ja":"牛肉の表面を焼き固め、根菜を加えて炒める","ko":"소고기 겉면 굽고 당근, 감자 함께 볶기","th":"นำเนื้อวัวลงผัดให้เกรียมหอมแล้วตามด้วยแครอทและมันฝรั่ง"},"instruction":{"zh-TW":"將牛肉塊放入鍋中，轉中大火將四面煎至微焦黃鎖住肉汁。隨後加入胡蘿蔔與馬鈴薯滾刀塊，翻炒 2 分鐘讓蔬菜表面裹上一層牛油香氣。","en":"Add beef chunks to the pot; sear on high heat until browned on all sides. Toss in carrots and potatoes, stirring for 2 mins to coat in beef fat aromatics.","ja":"牛肉を加え、強火で表面をこんがり焼き付けて旨味を閉じ込める。にんじんとじゃがいもを加え、サッと油が回るまで炒め合わせます。","ko":"소고기를 넣고 센 불에서 겉면을 노릇하게 시어링한 뒤, 당근과 감자를 넣고 2분간 볶아 기름을 입힙니다.","th":"ใส่เนื้อวัวลงไปย่างไฟแรงให้ผิวด้านนอกเกรียมหอม ใส่แครอทและมันฝรั่งผัดให้เคลือบน้ำมันเนื้อ"},"durationSeconds":240,"image":"/images/jp/japanese-curry-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"注水慢燉至肉質軟爛 (Simmer until Melting Tender)","en":"Simmer with Lid for 25 Mins","ja":"水を注ぎ、アクを取りながら弱火で25分コトコト煮る","ko":"물을 붓고 거품 걷어가며 25분간 은근히 끓이기","th":"เติมน้ำ ช้อนฟองทิ้ง และเคี่ยวไฟอ่อน 25 นาที"},"instruction":{"zh-TW":"注入 800ml 清水或高湯，大火煮沸。用湯勺仔細撈除湯面上泛起的所有灰色浮沫雜質。轉微小火，蓋上鍋蓋慢燉 25-30 分鐘，直到牛肉用筷子能輕易穿透、蔬菜軟稔。","en":"Pour in 800ml water or dashi. Bring to a rolling boil and skim off all grey foam. Cover and simmer on low for 25-30 mins until beef is fork-tender.","ja":"水800mlを注ぎ、沸騰したらアクを丁寧にすくい取る。フタをして極弱火で25〜30分、肉がホロリと柔らかくなるまで煮込みます。","ko":"물 800ml를 붓고 끓으면 떠오르는 거품을 걷어냅니다. 뚜껑 덮고 약불에서 25~30분간 고기가 부드러워질 때까지 푹 끓입니다.","th":"เทน้ำ 800 มล. ลงไป ต้มจนเดือด ช้อนฟองทิ้ง ปิดฝาเคี่ยวไฟอ่อน 25-30 นาทีจนเนื้อเปื่อยนุ่ม"},"durationSeconds":1500,"image":"/images/jp/japanese-curry-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"關火融化咖哩塊 (Melt Curry Roux Off Heat)","en":"Turn Off Heat & Dissolve Curry Roux","ja":"必ず「火を止めて」カレールーを割り入れ溶かす","ko":"반드시 ‘불을 끄고’ 고형 카레를 풀어 녹이기","th":"ต้อง \"ปิดไฟก่อน\" แล้วใส่ก้อนแกงกะหรี่ลงไปคนให้ละลาย"},"instruction":{"zh-TW":"【核心操作】：關火！將咖哩塊掰開成小格，放入大勺中浸入熱湯輕輕攪散融化（開火時放咖哩塊極易結死塊！關火才能均勻乳化）。攪勻至完全化開無粉粒後，重新開最小火微煮 5 分鐘收濃。","en":"CRITICAL: Turn off heat completely! Break roux blocks into a ladle, submerge in hot broth, and stir until completely dissolved before turning heat back to low for 5 mins.","ja":"【最重要ルール】：必ず火を止めること！火を止めてルーを溶かすことでダマにならず綺麗にとろみがつきます。溶けたら弱火で5分煮詰めます。","ko":"핵심 규칙: 불을 반드시 끄세요! 불을 끄고 국물에 카레를 풀어야 멍울 없이 곱게 녹습니다. 완전히 녹인 뒤 약불로 5분간 끓입니다.","th":"กฎเหล็ก: ต้องปิดไฟก่อนเสมอ นำก้อนแกงกะหรี่ใส่กระบวยจุ่มน้ำซุปคนให้ละลายจนหมด จึงเปิดไฟอ่อนเคี่ยวต่อ 5 นาที"},"durationSeconds":300,"image":"/images/jp/japanese-curry-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"加入大廚隱味與澆飯 (Add Secret Umami & Serve)","en":"Fold in Secret Boosters & Ladle over Rice","ja":"すりおろしリンゴとチョコを投入、ご飯にかけて完成","ko":"갈아 넣은 사과와 초콜릿을 넣고 밥 위에 듬뿍 얹기","th":"ใส่แอปเปิ้ลขูดและช็อกโกแลต ราดบนข้าวสวยร้อนๆ"},"instruction":{"zh-TW":"最後起鍋前，拌入現磨蘋果泥、蜂蜜 1 茶匙、以及 1 小塊黑巧克力（或少許黑咖啡）！巧克力與蘋果會帶來深沉黑潤的光澤、迷人的微苦果酸與多層次回甘。深盤盛入熱白飯，豪邁澆上濃稠黑咖哩，一口入魂！","en":"Stir in grated apple, 1 tsp honey, and 1 square dark chocolate (or pinch of instant coffee). The chocolate imparts a deep obsidian shine and complex velvet richness. Ladle generously over hot rice and enjoy!","ja":"仕上げにすりおろしリンゴとビターチョコを投入して混ぜます。コクとツヤが劇的に深まります！アツアツのご飯にたっぷりかけて召し上がれ。","ko":"마지막에 사과즙과 다크 초콜릿 1조각을 넣고 섞어줍니다. 깊은 초콜릿빛 윤기와 환상적인 감칠맛이 완성됩니다. 밥 위에 듬뿍 얹어 즐기세요!","th":"ใส่แอปเปิ้ลขูด น้ำผึ้ง และดาร์กช็อกโกแลต 1 ชิ้น ช็อกโกแลตจะทำให้สีเข้มสวยและรสชาติหวานลุ่มลึก ราดบนข้าวสวยร้อนๆ พร้อมเสิร์ฟ"},"durationSeconds":120,"image":"/images/jp/japanese-curry-step5.jpg"}],"troubleshooting":[{"id":"trouble-curry-1","problem":{"zh-TW":"為什麼咖哩塊很難融化，在湯裡結成一坨坨粉塊？","en":"Why didn’t the curry roux melt, clumping into powdery lumps?","ja":"ルーが溶け残って塊（ダマ）になってしまいました。","ko":"카레 덩어리가 풀리지 않고 뭉쳐 있어요.","th":"ทำไมก้อนแกงกะหรี่ไม่ละลาย กลายเป็นก้อนแป้งอยู่ในหม้อ?"},"cause":{"zh-TW":"在水沸騰翻滾時直接把咖哩塊丟進鍋中，高溫使外層澱粉瞬間膠化結膜，阻隔熱水進入核心。","en":"Dropped roux directly into boiling water; starch immediately gelatinized the outer shell into an impermeable ball.","ja":"沸騰した鍋にそのままルーを投入したため、表面のデンプンが固まって中まで溶けなくなったため。","ko":"팔팔 끓는 국물에 바로 넣었기 때문에 겉면 전분이 먼저 굳어버려 속이 풀리지 않은 것입니다.","th":"ใส่ก้อนแกงกะหรี่ลงไปขณะที่น้ำเดือดพล่าน ความร้อนจะทำให้แป้งด้านนอกเคลือบแข็งด้านในไม่ละลาย"},"solution":{"zh-TW":"絕對要「先關火」等待水面平靜，把咖哩塊掰碎放在大湯勺中浸入湯汁慢慢化開！","en":"Always turn off heat completely. Dissolve roux in a soup ladle submerged in hot liquid before stirring into the pot.","ja":"必ず火を止めてから、お玉の中でスープに浸して溶かしてから全体に混ぜましょう。","ko":"반드시 불을 끈 뒤, 국자에 국물을 떠서 카레 조각을 담가 천천히 으깨며 녹이세요.","th":"ต้องปิดไฟก่อนทุกครั้ง วางก้อนแกงกะหรี่ในกระบวยจุ่มน้ำร้อนแล้วค่อยๆ บี้ให้ละลาย"}}],"proTips":[{"zh-TW":"【黑巧克力與即溶咖啡的黑魔法】：日式老舖洋食館的招牌「黑咖哩」，最大秘密就是加入微量無糖黑巧克力或黑咖啡粉，其中的可可多酚與焦苦香氣，能瞬間將市售普通咖哩塊昇華為耗時熬製三天的深邃熟成風味！","en":"Old-school Yoshoku chefs swear by dark chocolate or a pinch of instant coffee. Cocoa polyphenols mimic days of slow cellar maturation instantly.","ja":"【チョコとコーヒーの隠し味】：洋食屋のブラックカレーの秘密はこれ！少量のカカオ成分が、数日寝かせたような深いコクと芳醇な苦味を生みます。","ko":"다크 초콜릿이나 인스턴트 커피 약간을 넣으면 며칠 동안 푹 끓여 숙성시킨 듯한 깊은 불맛과 윤기를 냅니다.","th":"การใส่ดาร์กช็อกโกแลตหรือกาแฟดำเล็กน้อย จะช่วยจำลองรสชาติแกงกะหรี่ที่เคี่ยวบ่มข้ามคืนอย่างน่าอัศจรรย์"}]},{"country":"jp","id":"tsukune","slug":"japanese-tsukune-chicken-meatballs","title":{"zh-TW":"日式醬烤雞肉丸 (Tsukune)","en":"Japanese Tsukune Skewers","ja":"焼き鳥 つくね (卵黄添え)","ko":"일본식 닭고기 완자 츠쿠네","th":"ซึคุเนะ ไก่บดเสียบไม้ย่างซอสทาเระ"},"subtitle":{"zh-TW":"居酒屋與夜市串燒霸主！混入雞軟骨脆感，刷上濃郁甜鹹醬汁，蘸溫泉蛋黃一口爆汁","en":"Izakaya & Yatai skewers made with minced chicken, crunch of cartilege, basted in sweet tare, served with raw egg yolk","ja":"なんこつのコリコリ感と甘辛タレが絶品。卵黄をたっぷり絡めて食べる屋台の定番串","ko":"이자카야 인기 꼬치구이! 달콤짭짤한 타레 소스와 부드러운 노른자의 환상 궁합","th":"ไก่บดปรุงรสเสียบไม้ย่าง ทาซอสทาเระหอมกรุ่น จิ้มไข่แดงเยิ้มๆ อร่อยสไตล์อิซากายะ"},"tagline":{"zh-TW":"一口丸子、一口生蛋黃，焦香醇厚的深夜食堂","en":"Juicy glazed meatballs dipped in rich golden egg yolk","ja":"タレの香ばしさと濃厚な黄身の贅沢な一口","ko":"노른자에 푹 찍어 먹는 촉촉한 닭완자 구이","th":"ไก่ปิ้งซอสหวานเค็ม จุ่มไข่แดงมันๆ ฟินทุกคำ"},"heroImage":"/images/jp/tsukune-hero.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":12,"defaultServings":2,"caloriesPerServing":380,"category":"yakimono","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer","oven"],"culture":{"originRegion":{"zh-TW":"東京都 新宿思い出橫丁 / 博多屋台","en":"Tokyo Omoide Yokocho / Hakata Yatais","ja":"東京都 新宿思い出横丁 / 博多中洲屋台","ko":"도쿄 신주쿠 오모이데 요코초 / 하카타 포장마차","th":"โตเกียว โอโมอิเดะ โยโกโช / ฮากาตะ"},"famousYataiMarkets":[{"zh-TW":"新宿思い出橫丁","en":"Omoide Yokocho","ja":"思い出横丁","ko":"오모이데 요코초","th":"โอโมอิเดะ โยโกโช"},{"zh-TW":"福岡中洲屋台街","en":"Nakasu Yatai Street","ja":"中洲屋台街","ko":"나카스 야타이 거리","th":"ย่านยาไต นาคาสึ"}],"historyStory":{"zh-TW":"Tsukune 源自日語「つくねる (捏、揉成團)」。將雞肉絞肉揉入薑汁、蔥花與切碎的雞軟骨，用竹籤串起炭火翻烤。其靈魂在於浸潤了數十年老滷汁的甜鹹「Tare」醬，最後一定要配上一顆金黃生食級蛋黃，脂香與蛋香在舌尖融化。","en":"Derived from the Japanese verb \"tsukuneru\" meaning to knead by hand. Minced chicken is combined with grated ginger, scallions, and finely chopped cartilage for crunch, then grilled over charcoal. The hallmark is basting with rich sweet tare sauce and dipping into fresh pasteurized egg yolk.","ja":"「手でこねて丸める」ことからその名がついたつくね。軟骨の食感とネギ・生姜の風味を効かせた肉だねを、代々受け継がれた秘伝タレに潜らせて焼き上げます。濃厚な卵黄をたっぷり絡めて食べるのが最高の贅沢です。","ko":"손으로 빚어 둥글게 만든다는 의미의 츠쿠네. 닭연골을 다져 넣어 씹는 맛을 살리고 특제 타레 소스를 덧발라 구워냅니다. 신선한 계란 노른자에 푹 찍어 먹으면 고소함이 배가됩니다.","th":"ซึคุเนะ มีความหมายว่าการปั้นด้วยมือ เป็นไก่บดผสมขิง ต้นหอม และกระดูกอ่อนไก่กรุบกรอบ เสียบไม้ย่างบนเตาถ่าน ทาซอสทาเระรสเข้มข้น และจิ้มไข่แดงสดเพื่อความนุ่มละมุน"},"japaneseKanji":"焼き鳥 軟骨つくね","japaneseKana":"やきとり なんこつつくね","japaneseRomaji":"Yakitori Tsukune","audioPronunciationText":"つくね","nativeName":"焼き鳥 軟骨つくね","nativePhonetics":"やきとり なんこつつくね"},"ingredients":[{"id":"ground-chicken","name":{"zh-TW":"雞絞肉 (腿肉與胸肉混合)","en":"Ground Chicken (thigh & breast mix)","ja":"鶏ひき肉 (もも・むね合挽き)","ko":"다진 닭고기","th":"เนื้อไก่บด"},"amount":350,"unitMetric":"g","unitUS":"oz","japaneseKanji":"鶏ひき肉","japaneseKana":"とりひきにく","japaneseRomaji":"Tori Hikiniku"},{"id":"chicken-cartilage","name":{"zh-TW":"雞軟骨 (細切，增加脆爽口感)","en":"Chicken Cartilage (finely minced for crunch)","ja":"鶏軟骨 (みじん切り)","ko":"닭연골 (다진 것)","th":"กระดูกอ่อนไก่สับละเอียด"},"amount":50,"unitMetric":"g","unitUS":"oz","isKeyFlavor":true,"japaneseKanji":"鶏なんこつ","japaneseKana":"とりなんこつ","japaneseRomaji":"Tori Nankotsu","substitute":{"substituteName":{"zh-TW":"細碎杏鮑菇或荸薺","en":"Finely minced king oyster mushroom or water chestnut","ja":"エリンギのみじん切り / クワイ","ko":"다진 새송이버섯 또는 물밤","th":"เห็ดออรินจิสับหรือแห้ว"},"ratio":"1:1","explanation":{"zh-TW":"如果買不到雞軟骨，可用切得極碎的生荸薺或杏鮑菇丁代替，同樣能營造出清脆咬感。","en":"If chicken cartilage is unavailable, finely minced water chestnuts or firm mushrooms mimic the delightful crunchy texture.","ja":"軟骨が手に入らない場合は、エリンギやレンコンを細かく刻んで入れると良い食感になります。","ko":"닭연골이 없으면 잘게 썬 연근이나 새송이버섯으로 아삭한 식감을 낼 수 있습니다.","th":"หากไม่มีกระดูกอ่อนไก่ สามารถใช้แห้วหรือเห็ดออรินจิสับละเอียดแทนได้"},"whereToBuy":{"zh-TW":"一般超市蔬菜區","en":"Supermarket produce section","ja":"スーパーの野菜売り場","ko":"동네 마트 채소 코너","th":"ซูเปอร์มาร์เก็ตทั่วไป"}}},{"id":"scallions-tsukune","name":{"zh-TW":"青蔥 (切碎)","en":"Scallions (finely chopped)","ja":"長ねぎ / 青ねぎ (みじん切り)","ko":"대파 (다진 것)","th":"ต้นหอมซอย"},"amount":3,"unitMetric":"tbsp","unitUS":"tbsp","japaneseKanji":"長ねぎ","japaneseKana":"ながねぎ","japaneseRomaji":"Naganegi"},{"id":"ginger-paste","name":{"zh-TW":"生薑泥","en":"Grated Fresh Ginger","ja":"おろし生姜","ko":"간 생강","th":"ขิงขูดละเอียด"},"amount":1,"unitMetric":"tsp","unitUS":"tsp","japaneseKanji":"生姜","japaneseKana":"しょうが","japaneseRomaji":"Shoga"},{"id":"tare-sauce","name":{"zh-TW":"特調醬汁 (醬油3勺、味醂3勺、清酒2勺、糖1.5勺熬稠)","en":"Yakitori Tare (Soy sauce, mirin, sake, sugar reduced)","ja":"焼き鳥の甘辛秘伝タレ","ko":"야키토리 타레 소스","th":"ซอสทาเระปรุงรส"},"amount":60,"unitMetric":"ml","unitUS":"fl oz","isKeyFlavor":true,"japaneseKanji":"焼き鳥のタレ","japaneseKana":"やきとりのたれ","japaneseRomaji":"Yakitori no Tare"},{"id":"egg-yolk","name":{"zh-TW":"生食級新鮮蛋黃 (蘸食用)","en":"Pasteurized Fresh Egg Yolks (for dipping)","ja":"生食用の新鮮な卵黄","ko":"신선한 달걀 노른자","th":"ไข่แดงสด (เกรดทานสดได้)"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"japaneseKanji":"卵黄","japaneseKana":"らんおう","japaneseRomaji":"Ran-ou"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"製作肉餡與起膠","en":"Mix and Knead the Chicken Paste","ja":"ひき肉をこねて粘りを出す","ko":"닭고기 반죽 치대기","th":"นวดเนื้อไก่ให้เหนียวนุ่ม"},"instruction":{"zh-TW":"大碗中放入雞絞肉、碎雞軟骨、蔥花、薑泥、半小匙鹽與一小匙太白粉。順同方向用力攪拌揉捏約3分鐘，直到肉餡出筋起白膠質。","en":"Combine minced chicken, cartilage, scallions, ginger, pinch of salt, and potato starch in a bowl. Knead vigorously in one direction for 3 minutes until pale and sticky.","ja":"ボウルにひき肉、刻んだ軟骨、ネギ、生姜、塩、片栗粉を入れ、粘りが出るまでしっかりと手早く練り合わせます。","ko":"볼에 다진 닭고기, 연골, 파, 생강, 소금, 전분을 넣고 끈기가 생길 때까지 한 방향으로 세게 치대줍니다.","th":"ใส่ไก่บด กระดูกอ่อน ต้นหอม ขิง เกลือ และแป้งมันลงในชาม นวดไปในทิศทางเดียวกัน 3 นาทีจนเหนียวข้น"},"image":"/images/jp/tsukune-step1.jpg","durationSeconds":180,"crucialTips":{"zh-TW":"一定要冷肉手打！如果肉太溫，油脂會融化，丸子烤好會變柴。","en":"Keep meat cold while kneading to maintain emulsion and juiciness.","ja":"肉ダネが温まらないよう手早く練ることでジューシーに仕上がります。","ko":"고기가 미지근해지지 않게 차가운 상태에서 빠르게 치대야 육즙이 보존됩니다.","th":"ควรนวดในขณะที่เนื้อไก่ยังเย็นอยู่ เพื่อคงความชุ่มฉ่ำของเนื้อ"}},{"stepNumber":2,"title":{"zh-TW":"捏成棒狀並穿籤","en":"Shape into Oval Patties and Skewer","ja":"長楕円形に成形して串に刺す","ko":"타원형으로 빚어 꼬치에 꽂기","th":"ปั้นเป็นทรงรีแล้วเสียบไม้"},"instruction":{"zh-TW":"雙手沾少量水或食用油，抓取約60g肉餡揉成棒槌型橢圓丸子，插入泡過水防焦的扁平竹籤，拍打排氣。","en":"Moisten hands with water or oil. Shape 60g portions into elongated oval logs and thread onto pre-soaked flat bamboo skewers.","ja":"手に軽く油または水をつけ、肉だねを細長い俵型にまとめ、平串にしっかりと刺します。","ko":"손에 물이나 기름을 바르고 타원형으로 빚어 물에 적셔둔 대나무 꼬치에 단단히 꽂아줍니다.","th":"แตะมือด้วยน้ำหรือน้ำมันเล็กน้อย ปั้นไก่บดเป็นแท่งรีแล้วเสียบไม้แบนที่แช่น้ำไว้"},"image":"/images/jp/tsukune-step2.jpg","durationSeconds":180},{"stepNumber":3,"title":{"zh-TW":"煎烤定型並反覆刷醬","en":"Sear and Glaze with Sweet Tare","ja":"香ばしく焼き上げ、タレを重ね塗りする","ko":"노릇하게 굽고 타레 소스 덧바르기","th":"ย่างให้สุกแล้วทาซอสทาเระ"},"instruction":{"zh-TW":"平底鍋熱油或入氣炸鍋。先中火將兩面煎烤至表面泛金黃上色微焦（約6分鐘）。接著轉小火，刷上厚厚一層醬汁，翻面再烤1分鐘，重複刷醬2-3次直到醬汁焦糖化發亮。","en":"Sear in pan or grill on medium heat until golden and set (about 6 mins). Lower heat, brush generously with tare sauce, flip and cook 1 min. Repeat glazing 2-3 times until richly caramelized.","ja":"フライパンまたはグリルで両面をきつね色になるまで香ばしく焼きます。火を弱め、タレをたっぷりと塗りながら照りが出るまで2〜3回重ね焼きします。","ko":"팬이나 그릴에 올려 중불로 노릇하게 굽습니다(약 6분). 약불로 줄이고 타레 소스를 넉넉히 발라가며 윤기가 날 때까지 2~3회 반복해서 굽습니다.","th":"ย่างบนกระทะด้วยไฟกลางจนผิวเริ่มเหลืองกรอบ (ประมาณ 6 นาที) จากนั้นหรี่ไฟลง ทาซอสทาเระให้ทั่ว พลิกกลับด้านแล้วทาซ้ำ 2-3 ครั้งจนซอสเคลือบเงาสวย"},"image":"/images/jp/tsukune-step3.jpg","durationSeconds":420,"cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 190°C (375°F) for 10 mins","instructionOverride":{"zh-TW":"氣炸鍋鋪烘焙紙，190°C 烤8分鐘後取出刷濃醬汁，200°C 續炸2分鐘收汁上色。","en":"Air fry at 190°C for 8 mins, brush generously with tare sauce, then finish at 200°C for 2 mins.","ja":"ノンフライヤー190℃で8分焼き、タレを塗ってから200℃で2分仕上げ焼きします。","ko":"에어프라이어 190도에서 8분간 구운 후 소스를 듬뿍 바르고 200도에서 2분간 더 구워줍니다.","th":"หม้อทอดไร้น้ำมัน 190°C ย่าง 8 นาที นำออกมาทาซอส แล้วอบต่อที่ 200°C อีก 2 นาที"}}],"dangerWarnings":{"zh-TW":"刷上甜醬後糖分極易燒焦，火候必須轉小，注意頻繁翻動。","en":"Tare contains high sugar; keep heat low after glazing to avoid burning.","ja":"タレを塗った後は焦げやすいため、弱火にして手早く返してください。","ko":"소스를 바른 후에는 당분 때문에 타기 쉬우므로 불을 줄이고 자주 뒤집어주세요.","th":"ซอสมีน้ำตาลสูง ระวังไหม้ ควรรักษาไฟให้อ่อนและพลิกบ่อยๆ"}},{"stepNumber":4,"title":{"zh-TW":"擺盤並附上鮮蛋黃","en":"Plate with Raw Egg Yolk and Seven Spice","ja":"卵黄と七味を添えて完成","ko":"노른자와 시치미를 곁들여 완성","th":"จัดจานเสิร์ฟพร้อมไข่แดงสดและชิชิมิ"},"instruction":{"zh-TW":"將肉丸串盛盤，灑上七味粉。小碟中盛裝一顆生食級新鮮蛋黃，撒上蔥花。吃的時候將熱騰騰的肉丸按破蛋黃均勻裹滿！","en":"Arrange skewers on a plate, dust with shichimi togarashi. Serve alongside a ramekin with pasteurized egg yolk. Dip deeply and enjoy hot!","ja":"器に盛り付け、七味唐辛子を振ります。小鉢に入れた濃厚な卵黄をたっぷり絡めてお召し上がりください。","ko":"접시에 담고 시치미를 살짝 뿌립니다. 작은 종지에 계란 노른자를 담아 따뜻한 츠쿠네를 듬뿍 찍어 드세요.","th":"จัดวางบนจาน โรยพริกชิชิมิ เสิร์ฟคู่กับถ้วยไข่แดงสด จิ้มทานร้อนๆ ได้รสชาติเข้มข้นกลมกล่อม"},"image":"/images/jp/tsukune-step4.jpg","durationSeconds":60}],"troubleshooting":[{"id":"tb-1","problem":{"zh-TW":"肉丸烤的時候從竹籤上脫落滑掉？","en":"Why do the meatballs slide off the bamboo skewer?","ja":"焼いている途中でつくねが串から外れてしまう","ko":"구울 때 고기 완자가 꼬치에서 떨어지는 경우","th":"ทำไมลูกชิ้นไก่ถึงหลุดออกจากไม้เสียบขณะย่าง?"},"cause":{"zh-TW":"肉餡攪拌時間不夠，未產生足夠的肉膠質；或者竹籤太細光滑。","en":"Under-kneading so protein did not bind; or using round slippery skewers instead of flat bamboo.","ja":"練り込み不足で粘りが出ていないか、丸串を使用していることが原因です。","ko":"고기를 덜 치대서 끈기가 부족하거나 둥근 꼬치를 사용했기 때문입니다.","th":"นวดไก่ไม่นานพอจนโปรตีนไม่เหนียว หรือใช้ไม้เสียบทรงกลมที่ลื่นเกินไป"},"solution":{"zh-TW":"務必攪拌至發白有黏性；使用「扁平竹籤 (平串)」，穿籤後捏緊兩頭。","en":"Knead until sticky; use wide flat skewers and pinch both ends tightly.","ja":"白っぽく粘りが出るまでしっかり練り、平串を使って両端をギュッと押さえましょう。","ko":"하얗게 끈기가 생길 때까지 충분히 치대고 납작한 대나무 꼬치를 사용하세요.","th":"นวดจนเนื้อเหนียวเป็นกาว และเลือกใช้ไม้ไผ่ทรงแบนเพื่อยึดเกาะได้ดีขึ้น"}}],"proTips":[{"zh-TW":"雞軟骨是靈魂！如果能在日本超市買到「ヤゲン軟骨 (胸骨脆骨)」，切碎後口感最爽脆。","en":"Yagen cartilage (breastbone cartilage) provides the ultimate izakaya-style crunch.","ja":"ヤゲン軟骨を細かく刻んで加えると、本場の居酒屋さながらのコリコリ感が楽しめます。","ko":"야겐 난코츠(가슴 연골)를 잘게 다져 넣으면 현지 이자카야의 오독오독한 식감을 완벽 재현할 수 있습니다.","th":"ใช้กระดูกอ่อนส่วนอกไก่สับละเอียด จะได้สัมผัสกรุบกรอบเหมือนกินที่ร้านอิซากายะแท้ๆ"},{"zh-TW":"自製 Tare 醬汁冷卻後會變稠，刷在剛出鍋的熱肉丸上會形成玻璃般的光澤外衣。","en":"Tare sauce thickens as it cools, creating a lacquered glossy sheen over the hot chicken.","ja":"タレを煮詰めてとろみをつけておくと、焼き上がりに美しい照りが出ます。","ko":"타레 소스를 약간 걸쭉하게 졸여두면 갓 구운 고기에 윤기 나는 글레이즈가 완성됩니다.","th":"เคี่ยวซอสทาเระให้ข้นเล็กน้อย เมื่อทาบนไก่ย่างร้อนๆ จะเงาวาวน่ารับประทาน"}]}];
